    if ((blockedAhead || state.stallT > stallTime) && e.t - (state.lastReplanT || -9) > 0.6) {
      // pushing against something the costmap does not show: mark the spot ahead (in the driving direction) as occupied
      if (!blockedAhead && input.environment && input.environment.isTouchingSide) markContact(cur.g, true)
      var fix = plan(maxExpFull)
      state.lastReplanT = e.t
      state.stallT = 0
      state.replans++
      if (fix.segs.length > 0) {
        begin(fix)
        state.prevGear = cur.g
        cur = state.segs[0]
        travelled = 0
      }
    }
  }
  // hand back once the rest of the plan starts with a long forward run
  var fwdRun = 0
  // (also from the first segment: a plan that simply starts with a long forward run is a route, not a manoeuvre — creeping
  // along it at manoeuvre speed with open-loop segments is what made the car shuttle back and forth next to obstacles)
  for (var si = state.idx; si < state.segs.length && state.segs[si].g > 0; si++) fwdRun += state.segs[si].len
  fwdRun -= travelled
  var aheadFree = false
  if (fwdRun >= handback && cur.g > 0) {
    // the car must really have room ahead on its own heading, not just a plan that will get there
    var aHit = makeHit(av.points || [], ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + planMargin, ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + planMargin)
    aheadFree = true
    for (var ad = 0; ad <= handback && aheadFree; ad += 1) {
      // along the current segment's arc (what the local planner would also pick), not just straight on
      var ath = cur.k * ad
      var ax = Math.abs(cur.k) < 1e-6 ? ad : Math.sin(ath) / cur.k
      var ay = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(ath)) / cur.k
      var apx = pos[0] + e.fwd[0] * ax + e.left[0] * ay
      var apz = pos[2] + e.fwd[2] * ax + e.left[2] * ay
      if (aHit(apx, apz, e.fwd[0] * Math.cos(ath) + e.left[0] * Math.sin(ath), e.fwd[2] * Math.cos(ath) + e.left[2] * Math.sin(ath))) aheadFree = false
    }
  }
  if (aheadFree) {
    state.active = false
    state.route = undefined
    return {}
  }
  var finished = state.segStart !== null && travelled >= cur.len - 0.25
  if (finished) {
    state.prevGear = cur.g
    if (state.idx + 1 >= state.segs.length || deviates(cur)) {
      var again = plan(maxExpFull)
      state.replans++
      if (again.segs.length === 0 || state.idx + 1 >= state.segs.length) {
        state.active = false
        state.route = undefined
        if (again.segs.length === 0) return {}
      }
      if (again.segs.length > 0 && state.active) {
        begin(again)
        state.prevGear = cur.g
      }
    } else {
      state.idx++
      state.segStart = null
    }
    if (!state.active) return {}
    cur = state.segs[state.idx]
    travelled = 0
  }
  if (params.debugDraw !== false && state.path) {
    var py = pos[1]
    for (var pi = 2; pi < state.path.length; pi += 2) {
      api.visualizeLine([state.path[pi - 2][0], py, state.path[pi - 2][1]], [state.path[pi][0], py, state.path[pi][1]], '#ff44ff')
    }
    if (cur.end) api.visualizeLine(pos, [cur.end.x, py, cur.end.z], '#ff8800')
    api.visualizeLine([pos[0], py + 1.2, pos[2]], [pos[0], py + 4, pos[2]], '#ff44ff')
  }
  var remain = state.segStart ? Math.max(0, cur.len - travelled) : cur.len
  var vMax = Math.min(vMan, 0.9 + Math.sqrt(2 * 3 * remain))
  // waiting for rest before a gear change: demand zero. Once the segment has started but the car still rolls the other
  // way (momentum from the previous segment; an icy car does not stop by itself and a zero-demand brake is below the
  // actuator deadband), drive in the demanded direction: that brakes it hard and turns it around.
  var waitingForRest = state.segStart === null
  var rollingWrong = !waitingForRest && cur.g * e.speed < -0.35
  av.override = { kappa: cur.k, vDesired: waitingForRest ? 0 : rollingWrong ? cur.g * Math.min(vMax, 2.5) : cur.g * vMax }
  av.mode = 'maneuver'
  api.watch('av.maneuver', 'seg ' + state.idx + '/' + state.segs.length + ' g' + cur.g + ' k' + cur.k.toFixed(3) + ' replans ' + state.replans)
  return {}
}

// AV stack · PLAN / local motion planner (sampling-based, receding horizon).
// Candidate paths = constant-curvature turn (limited turn angle) followed by a straight, so a path can
// swing around an obstacle and then run alongside it. Each path is swept with the vehicle footprint
// (margin grows with speed) against the costmap. Cost = progress to goal, heading, required stopping
// length, clearance, smoothness. Publishes av.plan {kappa, free, freeSoft, clearance, blocked, horizon}.
// debug draw: yellow = line to goal / route carrot, dark blue = candidate fan, green = chosen path, orange = where it would hit.
// params: vehicleWidth, vehicleLength, safetyMargin, marginSpeedGain, softMargin, maxCurvature, arcCount,
//         horizonMin, horizonGain, horizonMax, comfortDecel, wProgress, wHeading, wRequired, wFree, wSoft,
//         wSmooth, wTurn, minFree, rearIgnore, marginRamp (m over which the margin grows from the current clearance), debugDraw
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) {
    av.plan = { kappa: 0, free: 0, freeSoft: 0, clearance: 0, blocked: false, horizon: 0, noGoal: true }
    return {}
  }
  var pos = input.position
  var tdx = tgt[0] - pos[0]
  var tdz = tgt[2] - pos[2]
  av.goal = { x: tgt[0], z: tgt[2], dist: Math.sqrt(tdx * tdx + tdz * tdz) }
  // manoeuvre planner owns the controls (multi-point turn): pass its command through
  if (av.override) {
    av.plan = { kappa: av.override.kappa, vDesired: av.override.vDesired, free: 99, freeSoft: 99, clearance: 9, blocked: false, horizon: 0, override: true }
    return {}
  }
  // chase the route's carrot (global plan) when there is one, else the raw goal
  var aim = av.carrot ? [av.carrot[0], 0, av.carrot[1]] : tgt
  var gdx = aim[0] - pos[0]
  var gdz = aim[2] - pos[2]
  var gx = gdx * e.fwd[0] + gdz * e.fwd[2]
  var gy = gdx * e.left[0] + gdz * e.left[2]
  var goalDist = Math.sqrt(gx * gx + gy * gy)

  var v = Math.max(0, e.speedF)
  var margin = (params.safetyMargin != null ? params.safetyMargin : 0.5) + (params.marginSpeedGain != null ? params.marginSpeedGain : 0.05) * v
  var soft = params.softMargin != null ? params.softMargin : 1.1
  var halfW = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + margin
  var halfL = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + margin
  var kmax = params.maxCurvature || 0.115
  var count = params.arcCount || 31
  var hMin = params.horizonMin != null ? params.horizonMin : 10
  var aBrake = params.comfortDecel || 5
  // The planning horizon has to cover the stopping distance of the speed we want to drive, otherwise the free-path
  // limit (sqrt(2 * decel * horizon)) silently caps cruiseSpeed (26 m / 5 m/s^2 = 15.8 m/s).
  var cruiseV = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var hMax = params.horizonMax != null ? params.horizonMax : Math.min(150, Math.max(26, 1.1 * ((cruiseV * cruiseV) / (2 * aBrake)) + 10))
  var H = Math.min(hMax, hMin + Math.max((params.horizonGain != null ? params.horizonGain : 1.2) * v, (1.1 * v * v) / (2 * aBrake)))
  var Lreq = Math.min(H, (v * v) / (2 * aBrake) + 5)
  var wProg = params.wProgress != null ? params.wProgress : 1.0
  var wHead = params.wHeading != null ? params.wHeading : 2.0
  var wReq = params.wRequired != null ? params.wRequired : 60
  var wFree = params.wFree != null ? params.wFree : 10
  var wSoft = params.wSoft != null ? params.wSoft : 8
  var wSmooth = params.wSmooth != null ? params.wSmooth : 2.5
  var wTurn = params.wTurn != null ? params.wTurn : 1.5
  var minFree = params.minFree != null ? params.minFree : 4.5
  var ds = 0.75
  var turnAngles = [0.5, 1.15]

  // costmap into ego frame
  var pts = av.points || []
  var ox = []
  var oy = []
  for (var i = 0; i < pts.length; i++) {
    var dx = pts[i][0] - pos[0]
    var dz = pts[i][1] - pos[2]
    var px = dx * e.fwd[0] + dz * e.fwd[2]
    var py = dx * e.left[0] + dz * e.left[2]
    if (px > -halfL - soft - 3 && px < H + halfL + soft + 3 && py > -H - 4 && py < H + 4) {
      ox.push(px)
      oy.push(py)
    }
  }

  // pose along a path: turn at `kappa` for `turnLen`, then straight
  function poseAt(kappa, turnLen, s, out) {
    var sa = s < turnLen ? s : turnLen
    var th = kappa * sa
    var x
    var y
    if (Math.abs(kappa) < 1e-6) {
      x = sa
      y = 0
    } else {
      x = Math.sin(th) / kappa
      y = (1 - Math.cos(th)) / kappa
    }
    if (s > turnLen) {
      x += Math.cos(th) * (s - turnLen)
      y += Math.sin(th) * (s - turnLen)
    }
    out.x = x
    out.y = y
    out.th = th
  }
  var P = { x: 0, y: 0, th: 0 }

  // forward paths only sweep the front of the footprint: an obstacle already behind/at the tail (touching
  // start pose) must not veto driving away from it
  var rearIgnore = params.rearIgnore != null ? params.rearIgnore : 1.4
  // Start already inside the margin (parked next to a car / wall): the full margin would veto every path at s = 0 and
  // freeze the car. The margin therefore starts at the clearance the car has now and grows to the full value over
  // `marginRamp` metres — a path may not get closer than the car already is, but it may drive away.
  var hullL = halfL - margin
  var hullW = halfW - margin
  var startGap = margin + soft
  for (var sg = 0; sg < ox.length; sg++) {
    if (ox[sg] < -hullL + rearIgnore - margin) continue
    var gap = Math.max(Math.abs(ox[sg]) - hullL, Math.abs(oy[sg]) - hullW)
    if (gap < startGap) startGap = gap
  }
  var ramp = params.marginRamp != null ? params.marginRamp : 3
  function freeLength(kappa, turnLen, hw, hl) {
    var extra = hw - hullW
    var m0 = Math.max(0, Math.min(extra, startGap - 0.05))
    for (var s = 0; s <= H; s += ds) {
      var m = s >= ramp || m0 >= extra ? extra : m0 + ((extra - m0) * s) / ramp
      var hwS = hullW + m
      var hlS = hullL + m
      var hlRear = Math.max(0.3, hlS - rearIgnore)
      poseAt(kappa, turnLen, s, P)
      var ct = Math.cos(P.th)
      var st = Math.sin(P.th)
      for (var q = 0; q < ox.length; q++) {
        var rx = ox[q] - P.x
        var ry = oy[q] - P.y
        var lx = ct * rx + st * ry
        var ly = -st * rx + ct * ry
        if (lx > -hlRear && lx < hlS && ly > -hwS && ly < hwS) return Math.max(0, s - ds)
      }
    }
    return H
  }

  var prev = state.prevKappa || 0
  var prevTurn = state.prevTurn || 0
  var best = null
  var bestCost = Infinity
  var bestHard = 0
  var bestSoft = 0
  var bestTurnLen = 0
  var cand = []
  // Direct aim: turn at curvature `kappa` until the car points at the goal, then drive straight (shortest way when the
  // way is free). Returns the turn angle (rad), or 0 when the goal is on the other side / cannot be aimed at this way.
  function aimTurnAngle(kappa) {
    var ak = Math.abs(kappa)
    if (ak < 1e-6) return 0
    var gyS = kappa > 0 ? gy : -gy
    if (gyS <= 0.05 && gx > 0) return 0
    var prevF = null
    for (var th = 0.02; th <= Math.PI; th += 0.02) {
      var x = Math.sin(th) / ak
      var y = (1 - Math.cos(th)) / ak
      var f = Math.atan2(gyS - y, gx - x) - th
      while (f > Math.PI) f -= 2 * Math.PI
      while (f < -Math.PI) f += 2 * Math.PI
      if (prevF !== null && prevF > 0 && f <= 0) return th
      prevF = f
    }
    return 0
  }
  for (var a = 0; a < count; a++) {
    var kappa = count === 1 ? 0 : -kmax + (2 * kmax * a) / (count - 1)
    var aimAng = aimTurnAngle(kappa)
    var nAngles = turnAngles.length + (aimAng > 0 ? 1 : 0)
    for (var ti = 0; ti < nAngles; ti++) {
      if (Math.abs(kappa) < 1e-6 && ti > 0) continue
      var isAim = ti >= turnAngles.length
      var turnLen = Math.abs(kappa) < 1e-6 ? H : Math.min(H, (isAim ? aimAng : turnAngles[ti]) / Math.abs(kappa))
      var fHard = freeLength(kappa, turnLen, halfW, halfL)
      var fSoft = freeLength(kappa, turnLen, halfW + soft - margin, halfL + soft - margin)
      var L = fHard
      var Lpose = L
      if (isAim) {
        // judged where it reaches the goal (not far beyond it); free-length terms still use the full free path
        poseAt(kappa, turnLen, turnLen, P)
        Lpose = Math.min(L, turnLen + Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y)))
      }
      poseAt(kappa, turnLen, Lpose, P)
      var gdEnd = Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y))
      var progress = goalDist - gdEnd
      var herr = Math.atan2(gy - P.y, gx - P.x) - P.th
      while (herr > Math.PI) herr -= 2 * Math.PI
      while (herr < -Math.PI) herr += 2 * Math.PI
      var cost =
        -wProg * progress +
        wHead * Math.abs(herr) +
        wReq * Math.max(0, 1 - L / Lreq) +
        wFree * (1 - L / H) +
        wSoft * (1 - Math.min(fSoft, H) / H) +
        wSmooth * (Math.abs(kappa - prev) / kmax) +
        wTurn * Math.abs(kappa * turnLen)
      if (cost < bestCost) {
        bestCost = cost
        best = kappa
        bestHard = fHard
        bestSoft = fSoft
        bestTurnLen = turnLen
      }
      if (params.debugDraw !== false && a % 8 === 0 && ti === 0) cand.push([kappa, turnLen, fHard])
    }
  }
  state.prevKappa = best

  // lateral clearance of the chosen path over the distance that matters (beyond the hard margin)
  var clearance = 0
  var margins = [0.5, 1.0, 1.5, 2.5]
  var needLen = Math.min(bestHard, Lreq)
  for (var mi = 0; mi < margins.length; mi++) {
    var fm = freeLength(best, bestTurnLen, halfW + margins[mi], halfL + margins[mi])
    if (fm >= needLen - 1e-6) clearance = margins[mi]
    else break
  }

  av.plan = {
    kappa: best,
    free: bestHard,
    freeSoft: bestSoft,
    clearance: clearance,
    margin: margin,
    blocked: bestHard < minFree,
    startGap: startGap,
    horizon: H,
    required: Lreq,
    cost: bestCost,
  }
  api.watch('av.plan.kappa', Math.round(best * 1000) / 1000)
  api.watch('av.plan.free', Math.round(bestHard * 10) / 10 + ' clr ' + clearance)

  if (params.debugDraw !== false) {
    var y0 = pos[1]
    var W = { x: 0, y: 0, th: 0 }
    function world(x, y) {
      return [pos[0] + e.fwd[0] * x + e.left[0] * y, y0, pos[2] + e.fwd[2] * x + e.left[2] * y]
    }
    function drawPath(kk, tl, len, color, step) {
      var prevW = null
      for (var s = 0; s <= len + 1e-6; s += step) {
        poseAt(kk, tl, s, W)
        var wp = world(W.x, W.y)
        if (prevW) api.visualizeLine(prevW, wp, color)
        prevW = wp
      }
    }
    api.visualizeLine(pos, [aim[0], y0, aim[2]], '#ffcc00')
    for (var ci = 0; ci < cand.length; ci++) drawPath(cand[ci][0], cand[ci][1], cand[ci][2], '#3a5a9a', Math.max(4, cand[ci][2] / 3))
    drawPath(best, bestTurnLen, bestHard, '#22dd66', 2.5)
    if (bestHard < H) drawPath(best, bestTurnLen, Math.min(H, bestHard + 3), '#ff8800', 3)
  }
  return {}
}

// AV stack · PLAN / speed planner.
// v_des = min(cruise, obstacle in the path (auto-brake), obstacle right next to the car, route bends ahead, lateral acceleration, goal approach).
//  - In the path: auto-brake logic — v <= sqrt(2 * brakeDecel * (free distance - stopMargin)). Far obstacles only matter once they are within braking distance.
//  - Next to the car: only obstacles within `obstacleSlowRadius` (default 5 m) of the hull slow the car, linearly from `obstacleSlowFactor * cruiseSpeed` (touching) up to cruise (at the radius).
//    Obstacles that are farther away, or behind the car, never slow it. Set the radius to 0 to switch this off.
// Goal approach only slows for the FINAL waypoint (av.mission, else params.waypoints; otherwise every goal is final).
// The free-path (stopping distance) limit always wins over the floors.
// Publishes av.plan.vDesired / av.plan.vLimit ('cruise' | 'free' | 'near' | 'route' | 'curve' | 'goal').
// params: cruiseSpeed, minSpeed (lowest speed while driving, default 4), comfortDecel (brake decel for obstacles in the path, default 5),
//         stopMargin, obstacleSlowRadius (5), obstacleSlowFactor (speed right next to an obstacle as a fraction of cruise, default 0.5), maxLatAccel (default 9),
//         goalDecel (gentler braking used for the final approach, default 3), goalCrawlSpeed (floor while arriving, default 2), goalTolerance, vehicleWidth, vehicleLength, waypoints
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan) return {}
  var plan = av.plan
  if (plan.override) return {}
  var cruise = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var aBrake = params.comfortDecel || 5
  var aLat = params.maxLatAccel || 9
  var stopMargin = params.stopMargin != null ? params.stopMargin : 1.2
  var crawl = params.minSpeed != null ? params.minSpeed : params.crawlSpeed != null ? params.crawlSpeed : 4
  var limit = 'cruise'
  var v = cruise
  // obstacle in the path: auto-brake (free distance of the chosen path)
  var vFree = Math.sqrt(2 * aBrake * Math.max(0, plan.free - stopMargin))
  if (vFree < v) {
    v = vFree
    limit = 'free'
  }
  // obstacles right next to the car (hull distance), never farther than the slow radius, never behind
  var slowR = params.obstacleSlowRadius != null ? params.obstacleSlowRadius : 5
  if (slowR > 0 && av.points && av.points.length && av.ego) {
    var e = av.ego
    var hl = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2
    var hw = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2
    var pos = input.position
    var dn = Infinity
    for (var i = 0; i < av.points.length; i++) {
      var dx = av.points[i][0] - pos[0]
      var dz = av.points[i][1] - pos[2]
      var lx = dx * e.fwd[0] + dz * e.fwd[2]
      if (lx < -hl) continue // behind the rear: irrelevant for a forward-driving car
      var ly = dx * e.left[0] + dz * e.left[2]
      var ex = Math.max(Math.abs(lx) - hl, 0)
      var ey = Math.max(Math.abs(ly) - hw, 0)
      var d = Math.sqrt(ex * ex + ey * ey)
      if (d < dn) dn = d
    }
    if (dn < slowR) {
      var vNear = Math.max(crawl, (params.obstacleSlowFactor != null ? params.obstacleSlowFactor : 0.5) * cruise)
      var t = Math.min(1, Math.max(0, (dn - 0.3) / Math.max(0.01, slowR - 0.3)))
      var vProx = vNear + (cruise - vNear) * t
      if (vProx < v) {
        v = vProx
        limit = 'near'
      }
    }
  }
  // bends ahead on the global route (corner speed, reachable by braking)
  if (av.route && av.route.vLimit < v) {
    v = Math.max(av.route.vLimit, crawl)
    limit = 'route'
  }
  var k = Math.abs(plan.kappa)
  if (k > 1e-4) {
    var vCurve = Math.sqrt(aLat / k)
    if (vCurve < v) {
      v = Math.max(vCurve, crawl)
      limit = 'curve'
    }
  }
  if (av.goal) {
    var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
    var wps = params.waypoints
    var isFinal = true
    if (av.mission) {
      isFinal = av.mission.isFinal
    } else if (wps && wps.length) {
      var last = wps[wps.length - 1]
      isFinal = Math.abs(av.goal.x - last[0]) < 0.05 && Math.abs(av.goal.z - last[1]) < 0.05
    }
    if (isFinal) {
      var vGoal = Math.sqrt(2 * (params.goalDecel != null ? params.goalDecel : 3) * Math.max(0, av.goal.dist - tol))
      if (vGoal < v) {
        // arriving: creep in slowly enough to stop inside the hold radius (own, lower floor than the driving minimum)
        v = Math.max(vGoal, params.goalCrawlSpeed != null ? params.goalCrawlSpeed : 2)
        limit = 'goal'
      }
    }
  }
  if (!plan.blocked && v < crawl && limit !== 'goal') v = crawl
  // The stopping-distance limit is a safety bound, not a preference: no floor (minSpeed, route/curve crawl, goal crawl)
  // may lift the speed above what can still stop within the free path (minSpeed 9.4 with 5 m free and 2 m/s² used to
  // drive at 9.4 instead of 3.9 m/s — straight into the AEB, then stop-and-go).
  if (v > vFree) {
    v = vFree
    limit = 'free'
  }
  plan.vDesired = v
  plan.vLimit = limit
  api.watch('av.vLimit', limit + ' ' + v.toFixed(1))
  return {}
}

// AV stack · PLAN / behaviour supervisor.
// Watches planner health and flags `av.needManeuver` when the local planner is blocked
// or the vehicle is stuck; holds at the final goal. Sets av.mode ('drive' | 'hold').
// debug draw: vertical mast above the car = status (green drive, orange needs manoeuvre, white hold).
// Simulated time only. params: stuckTime, blockedTime, holdAtGoal, goalTolerance
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var plan = av.plan
  if (state.stuckT === undefined) {
    state.stuckT = 0
    state.blockedT = 0
  }
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var blockedTime = params.blockedTime != null ? params.blockedTime : 0.4
  var wantsMove = (plan.vDesired || 0) > 0.8
  if (wantsMove && Math.abs(e.speed) < 0.25) state.stuckT += dt
  else state.stuckT = 0
  if (plan.blocked && Math.abs(e.speed) < 1.2) state.blockedT += dt
  else state.blockedT = 0
  av.needManeuver = state.blockedT > blockedTime || state.stuckT > stuckTime
  av.mode = av.override ? 'maneuver' : 'drive'
  var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
  var finalGoal = !av.mission || av.mission.isFinal
  if (params.holdAtGoal !== false && finalGoal && av.goal && av.goal.dist < tol) {
    av.mode = 'hold'
    plan.override = false
    plan.vDesired = 0
    plan.kappa = 0
  }
  if (params.debugDraw !== false) {
    // status mast above the car: green drive, orange manoeuvre requested, white hold
    var c = av.mode === 'hold' ? '#ffffff' : av.needManeuver ? '#ff8800' : '#00ff66'
    api.visualizeLine([e.pos[0], e.pos[1] + 1.2, e.pos[2]], [e.pos[0], e.pos[1] + 4, e.pos[2]], c)
  }
  return {}
}

// AV stack · CONTROL / lateral (curvature tracking).
// steering = feed-forward(kappa_plan / kappaPerSteer) + P feedback on measured curvature,
// with a steering-rate limiter (comfort / actuator model).
// debug draw: white = commanded steering direction.
// params: kappaPerSteer, fbGain, steerRate
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var kps = params.kappaPerSteer || 0.12
  var fb = params.fbGain != null ? params.fbGain : 0.35
  var rate = params.steerRate != null ? params.steerRate : 4
  var kCmd = av.plan.kappa
  var steer = kCmd / kps
  if (Math.abs(e.speed) > 2 && av.mode !== 'reverse') {
    steer += (fb * (kCmd - e.kappa)) / kps
  }
  if (steer > 1) steer = 1
  if (steer < -1) steer = -1
  var prev = state.steer || 0
  var maxStep = rate * dt
  if (steer > prev + maxStep) steer = prev + maxStep
  if (steer < prev - maxStep) steer = prev - maxStep
  state.steer = steer
  // car2 treats exactly 0 as "no steering command" (wheel re-centres on its own)
  input.actions.steering_angle = Math.abs(steer) < 1e-4 ? 0 : steer
  av.cmdSteer = steer
  if (params.debugDraw !== false) {
    // white: commanded steering direction from the nose (4 m chord)
    var th = steer * kps * 4
    var nose = api.vec.offsetAlong(input.position, e.fwd, 2)
    var dir = [e.fwd[0] * Math.cos(th) + e.left[0] * Math.sin(th), 0, e.fwd[2] * Math.cos(th) + e.left[2] * Math.sin(th)]
    api.visualizeLine(nose, api.vec.offsetAlong(nose, dir, 4), '#ffffff')
  }
  return {}
}

// AV stack · CONTROL / longitudinal (model-based speed control with an online-identified actuator model).
// The car2 actuator turns a command u = throttle − brake into a force, so the body follows
//     a = G · u − D · sgn(v)          (G: m/s² per unit command, D: sliding/rolling friction deceleration, m/s²)
// G and D differ by orders of magnitude between bodies (reference car: G ≈ 156, D ≈ 60; a light icy car with power 2400:
// G ≈ 1200, D ≈ 1). A fixed deadband / gain only fits one of them — on the other the smallest command jumps the speed by
// metres per second per frame and the controller bang-bangs (the "jitter"). So G and D are estimated online (recursive
// least squares on the previous frame's command vs. the measured acceleration) and the controller asks for an
// acceleration: u = (a_des + D · s) / G, a_des = clamp((v_target − v) / tau + I, −maxDecel, maxAccel).
// Publishes av.actuator {G, D, u} (u = applied command; a later stage that overrides the actions must update it — the AEB does). The AEB uses it to brake with a deceleration instead of a raw command) and av.cmd.
// At rest the static friction can exceed D: a breakaway offset ramps while demanded motion does not start.
// params: tau, ki, maxAccel, maxDecel, maxThrottle, maxBrake, breakawayRate, gainInit, frictionInit, forget
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var vDes = av.plan.vDesired || 0
  var tau = params.tau != null ? params.tau : 0.35
  var ki = params.ki != null ? params.ki : 0.6
  var maxAcc = params.maxAccel != null ? params.maxAccel : 10
  var maxDec = params.maxDecel != null ? params.maxDecel : 12
  var maxThr = params.maxThrottle != null ? params.maxThrottle : 1
  var maxBrk = params.maxBrake != null ? params.maxBrake : 1
  var lam = params.forget != null ? params.forget : 0.97
  var v = e.speed
  if (state.G === undefined) {
    state.G = params.gainInit != null ? params.gainInit : 156
    state.D = params.frictionInit != null ? params.frictionInit : 60
    // RLS covariance over [G, D]
    state.P = [1e4, 0, 0, 1e3]
    state.uPrev = 0
    state.vPrev = v
    state.I = 0
    state.boost = 0
    state.samples = 0
  }
  // --- identify: last frame's command produced this frame's acceleration ---
  // a later stage (AEB) that overrode the command reports what was really applied in last frame's av.actuator.u
  if (state.lastAct && typeof state.lastAct.u === 'number') state.uPrev = state.lastAct.u
  var aMeas = dt > 1e-6 ? (v - state.vPrev) / dt : 0
  var vMid = 0.5 * (v + state.vPrev)
  var pushing = input.environment && input.environment.isTouchingSide
  // (sliding friction acts as soon as the body slides: learn from 0.12 m/s on, so a car creeping in force balance is not
  // stuck between 'too slow to learn' and 'too fast for the breakaway push')
  if (!pushing && Math.abs(state.uPrev) > 1e-4 && Math.abs(vMid) > 0.12 && state.vPrev * v > 0) {
    var x0 = state.uPrev
    var x1 = -(vMid > 0 ? 1 : -1)
    var P = state.P
    var px0 = P[0] * x0 + P[1] * x1
    var px1 = P[2] * x0 + P[3] * x1
    var den = lam + x0 * px0 + x1 * px1
    var k0 = px0 / den
    var k1 = px1 / den
    var err = aMeas - (state.G * x0 + state.D * x1)
    // robust: a collision / kerb spike must not wreck the model
    var lim = 50 + 0.5 * Math.abs(state.G * x0)
    if (err > lim) err = lim
    if (err < -lim) err = -lim
    state.G = Math.max(10, Math.min(20000, state.G + k0 * err))
    state.D = Math.max(0, Math.min(300, state.D + k1 * err))
    var n0 = (P[0] - k0 * px0) / lam
    var n1 = (P[1] - k0 * px1) / lam
    var n2 = (P[2] - k1 * px0) / lam
    var n3 = (P[3] - k1 * px1) / lam
    // keep the covariance bounded (forgetting without excitation blows it up)
    state.P = [Math.min(n0, 1e5), n1, n2, Math.min(n3, 1e4)]
    state.samples++
  }
  // Rescue path: the command clearly dominates friction and the response is far larger than the model predicts
  // (G underestimated — e.g. learned while pushing against a slope, or while the speed sign flipped every frame, where
  // the RLS is gated off). Pull G towards the observed gain directly so the controller stops saturating.
  // Only for a saturated command (that is the failure mode); collisions also produce big accelerations and must not pump G.
  if (!pushing && Math.abs(state.uPrev) > 0.3 && aMeas * state.uPrev > 0 && Math.abs(aMeas) > 3 * state.D + 10) {
    var gObs = Math.abs(aMeas / state.uPrev)
    if (gObs > 1.5 * state.G) state.G = Math.min(20000, state.G + 0.3 * (gObs - state.G))
  }
  var G = state.G
  var D = state.D

  // --- control ---
  var u = 0
  var holding = Math.abs(vDes) < 0.05 && Math.abs(v) < 0.3
  if (holding) {
    state.I = 0
    state.boost = 0
  } else {
    var errV = vDes - v
    // integral (acceleration units) only while not saturated, so steady errors (slope, model error) vanish
    var aDes = errV / tau + state.I
    if (aDes > maxAcc) aDes = maxAcc
    if (aDes < -maxDec) aDes = -maxDec
    if (aDes > -maxDec && aDes < maxAcc) state.I = Math.max(-3, Math.min(3, state.I + ki * errV * dt))
    // never brake through zero within one frame: the deceleration that stops the car this frame is the most we ask for
    if (Math.abs(vDes) < 0.05) {
      var stopA = Math.abs(v) / Math.max(dt, 1e-3)
      if (v > 0 && aDes < -stopA) aDes = -stopA
      if (v < 0 && aDes > stopA) aDes = stopA
    }
    // friction feed-forward in the direction of travel (at rest: of the wanted motion)
    var s = Math.abs(v) > 0.3 ? (v > 0 ? 1 : -1) : aDes > 0 ? 1 : aDes < 0 ? -1 : 0
    var fric = D * s
    // at rest, friction helps braking: no reverse push needed to stay stopped
    if (Math.abs(v) <= 0.3 && Math.abs(vDes) < 0.05) fric = 0
    u = (aDes + fric) / G
    // breakaway: demanded motion does not start (static friction > D) -> ramp an extra push
    var want = Math.abs(vDes) > 0.3
    // far below the demanded speed and not gaining (static friction / force balance the model does not explain yet)
    var stuck = want && vDes * v < Math.min(1, 0.4 * Math.abs(vDes)) && vDes * aDes > 0 && aMeas * (vDes > 0 ? 1 : -1) < 0.5
    if (stuck) state.boost = Math.min(1, state.boost + (params.breakawayRate != null ? params.breakawayRate : 0.5) * dt)
    // keep the push until the car really drives (else it jerks, stops, ramps again); then relax it slowly
    else if (!want || vDes * v >= Math.min(1, 0.4 * Math.abs(vDes))) state.boost = Math.max(0, state.boost - 0.5 * dt)
    if (state.boost > 0 && want) u += (vDes > 0 ? 1 : -1) * state.boost
    // stopping: never push along the direction of travel (friction alone may decelerate harder than maxDecel — fine)
    if (Math.abs(vDes) < 0.05 && u * v > 0) u = 0
  }
  if (u > maxThr) u = maxThr
  if (u < -maxBrk) u = -maxBrk
  state.uPrev = u
  state.vPrev = v
  input.actions.throttle = u > 0 ? u : 0
  input.actions.brake = u < 0 ? -u : 0
  // mailbox: stages after this one write the command they actually applied into av.actuator.u
  av.actuator = { G: G, D: D, samples: state.samples, u: u }
  state.lastAct = av.actuator
  av.cmd = { throttle: input.actions.throttle, brake: input.actions.brake }
  api.watch('av.throttle', 'u ' + u.toFixed(3) + ' G ' + G.toFixed(0) + ' D ' + D.toFixed(1) + ' vd ' + vDes.toFixed(1))
  return {}
}

// AV stack · SAFETY / autonomous emergency braking (independent monitor, own sensing).
// Runs after control and may only reduce throttle / add brake. Uses a smaller margin while the manoeuvre planner is driving (it already keeps swept clearance).
// Brakes with a deceleration (aebDecel), turned into a command with the actuator model the longitudinal stage identified
// (av.actuator {G, D}): a raw brake value means 360 m/s² on a light, powerful car and flips its speed within a frame.
// Footprint from av.vehicle (look-ahead starts at the nose, spread covers the body width).
// debug draw: dark gold = AEB look-ahead, red = AEB triggered.
// params: aebDecel, aebMargin, aebHalfWidth
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  if (e.speed < 0.8) {
    av.aeb = false
    return {}
  }
  var a = params.aebDecel || 7
  var margin = params.aebMargin != null ? params.aebMargin : 1.0
  if (av.mode === 'maneuver') margin = 0.2
  var len = (av.vehicle && av.vehicle.length) || params.vehicleLength || 4
  var wid = (av.vehicle && av.vehicle.width) || params.vehicleWidth || 2
  var hw = params.aebHalfWidth != null ? params.aebHalfWidth : Math.max(0.9, wid / 2 - 0.1)
  var need = (e.speed * e.speed) / (2 * a) + margin
  var origin = api.vec.offsetAlong(input.position, e.fwd, len / 2 + 0.3)
  var hit = api.raycastSpread(origin, e.fwd, need + 1, hw, 5, { visualize: false })
  av.aeb = false
  var drawOn = params.debugDraw !== false
  if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, need), '#b8860b')
  if (hit.hit && hit.distance < need) {
    if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, hit.distance), '#ff0000')
    av.aeb = true
    // deceleration needed to stop before the hit (at least aebDecel), never more than stops the car within this frame
    var room = Math.max(0.1, hit.distance - 0.2 * margin)
    var dec = Math.max(a, (e.speed * e.speed) / (2 * room))
    dec = Math.min(dec, e.speed / Math.max(dt, 1e-3))
    var act = av.actuator
    var u
    if (act && act.G > 0) u = (-dec + act.D) / act.G
    else u = -Math.min(1, 0.3 + (need - hit.distance) / need)
    var cur = (input.actions.throttle || 0) - (input.actions.brake || 0)
    if (u < cur) {
      input.actions.throttle = u > 0 ? u : 0
      input.actions.brake = u < 0 ? Math.min(1, -u) : 0
      // tell the longitudinal controller what was really applied (its actuator identification)
      if (act) act.u = input.actions.throttle - input.actions.brake
    }
    api.watch('av.aeb', Math.round(hit.distance * 10) / 10 + ' m dec ' + dec.toFixed(1))
  }
  return {}
}

// AV stack · SENSE / state estimation ("localization" layer).
// Publishes the ego state on the shared blackboard `input.av.ego` for all later stages.
// Also publishes av.vehicle {width, length, height} = max(params, own box collider) used by all planners.
// debug draw (params.debugDraw, default true): cyan = velocity vector.
// Owns the simulated clock (state.t) so no downstream stage needs a wall clock.
function transform(input, dt, params, state, api) {
  // fresh blackboard every frame (the input object is reused by the runtime)
  var av = (input.av = {})
  // a goal source running in front of this stage hands its mission over via input.goalSource (see av-wander.js)
  if (input.goalSource) {
    av.mission = input.goalSource
    input.goalSource = undefined
  }
  // Goal contract: a source that declares `input.target.isFinal === false` (preset wanderer, ...) makes the stack cruise
  // through its goals instead of braking at each one. (Sources without that flag are single, final goals.)
  if (!av.mission && input.target && input.target.pose && input.target.isFinal === false) {
    var tp = input.target.pose.position
    av.mission = { index: 0, waypoints: [[tp[0], tp[2]]], isFinal: false }
  }
  if (state.t === undefined) {
    state.t = 0
    state.speedF = 0
    state.prevSpeed = 0
    state.accelF = 0
  }
  state.t += dt
  // Vehicle footprint: never plan with a hull smaller than the entity's own box collider (a 4 x 8 m body driven with the
  // 2 x 4 defaults touches every neighbour). params.vehicleWidth / vehicleLength can only enlarge it. Cached (getEntity copies).
  if (state.vehT === undefined || state.t - state.vehT > 2) {
    state.vehT = state.t
    var ent = api.getEntity(input.entityId)
    var sh = ent && ent.shape
    var sc = (ent && ent.scale) || [1, 1, 1]
    state.vehW = sh && sh.type === 'box' ? Math.abs(sh.width * (sc[0] || 1)) : 0
    state.vehL = sh && sh.type === 'box' ? Math.abs(sh.depth * (sc[2] || 1)) : 0
    state.vehH = sh && sh.type === 'box' ? Math.abs(sh.height * (sc[1] || 1)) : 0
  }
  av.vehicle = {
    width: Math.max(params.vehicleWidth || 2, state.vehW || 0),
    length: Math.max(params.vehicleLength || 4, state.vehL || 0),
    height: state.vehH || 0,
  }
  var up = api.getUpVector(input.rotation)
  var fwd = api.vec.normalize(api.vec.projectOntoPlane(api.getForwardVector(input.rotation), up))
  var left = api.vec.normalize(api.vec.cross(up, fwd))
  var speed = api.vec.getForwardSpeed(input.velocity, fwd)
  var yawRate = api.vec.dot(input.angularVelocity, up)
  var a = dt > 1e-6 ? (speed - state.prevSpeed) / dt : 0
  state.prevSpeed = speed
  state.accelF += (a - state.accelF) * Math.min(1, dt * 8)
  state.speedF += (speed - state.speedF) * Math.min(1, dt * 20)
  av.ego = {
    t: state.t,
    dt: dt,
    pos: input.position,
    fwd: fwd,
    left: left,
    up: up,
    speed: speed,
    speedF: state.speedF,
    accel: state.accelF,
    yawRate: yawRate,
    kappa: Math.abs(speed) > 1.5 ? yawRate / speed : 0,
  }
  api.watch('av.speed', Math.round(speed * 10) / 10)
  if (params.debugDraw !== false) {
    // cyan: velocity vector
    api.visualizeLine(input.position, api.vec.add(input.position, api.vec.scale(input.velocity, 0.6)), '#00e5ff')
  }
  return {}
}

// AV stack · SENSE / perception.
// 360° range-scan ring (lidar-like, mounted at the vehicle centre, rays start on the hull)
// + obstacle memory ("local costmap") so the planners also know what is behind / beside.
// Publishes: av.scan {angles, ranges, range}, av.points [[x,z],...] (world), av.rearClear.
// debug draw (params.debugDraw, debugRayStride, debugMaxPoints): red = lidar hit rays, magenta ticks = costmap points.
// Extra ray plane at the car's top edge (params.rayLevels false = off); params.lowRayClearance (m above the underside) adds a low plane.
// Memory clearing: remembered cells that fresh rays pass through (within memClearRange 45 m, 0 = off) are dropped, so moving obstacles leave no ghost trail.
// params: drivableArea [xmin, xmax, zmin, zmax] (virtual walls at the edge), edgeStep, rayCount, fovDeg, sensorRange, memoryTtl, memoryCell, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var n = params.rayCount || 72
  var fov = ((params.fovDeg || 360) * Math.PI) / 180
  // Sense far enough to stop: cruise speed needs v^2 / (2 * decel) of free view (default 24 m covers the stock 10 m/s).
  var cruiseV = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var stopD = (cruiseV * cruiseV) / (2 * (params.comfortDecel || 5))
  var range = params.sensorRange || Math.min(150, Math.max(24, 1.1 * stopD + 8))
  var ttl = params.memoryTtl != null ? params.memoryTtl : 15
  var cell = params.memoryCell || 0.5
  var hl = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + 0.15
  var hw = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + 0.15
  if (!state.mem) state.mem = {}
  var mem = state.mem
  var pos = input.position
  var full = fov >= 2 * Math.PI - 1e-3
  var angles = []
  var ranges = []
  var rearClear = params.rearRange || 8
  var draw = params.debugDraw !== false
  var rayInfo = []
  var rayStride = params.debugRayStride || 2
  // extra ray planes (offsets from the centre ray): the car's top edge (+ optionally just above its underside)
  var levels = []
  var carH = av.vehicle && av.vehicle.height ? av.vehicle.height : 0
  if (params.rayLevels !== false && carH > 0.3) {
    levels = [carH / 2 - 0.08]
    // optional underside plane for low bars (off by default: ground bumps then read as obstacles)
    if (params.lowRayClearance != null) levels.push(-carH / 2 + params.lowRayClearance)
  }
  for (var i = 0; i < n; i++) {
    var th = full ? -Math.PI + (2 * Math.PI * i) / n : n === 1 ? 0 : -fov / 2 + (fov * i) / (n - 1)
    var c = Math.cos(th)
    var s = Math.sin(th)
    var dir = [
      e.fwd[0] * c + e.left[0] * s,
      e.fwd[1] * c + e.left[1] * s,
      e.fwd[2] * c + e.left[2] * s,
    ]
    // start just outside the hull rectangle along this ray
    var tHull = Math.min(Math.abs(c) > 1e-6 ? hl / Math.abs(c) : 1e9, Math.abs(s) > 1e-6 ? hw / Math.abs(s) : 1e9)
    var origin = api.vec.offsetAlong(pos, dir, tHull)
    // One horizontal plane misses what curves away from it (a sphere / dome is farther at the car's top edge than at the
    // equator, a low bar hides under the plane): cast at the car's top edge too and keep the nearest hit.
    var r = api.raycast(origin, dir, range, { visualize: false })
    for (var li = 0; li < levels.length; li++) {
      var lo = [origin[0], origin[1] + levels[li], origin[2]]
      var rl = api.raycast(lo, dir, range, { visualize: false })
      if (rl.hit && (!r.hit || rl.distance < r.distance)) {
        r = rl
        origin = lo
      }
    }
    angles.push(th)
    if (r.hit) {
      if (draw && i % rayStride === 0) api.visualizeLine(origin, api.vec.offsetAlong(origin, dir, r.distance), '#ff4d4d')
      ranges.push(r.distance)
      rayInfo.push([dir, tHull, r.distance])
      var hx = origin[0] + dir[0] * r.distance
      var hz = origin[2] + dir[2] * r.distance
      mem[Math.round(hx / cell) + ',' + Math.round(hz / cell)] = { x: hx, z: hz, t: e.t }
      if (c < -0.9 && r.distance < rearClear) rearClear = r.distance
    } else {
      ranges.push(range)
      rayInfo.push([dir, tHull, range])
    }
  }
  // Free-space clearing: a remembered obstacle that a fresh ray now passes straight through is gone (a car that drove
  // on). Without it moving traffic leaves ghost trails that box the car in for the whole memory time.
  // Cells written this frame are never cleared (a ray grazing a thin obstacle must not erase it).
  var clearRange = params.memClearRange != null ? params.memClearRange : 45
  if (clearRange > 0) {
    for (var ri = 0; ri < rayInfo.length; ri++) {
      var rd = rayInfo[ri][0]
      var rs = rayInfo[ri][1]
      var rend = Math.min(rayInfo[ri][2] - 1.0, clearRange)
      for (var rt = rs + cell; rt < rend; rt += cell) {
        var kk = Math.round((pos[0] + rd[0] * rt) / cell) + ',' + Math.round((pos[2] + rd[2] * rt) / cell)
        var mm = mem[kk]
        if (mm && mm.t < e.t - 1e-6) delete mem[kk]
      }
    }
  }
  var pts = []
  // virtual walls along the edge of the drivable area (map prior): [xmin, xmax, zmin, zmax]
  var area = params.drivableArea
  if (area && area.length === 4) {
    var step = params.edgeStep || 1.2
    var reach = range
    var xs = Math.max(area[0], pos[0] - reach)
    var xe = Math.min(area[1], pos[0] + reach)
    var zs = Math.max(area[2], pos[2] - reach)
    var ze = Math.min(area[3], pos[2] + reach)
    var j
    if (pos[2] - area[2] < reach) for (j = xs; j <= xe; j += step) pts.push([j, area[2]])
    if (area[3] - pos[2] < reach) for (j = xs; j <= xe; j += step) pts.push([j, area[3]])
    if (pos[0] - area[0] < reach) for (j = zs; j <= ze; j += step) pts.push([area[0], j])
    if (area[1] - pos[0] < reach) for (j = zs; j <= ze; j += step) pts.push([area[1], j])
  }
  var keys = Object.keys(mem)
  for (var k = 0; k < keys.length; k++) {
    var m = mem[keys[k]]
    if (e.t - m.t > ttl) delete mem[keys[k]]
    else pts.push([m.x, m.z])
  }
  if (draw) {
    // magenta ticks: remembered obstacle points (costmap), nearest 60
    var near = pts
      .map(function (q) {
        var ddx = q[0] - pos[0]
        var ddz = q[1] - pos[2]
        return [ddx * ddx + ddz * ddz, q]
      })
      .sort(function (a, b) {
        return a[0] - b[0]
      })
      .slice(0, params.debugMaxPoints || 60)
    for (var pi = 0; pi < near.length; pi++) {
      var q2 = near[pi][1]
      api.visualizeLine([q2[0], pos[1] - 0.4, q2[1]], [q2[0], pos[1] + 0.5, q2[1]], '#ff00ff')
    }
  }
  av.scan = { angles: angles, ranges: ranges, range: range }
  av.points = pts
  av.rearClear = rearClear
  return {}
}

// AV stack · SENSE / mission overlay (debug only, no effect on driving).
// Draws the whole mission route: mint polyline + poles at every waypoint; the active target pole is yellow.
// Reads av.mission.waypoints (av-mission stage) or params.waypoints [[x, z], ...].
// params: waypoints, debugDraw
function transform(input, dt, params, state, api) {
  if (params.debugDraw === false) return {}
  var av = input.av
  var wps = (av && av.mission && av.mission.waypoints) || params.waypoints
  if (!wps || !wps.length) return {}
  var y = input.position[1]
  var cur = input.target && input.target.pose && input.target.pose.position
  for (var i = 0; i < wps.length; i++) {
    var w = wps[i]
    var active = cur && Math.abs(cur[0] - w[0]) < 0.05 && Math.abs(cur[2] - w[1]) < 0.05
    api.visualizeLine([w[0], y - 0.5, w[1]], [w[0], y + 5, w[1]], active ? '#ffcc00' : '#00ffcc')
    if (i > 0) api.visualizeLine([wps[i - 1][0], y - 0.4, wps[i - 1][1]], [w[0], y - 0.4, w[1]], '#7dffb0')
  }
  return {}
}

// AV stack · PLAN / route + manoeuvre planner (Hybrid-A* over forward/reverse arc primitives).
// Two jobs, one search:
//  1. ROUTE: every `routeInterval` s plans a collision-free route to the goal over the costmap and publishes
//     `av.carrot` (a point ~lookahead metres along the forward part of the route). The local planner chases
//     the carrot instead of the raw goal, so a goal behind an obstacle no longer produces endless orbits.
//  2. MANOEUVRE: if the route starts by reversing (or the car is stuck) it takes over (`av.override`): drives the
//     multi-point turn segment by segment, re-plans on drift/blockage/stall, and hands back as soon as the route
//     has a long forward run.
// Runs BEFORE the local motion planner. Simulated time only.
// debug draw: magenta = route / manoeuvre path (+ status mast while manoeuvring), orange = current segment end.
// params: maneuverSpeed, routeInterval, routeExpansions, lookahead, primitiveLength, maxExpansions,
//         gearSwitchPenalty, reversePenalty, maxReverseRun, planMargin, tightMargin, guardMargin, stallTime, stuckTime,
//         contactTtl (s, how long an unseen contact stays a virtual obstacle, default 25), contactRestTime (s at rest before a lateral stall counts as contact, default 1), contactMemory (false = off), restWaitMax (s, wait for rest before a gear change), maxOffPath (m, drop a plan the car is farther from), crawlTime,
//         goalReach, handbackFree, goalTolerance, maxCurvature, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) return {}
  var gxw = tgt[0]
  var gzw = tgt[2]
  var kmax = params.maxCurvature || 0.115
  var planMargin = params.planMargin != null ? params.planMargin : 0.4
  var tightMargin = params.tightMargin != null ? params.tightMargin : 0.1
  var guardMargin = params.guardMargin != null ? params.guardMargin : 0.15
  var ell = params.primitiveLength || 1.8
  var maxExpFull = params.maxExpansions || 4000
  var routeExp = params.routeExpansions || 1500
  var routeInterval = params.routeInterval != null ? params.routeInterval : 0.8
  var lookahead = params.lookahead != null ? params.lookahead : 14
  var gearPen = params.gearSwitchPenalty != null ? params.gearSwitchPenalty : 4
  var revPen = params.reversePenalty != null ? params.reversePenalty : 4
  var handback = params.handbackFree != null ? params.handbackFree : 10
  var vMan = params.maneuverSpeed != null ? params.maneuverSpeed : 3
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var restWaitMax = params.restWaitMax != null ? params.restWaitMax : 1.2
  var maxOffPath = params.maxOffPath != null ? params.maxOffPath : 6
  var holdTol = params.goalTolerance != null ? params.goalTolerance : 3.5
  // route ends inside the waypoint acceptance zone (not only at its centre)
  var reach = params.goalReach != null ? params.goalReach : 3.5
  var maxRevRun = params.maxReverseRun != null ? params.maxReverseRun : 8
  var termHeadW = params.exitHeadingWeight != null ? params.exitHeadingWeight : 0
  var ks = [-kmax, -kmax / 2, 0, kmax / 2, kmax]
  var pos = input.position
  // next waypoint after the current target: the route should arrive heading towards it
  var nextWp = null
  var wps = av.mission ? av.mission.waypoints : params.waypoints
  if (wps && wps.length) {
    for (var wi = 0; wi < wps.length - 1; wi++) {
      if (Math.abs(wps[wi][0] - gxw) < 0.05 && Math.abs(wps[wi][1] - gzw) < 0.05) {
        nextWp = wps[wi + 1]
        break
      }
    }
  }
  var goalDist = Math.sqrt((gxw - pos[0]) * (gxw - pos[0]) + (gzw - pos[2]) * (gzw - pos[2]))
  // Contacts the lidar cannot see (a low bar under the ray plane, a car pressed against the hull): remembered as
  // virtual obstacle points so every planner after this stage routes around them instead of driving into them again.
  var contactTtl = params.contactTtl != null ? params.contactTtl : 25
  if (!state.contacts) state.contacts = []
  // drop expired marks and any mark that now lies inside (or hugging) the car's own footprint: it is obsolete by
  // definition and, left in place, makes every start pose collide so the car can never plan a way out
  var pHalfL = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + 0.1
  var pHalfW = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + 0.1
  state.contacts = state.contacts.filter(function (c) {
    if (e.t - c.t >= contactTtl) return false
    var rx = c.x - pos[0]
    var rz = c.z - pos[2]
    var lf = rx * e.fwd[0] + rz * e.fwd[2]
    var ll = rx * e.left[0] + rz * e.left[2]
    return !(Math.abs(lf) < pHalfL && Math.abs(ll) < pHalfW)
  })
  state.restT = Math.abs(e.speed) < 0.25 && goalDist > ((params.goalTolerance != null ? params.goalTolerance : 3.5)) ? (state.restT || 0) + dt : 0
  api.watch('av.contacts', state.contacts.length + ' rest ' + (state.restT || 0).toFixed(1) + ' side ' + (input.environment && input.environment.isTouchingSide ? 1 : 0))
  function markContact(g, stalledAlready) {
    // only a LATERAL contact (isTouchingSide: wall, other body, low bar) counts — isTouchingObject is also true on the floor — and only after the car has really been pushing
    // without moving for a while, and never build a cage (no new mark where a recent one already sits ahead).
    if (params.contactMemory === false) return
    if (!stalledAlready && (state.restT || 0) < (params.contactRestTime != null ? params.contactRestTime : 1.0)) return
    var cdd = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + 0.3
    for (var ck = 0; ck < state.contacts.length; ck++) {
      var dxk = state.contacts[ck].x - (pos[0] + e.fwd[0] * g * cdd)
      var dzk = state.contacts[ck].z - (pos[2] + e.fwd[2] * g * cdd)
      if (dxk * dxk + dzk * dzk < 2.25) return
    }
    var cd = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + 0.3
    var cw = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2
    for (var cl = -cw; cl <= cw + 1e-6; cl += cw) {
      state.contacts.push({
        x: pos[0] + e.fwd[0] * g * cd + e.left[0] * cl,
        z: pos[2] + e.fwd[2] * g * cd + e.left[2] * cl,
        t: e.t,
      })
    }
    if (state.contacts.length > 40) state.contacts.splice(0, state.contacts.length - 40)
  }
  if (state.contacts.length > 0) {
    var withContacts = (av.points || []).slice()
    for (var ci2 = 0; ci2 < state.contacts.length; ci2++) withContacts.push([state.contacts[ci2].x, state.contacts[ci2].z])
    av.points = withContacts
  }

  // spatial hash over costmap points + swept-footprint test (hl/hw are the active margins)
  function makeHit(pts, hlA, hwA) {
    var grid = {}
    for (var i = 0; i < pts.length; i++) {
      var key = Math.floor(pts[i][0] / 2) + ',' + Math.floor(pts[i][1] / 2)
      ;(grid[key] || (grid[key] = [])).push(pts[i])
    }
    var R = Math.sqrt(hlA * hlA + hwA * hwA)
    return function (x, z, fx, fz) {
      var x0 = Math.floor((x - R) / 2)
      var x1 = Math.floor((x + R) / 2)
      var z0 = Math.floor((z - R) / 2)
      var z1 = Math.floor((z + R) / 2)
      for (var cx = x0; cx <= x1; cx++) {
        for (var cz = z0; cz <= z1; cz++) {
          var list = grid[cx + ',' + cz]
          if (!list) continue
          for (var q = 0; q < list.length; q++) {
            var dx = list[q][0] - x
            var dz = list[q][1] - z
            var lx = dx * fx + dz * fz
            var ly = dx * fz - dz * fx
            if (lx > -hlA && lx < hlA && ly > -hwA && ly < hwA) return true
          }
        }
      }
      return false
    }
  }

  function search(sx, sz, sfx, sfz, gx, gz, pts, maxExp, marginOverride) {
    var hlS = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + planMargin
    var hwS = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + planMargin
    var hit = makeHit(pts, hlS, hwS)
    // start already inside the comfort margin (drift, soft contact): re-plan with the tight margin so
    // the planner can still drive out of the margin band instead of finding every primitive blocked
    // start already inside the comfort margin (drift, soft contact): re-plan with the tight margin so
    // the planner can still drive out of the margin band instead of finding every primitive blocked
    var marginUsed = planMargin
    if (marginOverride != null) {
      marginUsed = marginOverride
      hlS = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + marginUsed
      hwS = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + marginUsed
      hit = makeHit(pts, hlS, hwS)
    } else if (hit(sx, sz, sfx, sfz)) {
      marginUsed = tightMargin
      hlS = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + tightMargin
      hwS = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + tightMargin
      hit = makeHit(pts, hlS, hwS)
    }
    state.startMargin = marginUsed
    function dist(x, z) {
      var dx = gx - x
      var dz = gz - z
      return Math.sqrt(dx * dx + dz * dz)
    }
    // binary min-heap on f
    var heap = []
    function push(nd) {
      heap.push(nd)
      var c = heap.length - 1
      while (c > 0) {
        var p = (c - 1) >> 1
        if (heap[p].f <= heap[c].f) break
        var t = heap[p]
        heap[p] = heap[c]
        heap[c] = t
        c = p
      }
    }
    function pop() {
      var top = heap[0]
      var last = heap.pop()
      if (heap.length > 0) {
        heap[0] = last
        var c = 0
        for (;;) {
          var l = 2 * c + 1
          var r = l + 1
          var m = c
          if (l < heap.length && heap[l].f < heap[m].f) m = l
          if (r < heap.length && heap[r].f < heap[m].f) m = r
          if (m === c) break
          var t = heap[m]
          heap[m] = heap[c]
          heap[c] = t
          c = m
        }
      }
      return top
    }
    function skey(x, z, fx, fz, g) {
      var ih = Math.round((Math.atan2(fz, fx) / (2 * Math.PI)) * 36)
      if (ih < 0) ih += 36
      return Math.round(x / 0.6) + ',' + Math.round(z / 0.6) + ',' + (ih % 36) + ',' + g
    }
    var HW = 1.4
    var start = { x: sx, z: sz, fx: sfx, fz: sfz, g: 0, gear: 0, k: 0, parent: null, f: dist(sx, sz) * HW, d: 0 }
    push(start)
    var best = {}
    best[skey(sx, sz, sfx, sfz, 0)] = 0
    var bestNode = start
    var bestH = dist(sx, sz)
    var goalNode = null
    var expansions = 0
    while (heap.length > 0 && expansions < maxExp) {
      var cur = pop()
      var ck = skey(cur.x, cur.z, cur.fx, cur.fz, cur.gear)
      if (best[ck] !== undefined && cur.g > best[ck] + 1e-6) continue
      expansions++
      var h = dist(cur.x, cur.z)
      if (h < bestH) {
        bestH = h
        bestNode = cur
      }
      if (h < reach) {
        if (cur.terminal || !nextWp) {
          goalNode = cur
          break
        }
        // arrival cost: leave the goal zone heading towards the next waypoint
        var ndx = nextWp[0] - cur.x
        var ndz = nextWp[1] - cur.z
        var nl = Math.sqrt(ndx * ndx + ndz * ndz) || 1
        var cosA = Math.max(-1, Math.min(1, (cur.fx * ndx + cur.fz * ndz) / nl))
        var termG = cur.g + termHeadW * Math.acos(cosA)
        push({ x: cur.x, z: cur.z, fx: cur.fx, fz: cur.fz, g: termG, gear: cur.gear, k: cur.k, parent: cur, terminal: true, f: termG })
        continue
      }
      for (var gi = 0; gi < 2; gi++) {
        var gear = gi === 0 ? 1 : -1
        for (var ki = 0; ki < ks.length; ki++) {
          var k = ks[ki]
          var lx = cur.fz
          var lz = -cur.fx
          var revRun = gear < 0 ? (cur.gear < 0 ? cur.revRun || 0 : 0) + ell : 0
          if (revRun > maxRevRun) continue
          var ok = true
          var nx = cur.x
          var nz = cur.z
          var nfx = cur.fx
          var nfz = cur.fz
          for (var sIdx = 1; sIdx <= 4; sIdx++) {
            var d = (gear * ell * sIdx) / 4
            var th = k * d
            var ddx
            var ddy
            if (Math.abs(k) < 1e-6) {
              ddx = d
              ddy = 0
            } else {
              ddx = Math.sin(th) / k
              ddy = (1 - Math.cos(th)) / k
            }
            nx = cur.x + cur.fx * ddx + lx * ddy
            nz = cur.z + cur.fz * ddx + lz * ddy
            var ct = Math.cos(th)
            var st = Math.sin(th)
            nfx = cur.fx * ct + lx * st
            nfz = cur.fz * ct + lz * st
            if (hit(nx, nz, nfx, nfz)) {
              ok = false
              break
            }
          }
          if (!ok) continue
          var step = ell * (gear < 0 ? revPen : 1) + (Math.abs(k) / kmax) * 0.4 * ell
          if (cur.gear !== 0 && cur.gear !== gear) step += gearPen
          if (cur.gear !== 0 && cur.k !== k) step += 0.3
          var g2 = cur.g + step
          var nk = skey(nx, nz, nfx, nfz, gear)
          if (best[nk] !== undefined && best[nk] <= g2) continue
          best[nk] = g2
          push({ x: nx, z: nz, fx: nfx, fz: nfz, g: g2, gear: gear, k: k, revRun: revRun, parent: cur, f: g2 + dist(nx, nz) * HW })
        }
      }
    }
    var end = goalNode || bestNode
    if (end.terminal) end = end.parent
    var segs = []
    for (var nd = end; nd && nd.parent; nd = nd.parent) {
      var last = segs[0]
      if (last && last.g === nd.gear && last.k === nd.k) {
        last.len += ell
      } else {
        segs.unshift({ g: nd.gear, k: nd.k, len: ell, end: null })
      }
    }
    // expected pose at the end of every segment (walk the chain again, front to back)
    var chain = []
    for (var cn = end; cn; cn = cn.parent) chain.unshift(cn)
    var si = -1
    var prevG = null
    var prevK = null
    for (var ci = 1; ci < chain.length; ci++) {
      var nn = chain[ci]
      if (si < 0 || nn.gear !== prevG || nn.k !== prevK) {
        si++
        prevG = nn.gear
        prevK = nn.k
      }
      segs[si].end = { x: nn.x, z: nn.z, fx: nn.fx, fz: nn.fz }
    }
    var pathPts = []
    for (var pj = 0; pj < chain.length; pj++) pathPts.push([chain[pj].x, chain[pj].z])
    var nodes = []
    for (var nj = 0; nj < chain.length; nj++) nodes.push({ x: chain[nj].x, z: chain[nj].z, g: chain[nj].gear })
    return { segs: segs, reached: !!goalNode, expansions: expansions, hRemaining: bestH, path: pathPts, nodes: nodes }
  }

  function begin(res) {
    state.segs = res.segs
    state.idx = 0
    state.segStart = null
    state.prevGear = 0
    state.path = res.path
  }
  function deviates(seg) {
    if (!seg || !seg.end) return false
    var ex = pos[0] - seg.end.x
    var ez = pos[2] - seg.end.z
    var dot = e.fwd[0] * seg.end.fx + e.fwd[2] * seg.end.fz
    return Math.sqrt(ex * ex + ez * ez) > 0.9 || dot < 0.97
  }
  function plan(maxE) {
    var res = search(pos[0], pos[2], e.fwd[0], e.fwd[2], gxw, gzw, av.points || [], maxE, null)
    // Pressed against something (a corner touching a long wall): every primitive is blocked at the comfort margins, so
    // retry with ever smaller margins until the car can at least drive out of the contact.
    var escape = [0.05, 0.02, 0]
    for (var ei = 0; ei < escape.length && res.segs.length === 0 && !res.reached; ei++) {
      res = search(pos[0], pos[2], e.fwd[0], e.fwd[2], gxw, gzw, av.points || [], maxE, escape[ei])
    }
    return res
  }
  // route summary: first gear, length of the leading forward run, carrot point
  function summarize(res) {
    var nodes = res.nodes
    var firstGear = nodes.length > 1 ? nodes[1].g : 1
    var run = 0
    var carrot = null
    if (firstGear === 1) {
      var want = Math.min(lookahead, 6 + 1.0 * Math.max(0, e.speedF))
      var acc = 0
      for (var i = 1; i < nodes.length && nodes[i].g === 1; i++) {
        var dx = nodes[i].x - nodes[i - 1].x
        var dz = nodes[i].z - nodes[i - 1].z
        acc += Math.sqrt(dx * dx + dz * dz)
        carrot = [nodes[i].x, nodes[i].z]
        if (acc >= want) break
      }
      run = acc
      for (var j = i; j < nodes.length && nodes[j].g === 1; j++) {
        var ddx = nodes[j].x - nodes[j - 1].x
        var ddz = nodes[j].z - nodes[j - 1].z
        run += Math.sqrt(ddx * ddx + ddz * ddz)
      }
    }
    // speed limit from the bends ahead on the route: corner speed sqrt(aLat / kappa), reachable by braking
    var aLat = params.maxLatAccel || 9
    var aBrk = params.comfortDecel || 5
    var vLimit = Infinity
    var dAhead = 0
    for (var si = 0; si < res.segs.length && dAhead < 40 && res.segs[si].g > 0; si++) {
      var kk = Math.abs(res.segs[si].k)
      if (kk > 0.04) {
        var vi = Math.sqrt(aLat / kk)
        var allowed = Math.sqrt(vi * vi + 2 * aBrk * dAhead)
        if (allowed < vLimit) vLimit = allowed
      }
      dAhead += res.segs[si].len
    }
    return { firstGear: firstGear, run: run, carrot: carrot, reached: res.reached, nodes: nodes, path: res.path, vLimit: vLimit }
  }

  // stuck watchdog (own, independent of the local planner)
  if (state.stuckT === undefined) state.stuckT = 0
  if (!state.active && Math.abs(e.speed) < 0.25 && goalDist > holdTol) state.stuckT += dt
  else state.stuckT = 0
  // Scraping along an obstacle (wheels spinning against contact friction) is slow but not "stopped": also count it as
  // stuck when the car has hardly moved over a longer window while driving slowly.
  if (!state.crawlAnchor) state.crawlAnchor = [pos[0], pos[2]]
  var crawlMoved = Math.sqrt((pos[0] - state.crawlAnchor[0]) * (pos[0] - state.crawlAnchor[0]) + (pos[2] - state.crawlAnchor[1]) * (pos[2] - state.crawlAnchor[1]))
  if (state.active || goalDist <= holdTol || Math.abs(e.speed) > 1.2 || crawlMoved > 2.5) {
    state.crawlAnchor = [pos[0], pos[2]]
    state.crawlT = 0
  } else {
    state.crawlT = (state.crawlT || 0) + dt
    if (state.crawlT > (params.crawlTime != null ? params.crawlTime : 6)) {
      state.stuckT = Math.max(state.stuckT, stuckTime + 0.1)
      state.crawlT = 0
      state.crawlAnchor = [pos[0], pos[2]]
    }
  }

  if (!state.active) {
    if (state.route === undefined || e.t - state.routeT >= routeInterval) {
      state.route = summarize(plan(routeExp))
      state.routeT = e.t
      state.revFresh = true
      state.routes = (state.routes || 0) + 1
    }
    var rt = state.route
    // hysteresis: a reverse-first route must be confirmed by two consecutive plans before the car manoeuvres
    state.revVotes = rt.firstGear === -1 ? (state.revFresh ? (state.revVotes || 0) + 1 : state.revVotes || 1) : 0
    state.revFresh = false
    var wantManeuver = (rt.firstGear === -1 && (state.revVotes >= 2 || Math.abs(e.speed) < 0.3) && Math.abs(e.speed) < 1.5) || state.stuckT > stuckTime
    if (wantManeuver && goalDist > holdTol) {
      // stuck although the costmap shows a free way, and in contact with something: it is invisible to the lidar
      if (state.stuckT > stuckTime && input.environment && input.environment.isTouchingSide) {
        markContact(rt.firstGear === -1 ? -1 : 1)
        av.points = (av.points || []).concat(state.contacts.slice(-3).map(function (c) { return [c.x, c.z] }))
      }
      var res = plan(maxExpFull)
      if (res.segs.length > 0) {
        state.active = true
        state.replans = (state.replans || 0) + 1
        state.stuckT = 0
        begin(res)
      }
    }
    if (!state.active) {
      if (rt.carrot) av.carrot = rt.carrot
      av.route = { firstGear: rt.firstGear, run: rt.run, reached: rt.reached, vLimit: rt.vLimit }
      if (params.debugDraw !== false) {
        var y0 = pos[1]
        for (var di = 2; di < rt.path.length; di += 2) {
          api.visualizeLine([rt.path[di - 2][0], y0, rt.path[di - 2][1]], [rt.path[di][0], y0, rt.path[di][1]], '#ff44ff')
        }
      }
      api.watch('av.route', 'gear ' + rt.firstGear + ' run ' + rt.run.toFixed(1) + (rt.reached ? ' goal' : ' partial'))
      return {}
    }
  }

  // --- execute manoeuvre ---
  var cur = state.segs[state.idx]
  if (state.segStart === null) {
    // a gear change must come to rest first so the odometer does not count coasting
    // (not forever: a car that chatters around zero speed never reads as stopped)
    state.restWaitT = (state.restWaitT || 0) + dt
    if (cur.g === state.prevGear || Math.abs(e.speed) < 0.4 || state.restWaitT > restWaitMax) {
      state.segStart = [pos[0], pos[2]]
      state.restWaitT = 0
    }
  }
  // a plan the car is far away from (pushed, teleported, stale): drop it and plan from the real pose
  if (state.path && state.path.length > 1) {
    var offPath = Infinity
    for (var oi = 1; oi < state.path.length; oi++) {
      var ax0 = state.path[oi - 1][0]
      var az0 = state.path[oi - 1][1]
      var abx = state.path[oi][0] - ax0
      var abz = state.path[oi][1] - az0
      var ab2 = abx * abx + abz * abz
      var tt = ab2 > 1e-9 ? Math.max(0, Math.min(1, ((pos[0] - ax0) * abx + (pos[2] - az0) * abz) / ab2)) : 0
      var dd = Math.hypot(pos[0] - (ax0 + tt * abx), pos[2] - (az0 + tt * abz))
      if (dd < offPath) offPath = dd
    }
    if (offPath > maxOffPath) {
      state.active = false
      state.route = undefined
      state.stuckT = 0
      return {}
    }
  }
  var travelled = 0
  if (state.segStart) {
    var dx = pos[0] - state.segStart[0]
    var dz = pos[2] - state.segStart[1]
    travelled = Math.sqrt(dx * dx + dz * dz)
  }
  // --- execution guard: re-plan when the real pose makes the rest of the segment collide, or when stalled ---
  if (state.segStart !== null) {
    // the guard must not be stricter than the margin the manoeuvre was planned with (escaping from contact)
    var guardM = Math.min(guardMargin, state.startMargin != null ? state.startMargin : guardMargin)
    var guardL = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + guardM
    var guardW = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + guardM
    var gHit = makeHit(av.points || [], guardL, guardW)
    var lx0 = e.left[0]
    var lz0 = e.left[2]
    var look = Math.min(2.0, Math.max(0, cur.len - travelled))
    var blockedAhead = false
    for (var gd = 0.5; gd <= look + 1e-6 && !blockedAhead; gd += 0.5) {
      var gdd = cur.g * gd
      var gth = cur.k * gdd
      var gx2 = Math.abs(cur.k) < 1e-6 ? gdd : Math.sin(gth) / cur.k
      var gy2 = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(gth)) / cur.k
      var px = pos[0] + e.fwd[0] * gx2 + lx0 * gy2
      var pz = pos[2] + e.fwd[2] * gx2 + lz0 * gy2
      var pfx = e.fwd[0] * Math.cos(gth) + lx0 * Math.sin(gth)
      var pfz = e.fwd[2] * Math.cos(gth) + lz0 * Math.sin(gth)
      if (gHit(px, pz, pfx, pfz)) blockedAhead = true
    }
    state.stallT = Math.abs(e.speed) < 0.15 ? (state.stallT || 0) + dt : 0
    var stallTime = params.stallTime != null ? params.stallTime : 1.2
    if ((blockedAhead || state.stallT > stallTime) && e.t - (state.lastReplanT || -9) > 0.6) {
      // pushing against something the costmap does not show: mark the spot ahead (in the driving direction) as occupied
      if (!blockedAhead && input.environment && input.environment.isTouchingSide) markContact(cur.g, true)
      var fix = plan(maxExpFull)
      state.lastReplanT = e.t
      state.stallT = 0
      state.replans++
      if (fix.segs.length > 0) {
        begin(fix)
        state.prevGear = cur.g
        cur = state.segs[0]
        travelled = 0
      }
    }
  }
  // hand back once the rest of the plan starts with a long forward run
  var fwdRun = 0
  // (also from the first segment: a plan that simply starts with a long forward run is a route, not a manoeuvre — creeping
  // along it at manoeuvre speed with open-loop segments is what made the car shuttle back and forth next to obstacles)
  for (var si = state.idx; si < state.segs.length && state.segs[si].g > 0; si++) fwdRun += state.segs[si].len
  fwdRun -= travelled
  var aheadFree = false
  if (fwdRun >= handback && cur.g > 0) {
    // the car must really have room ahead on its own heading, not just a plan that will get there
    var aHit = makeHit(av.points || [], ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + planMargin, ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + planMargin)
    aheadFree = true
    for (var ad = 0; ad <= handback && aheadFree; ad += 1) {
      // along the current segment's arc (what the local planner would also pick), not just straight on
      var ath = cur.k * ad
      var ax = Math.abs(cur.k) < 1e-6 ? ad : Math.sin(ath) / cur.k
      var ay = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(ath)) / cur.k
      var apx = pos[0] + e.fwd[0] * ax + e.left[0] * ay
      var apz = pos[2] + e.fwd[2] * ax + e.left[2] * ay
      if (aHit(apx, apz, e.fwd[0] * Math.cos(ath) + e.left[0] * Math.sin(ath), e.fwd[2] * Math.cos(ath) + e.left[2] * Math.sin(ath))) aheadFree = false
    }
  }
  if (aheadFree) {
    state.active = false
    state.route = undefined
    return {}
  }
  var finished = state.segStart !== null && travelled >= cur.len - 0.25
  if (finished) {
    state.prevGear = cur.g
    if (state.idx + 1 >= state.segs.length || deviates(cur)) {
      var again = plan(maxExpFull)
      state.replans++
      if (again.segs.length === 0 || state.idx + 1 >= state.segs.length) {
        state.active = false
        state.route = undefined
        if (again.segs.length === 0) return {}
      }
      if (again.segs.length > 0 && state.active) {
        begin(again)
        state.prevGear = cur.g
      }
    } else {
      state.idx++
      state.segStart = null
    }
    if (!state.active) return {}
    cur = state.segs[state.idx]
    travelled = 0
  }
  if (params.debugDraw !== false && state.path) {
    var py = pos[1]
    for (var pi = 2; pi < state.path.length; pi += 2) {
      api.visualizeLine([state.path[pi - 2][0], py, state.path[pi - 2][1]], [state.path[pi][0], py, state.path[pi][1]], '#ff44ff')
    }
    if (cur.end) api.visualizeLine(pos, [cur.end.x, py, cur.end.z], '#ff8800')
    api.visualizeLine([pos[0], py + 1.2, pos[2]], [pos[0], py + 4, pos[2]], '#ff44ff')
  }
  var remain = state.segStart ? Math.max(0, cur.len - travelled) : cur.len
  var vMax = Math.min(vMan, 0.9 + Math.sqrt(2 * 3 * remain))
  // waiting for rest before a gear change: demand zero. Once the segment has started but the car still rolls the other
  // way (momentum from the previous segment; an icy car does not stop by itself and a zero-demand brake is below the
  // actuator deadband), drive in the demanded direction: that brakes it hard and turns it around.
  var waitingForRest = state.segStart === null
  var rollingWrong = !waitingForRest && cur.g * e.speed < -0.35
  av.override = { kappa: cur.k, vDesired: waitingForRest ? 0 : rollingWrong ? cur.g * Math.min(vMax, 2.5) : cur.g * vMax }
  av.mode = 'maneuver'
  api.watch('av.maneuver', 'seg ' + state.idx + '/' + state.segs.length + ' g' + cur.g + ' k' + cur.k.toFixed(3) + ' replans ' + state.replans)
  return {}
}

// AV stack · PLAN / local motion planner (sampling-based, receding horizon).
// Candidate paths = constant-curvature turn (limited turn angle) followed by a straight, so a path can
// swing around an obstacle and then run alongside it. Each path is swept with the vehicle footprint
// (margin grows with speed) against the costmap. Cost = progress to goal, heading, required stopping
// length, clearance, smoothness. Publishes av.plan {kappa, free, freeSoft, clearance, blocked, horizon}.
// debug draw: yellow = line to goal / route carrot, dark blue = candidate fan, green = chosen path, orange = where it would hit.
// params: vehicleWidth, vehicleLength, safetyMargin, marginSpeedGain, softMargin, maxCurvature, arcCount,
//         horizonMin, horizonGain, horizonMax, comfortDecel, wProgress, wHeading, wRequired, wFree, wSoft,
//         wSmooth, wTurn, minFree, rearIgnore, marginRamp (m over which the margin grows from the current clearance), debugDraw
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) {
    av.plan = { kappa: 0, free: 0, freeSoft: 0, clearance: 0, blocked: false, horizon: 0, noGoal: true }
    return {}
  }
  var pos = input.position
  var tdx = tgt[0] - pos[0]
  var tdz = tgt[2] - pos[2]
  av.goal = { x: tgt[0], z: tgt[2], dist: Math.sqrt(tdx * tdx + tdz * tdz) }
  // manoeuvre planner owns the controls (multi-point turn): pass its command through
  if (av.override) {
    av.plan = { kappa: av.override.kappa, vDesired: av.override.vDesired, free: 99, freeSoft: 99, clearance: 9, blocked: false, horizon: 0, override: true }
    return {}
  }
  // chase the route's carrot (global plan) when there is one, else the raw goal
  var aim = av.carrot ? [av.carrot[0], 0, av.carrot[1]] : tgt
  var gdx = aim[0] - pos[0]
  var gdz = aim[2] - pos[2]
  var gx = gdx * e.fwd[0] + gdz * e.fwd[2]
  var gy = gdx * e.left[0] + gdz * e.left[2]
  var goalDist = Math.sqrt(gx * gx + gy * gy)

  var v = Math.max(0, e.speedF)
  var margin = (params.safetyMargin != null ? params.safetyMargin : 0.5) + (params.marginSpeedGain != null ? params.marginSpeedGain : 0.05) * v
  var soft = params.softMargin != null ? params.softMargin : 1.1
  var halfW = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + margin
  var halfL = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + margin
  var kmax = params.maxCurvature || 0.115
  var count = params.arcCount || 31
  var hMin = params.horizonMin != null ? params.horizonMin : 10
  var aBrake = params.comfortDecel || 5
  // The planning horizon has to cover the stopping distance of the speed we want to drive, otherwise the free-path
  // limit (sqrt(2 * decel * horizon)) silently caps cruiseSpeed (26 m / 5 m/s^2 = 15.8 m/s).
  var cruiseV = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var hMax = params.horizonMax != null ? params.horizonMax : Math.min(150, Math.max(26, 1.1 * ((cruiseV * cruiseV) / (2 * aBrake)) + 10))
  var H = Math.min(hMax, hMin + Math.max((params.horizonGain != null ? params.horizonGain : 1.2) * v, (1.1 * v * v) / (2 * aBrake)))
  var Lreq = Math.min(H, (v * v) / (2 * aBrake) + 5)
  var wProg = params.wProgress != null ? params.wProgress : 1.0
  var wHead = params.wHeading != null ? params.wHeading : 2.0
  var wReq = params.wRequired != null ? params.wRequired : 60
  var wFree = params.wFree != null ? params.wFree : 10
  var wSoft = params.wSoft != null ? params.wSoft : 8
  var wSmooth = params.wSmooth != null ? params.wSmooth : 2.5
  var wTurn = params.wTurn != null ? params.wTurn : 1.5
  var minFree = params.minFree != null ? params.minFree : 4.5
  var ds = 0.75
  var turnAngles = [0.5, 1.15]

  // costmap into ego frame
  var pts = av.points || []
  var ox = []
  var oy = []
  for (var i = 0; i < pts.length; i++) {
    var dx = pts[i][0] - pos[0]
    var dz = pts[i][1] - pos[2]
    var px = dx * e.fwd[0] + dz * e.fwd[2]
    var py = dx * e.left[0] + dz * e.left[2]
    if (px > -halfL - soft - 3 && px < H + halfL + soft + 3 && py > -H - 4 && py < H + 4) {
      ox.push(px)
      oy.push(py)
    }
  }

  // pose along a path: turn at `kappa` for `turnLen`, then straight
  function poseAt(kappa, turnLen, s, out) {
    var sa = s < turnLen ? s : turnLen
    var th = kappa * sa
    var x
    var y
    if (Math.abs(kappa) < 1e-6) {
      x = sa
      y = 0
    } else {
      x = Math.sin(th) / kappa
      y = (1 - Math.cos(th)) / kappa
    }
    if (s > turnLen) {
      x += Math.cos(th) * (s - turnLen)
      y += Math.sin(th) * (s - turnLen)
    }
    out.x = x
    out.y = y
    out.th = th
  }
  var P = { x: 0, y: 0, th: 0 }

  // forward paths only sweep the front of the footprint: an obstacle already behind/at the tail (touching
  // start pose) must not veto driving away from it
  var rearIgnore = params.rearIgnore != null ? params.rearIgnore : 1.4
  // Start already inside the margin (parked next to a car / wall): the full margin would veto every path at s = 0 and
  // freeze the car. The margin therefore starts at the clearance the car has now and grows to the full value over
  // `marginRamp` metres — a path may not get closer than the car already is, but it may drive away.
  var hullL = halfL - margin
  var hullW = halfW - margin
  var startGap = margin + soft
  for (var sg = 0; sg < ox.length; sg++) {
    if (ox[sg] < -hullL + rearIgnore - margin) continue
    var gap = Math.max(Math.abs(ox[sg]) - hullL, Math.abs(oy[sg]) - hullW)
    if (gap < startGap) startGap = gap
  }
  var ramp = params.marginRamp != null ? params.marginRamp : 3
  function freeLength(kappa, turnLen, hw, hl) {
    var extra = hw - hullW
    var m0 = Math.max(0, Math.min(extra, startGap - 0.05))
    for (var s = 0; s <= H; s += ds) {
      var m = s >= ramp || m0 >= extra ? extra : m0 + ((extra - m0) * s) / ramp
      var hwS = hullW + m
      var hlS = hullL + m
      var hlRear = Math.max(0.3, hlS - rearIgnore)
      poseAt(kappa, turnLen, s, P)
      var ct = Math.cos(P.th)
      var st = Math.sin(P.th)
      for (var q = 0; q < ox.length; q++) {
        var rx = ox[q] - P.x
        var ry = oy[q] - P.y
        var lx = ct * rx + st * ry
        var ly = -st * rx + ct * ry
        if (lx > -hlRear && lx < hlS && ly > -hwS && ly < hwS) return Math.max(0, s - ds)
      }
    }
    return H
  }

  var prev = state.prevKappa || 0
  var prevTurn = state.prevTurn || 0
  var best = null
  var bestCost = Infinity
  var bestHard = 0
  var bestSoft = 0
  var bestTurnLen = 0
  var cand = []
  // Direct aim: turn at curvature `kappa` until the car points at the goal, then drive straight (shortest way when the
  // way is free). Returns the turn angle (rad), or 0 when the goal is on the other side / cannot be aimed at this way.
  function aimTurnAngle(kappa) {
    var ak = Math.abs(kappa)
    if (ak < 1e-6) return 0
    var gyS = kappa > 0 ? gy : -gy
    if (gyS <= 0.05 && gx > 0) return 0
    var prevF = null
    for (var th = 0.02; th <= Math.PI; th += 0.02) {
      var x = Math.sin(th) / ak
      var y = (1 - Math.cos(th)) / ak
      var f = Math.atan2(gyS - y, gx - x) - th
      while (f > Math.PI) f -= 2 * Math.PI
      while (f < -Math.PI) f += 2 * Math.PI
      if (prevF !== null && prevF > 0 && f <= 0) return th
      prevF = f
    }
    return 0
  }
  for (var a = 0; a < count; a++) {
    var kappa = count === 1 ? 0 : -kmax + (2 * kmax * a) / (count - 1)
    var aimAng = aimTurnAngle(kappa)
    var nAngles = turnAngles.length + (aimAng > 0 ? 1 : 0)
    for (var ti = 0; ti < nAngles; ti++) {
      if (Math.abs(kappa) < 1e-6 && ti > 0) continue
      var isAim = ti >= turnAngles.length
      var turnLen = Math.abs(kappa) < 1e-6 ? H : Math.min(H, (isAim ? aimAng : turnAngles[ti]) / Math.abs(kappa))
      var fHard = freeLength(kappa, turnLen, halfW, halfL)
      var fSoft = freeLength(kappa, turnLen, halfW + soft - margin, halfL + soft - margin)
      var L = fHard
      var Lpose = L
      if (isAim) {
        // judged where it reaches the goal (not far beyond it); free-length terms still use the full free path
        poseAt(kappa, turnLen, turnLen, P)
        Lpose = Math.min(L, turnLen + Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y)))
      }
      poseAt(kappa, turnLen, Lpose, P)
      var gdEnd = Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y))
      var progress = goalDist - gdEnd
      var herr = Math.atan2(gy - P.y, gx - P.x) - P.th
      while (herr > Math.PI) herr -= 2 * Math.PI
      while (herr < -Math.PI) herr += 2 * Math.PI
      var cost =
        -wProg * progress +
        wHead * Math.abs(herr) +
        wReq * Math.max(0, 1 - L / Lreq) +
        wFree * (1 - L / H) +
        wSoft * (1 - Math.min(fSoft, H) / H) +
        wSmooth * (Math.abs(kappa - prev) / kmax) +
        wTurn * Math.abs(kappa * turnLen)
      if (cost < bestCost) {
        bestCost = cost
        best = kappa
        bestHard = fHard
        bestSoft = fSoft
        bestTurnLen = turnLen
      }
      if (params.debugDraw !== false && a % 8 === 0 && ti === 0) cand.push([kappa, turnLen, fHard])
    }
  }
  state.prevKappa = best

  // lateral clearance of the chosen path over the distance that matters (beyond the hard margin)
  var clearance = 0
  var margins = [0.5, 1.0, 1.5, 2.5]
  var needLen = Math.min(bestHard, Lreq)
  for (var mi = 0; mi < margins.length; mi++) {
    var fm = freeLength(best, bestTurnLen, halfW + margins[mi], halfL + margins[mi])
    if (fm >= needLen - 1e-6) clearance = margins[mi]
    else break
  }

  av.plan = {
    kappa: best,
    free: bestHard,
    freeSoft: bestSoft,
    clearance: clearance,
    margin: margin,
    blocked: bestHard < minFree,
    startGap: startGap,
    horizon: H,
    required: Lreq,
    cost: bestCost,
  }
  api.watch('av.plan.kappa', Math.round(best * 1000) / 1000)
  api.watch('av.plan.free', Math.round(bestHard * 10) / 10 + ' clr ' + clearance)

  if (params.debugDraw !== false) {
    var y0 = pos[1]
    var W = { x: 0, y: 0, th: 0 }
    function world(x, y) {
      return [pos[0] + e.fwd[0] * x + e.left[0] * y, y0, pos[2] + e.fwd[2] * x + e.left[2] * y]
    }
    function drawPath(kk, tl, len, color, step) {
      var prevW = null
      for (var s = 0; s <= len + 1e-6; s += step) {
        poseAt(kk, tl, s, W)
        var wp = world(W.x, W.y)
        if (prevW) api.visualizeLine(prevW, wp, color)
        prevW = wp
      }
    }
    api.visualizeLine(pos, [aim[0], y0, aim[2]], '#ffcc00')
    for (var ci = 0; ci < cand.length; ci++) drawPath(cand[ci][0], cand[ci][1], cand[ci][2], '#3a5a9a', Math.max(4, cand[ci][2] / 3))
    drawPath(best, bestTurnLen, bestHard, '#22dd66', 2.5)
    if (bestHard < H) drawPath(best, bestTurnLen, Math.min(H, bestHard + 3), '#ff8800', 3)
  }
  return {}
}

// AV stack · PLAN / speed planner.
// v_des = min(cruise, obstacle in the path (auto-brake), obstacle right next to the car, route bends ahead, lateral acceleration, goal approach).
//  - In the path: auto-brake logic — v <= sqrt(2 * brakeDecel * (free distance - stopMargin)). Far obstacles only matter once they are within braking distance.
//  - Next to the car: only obstacles within `obstacleSlowRadius` (default 5 m) of the hull slow the car, linearly from `obstacleSlowFactor * cruiseSpeed` (touching) up to cruise (at the radius).
//    Obstacles that are farther away, or behind the car, never slow it. Set the radius to 0 to switch this off.
// Goal approach only slows for the FINAL waypoint (av.mission, else params.waypoints; otherwise every goal is final).
// The free-path (stopping distance) limit always wins over the floors.
// Publishes av.plan.vDesired / av.plan.vLimit ('cruise' | 'free' | 'near' | 'route' | 'curve' | 'goal').
// params: cruiseSpeed, minSpeed (lowest speed while driving, default 4), comfortDecel (brake decel for obstacles in the path, default 5),
//         stopMargin, obstacleSlowRadius (5), obstacleSlowFactor (speed right next to an obstacle as a fraction of cruise, default 0.5), maxLatAccel (default 9),
//         goalDecel (gentler braking used for the final approach, default 3), goalCrawlSpeed (floor while arriving, default 2), goalTolerance, vehicleWidth, vehicleLength, waypoints
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan) return {}
  var plan = av.plan
  if (plan.override) return {}
  var cruise = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var aBrake = params.comfortDecel || 5
  var aLat = params.maxLatAccel || 9
  var stopMargin = params.stopMargin != null ? params.stopMargin : 1.2
  var crawl = params.minSpeed != null ? params.minSpeed : params.crawlSpeed != null ? params.crawlSpeed : 4
  var limit = 'cruise'
  var v = cruise
  // obstacle in the path: auto-brake (free distance of the chosen path)
  var vFree = Math.sqrt(2 * aBrake * Math.max(0, plan.free - stopMargin))
  if (vFree < v) {
    v = vFree
    limit = 'free'
  }
  // obstacles right next to the car (hull distance), never farther than the slow radius, never behind
  var slowR = params.obstacleSlowRadius != null ? params.obstacleSlowRadius : 5
  if (slowR > 0 && av.points && av.points.length && av.ego) {
    var e = av.ego
    var hl = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2
    var hw = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2
    var pos = input.position
    var dn = Infinity
    for (var i = 0; i < av.points.length; i++) {
      var dx = av.points[i][0] - pos[0]
      var dz = av.points[i][1] - pos[2]
      var lx = dx * e.fwd[0] + dz * e.fwd[2]
      if (lx < -hl) continue // behind the rear: irrelevant for a forward-driving car
      var ly = dx * e.left[0] + dz * e.left[2]
      var ex = Math.max(Math.abs(lx) - hl, 0)
      var ey = Math.max(Math.abs(ly) - hw, 0)
      var d = Math.sqrt(ex * ex + ey * ey)
      if (d < dn) dn = d
    }
    if (dn < slowR) {
      var vNear = Math.max(crawl, (params.obstacleSlowFactor != null ? params.obstacleSlowFactor : 0.5) * cruise)
      var t = Math.min(1, Math.max(0, (dn - 0.3) / Math.max(0.01, slowR - 0.3)))
      var vProx = vNear + (cruise - vNear) * t
      if (vProx < v) {
        v = vProx
        limit = 'near'
      }
    }
  }
  // bends ahead on the global route (corner speed, reachable by braking)
  if (av.route && av.route.vLimit < v) {
    v = Math.max(av.route.vLimit, crawl)
    limit = 'route'
  }
  var k = Math.abs(plan.kappa)
  if (k > 1e-4) {
    var vCurve = Math.sqrt(aLat / k)
    if (vCurve < v) {
      v = Math.max(vCurve, crawl)
      limit = 'curve'
    }
  }
  if (av.goal) {
    var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
    var wps = params.waypoints
    var isFinal = true
    if (av.mission) {
      isFinal = av.mission.isFinal
    } else if (wps && wps.length) {
      var last = wps[wps.length - 1]
      isFinal = Math.abs(av.goal.x - last[0]) < 0.05 && Math.abs(av.goal.z - last[1]) < 0.05
    }
    if (isFinal) {
      var vGoal = Math.sqrt(2 * (params.goalDecel != null ? params.goalDecel : 3) * Math.max(0, av.goal.dist - tol))
      if (vGoal < v) {
        // arriving: creep in slowly enough to stop inside the hold radius (own, lower floor than the driving minimum)
        v = Math.max(vGoal, params.goalCrawlSpeed != null ? params.goalCrawlSpeed : 2)
        limit = 'goal'
      }
    }
  }
  if (!plan.blocked && v < crawl && limit !== 'goal') v = crawl
  // The stopping-distance limit is a safety bound, not a preference: no floor (minSpeed, route/curve crawl, goal crawl)
  // may lift the speed above what can still stop within the free path (minSpeed 9.4 with 5 m free and 2 m/s² used to
  // drive at 9.4 instead of 3.9 m/s — straight into the AEB, then stop-and-go).
  if (v > vFree) {
    v = vFree
    limit = 'free'
  }
  plan.vDesired = v
  plan.vLimit = limit
  api.watch('av.vLimit', limit + ' ' + v.toFixed(1))
  return {}
}

// AV stack · PLAN / behaviour supervisor.
// Watches planner health and flags `av.needManeuver` when the local planner is blocked
// or the vehicle is stuck; holds at the final goal. Sets av.mode ('drive' | 'hold').
// debug draw: vertical mast above the car = status (green drive, orange needs manoeuvre, white hold).
// Simulated time only. params: stuckTime, blockedTime, holdAtGoal, goalTolerance
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var plan = av.plan
  if (state.stuckT === undefined) {
    state.stuckT = 0
    state.blockedT = 0
  }
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var blockedTime = params.blockedTime != null ? params.blockedTime : 0.4
  var wantsMove = (plan.vDesired || 0) > 0.8
  if (wantsMove && Math.abs(e.speed) < 0.25) state.stuckT += dt
  else state.stuckT = 0
  if (plan.blocked && Math.abs(e.speed) < 1.2) state.blockedT += dt
  else state.blockedT = 0
  av.needManeuver = state.blockedT > blockedTime || state.stuckT > stuckTime
  av.mode = av.override ? 'maneuver' : 'drive'
  var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
  var finalGoal = !av.mission || av.mission.isFinal
  if (params.holdAtGoal !== false && finalGoal && av.goal && av.goal.dist < tol) {
    av.mode = 'hold'
    plan.override = false
    plan.vDesired = 0
    plan.kappa = 0
  }
  if (params.debugDraw !== false) {
    // status mast above the car: green drive, orange manoeuvre requested, white hold
    var c = av.mode === 'hold' ? '#ffffff' : av.needManeuver ? '#ff8800' : '#00ff66'
    api.visualizeLine([e.pos[0], e.pos[1] + 1.2, e.pos[2]], [e.pos[0], e.pos[1] + 4, e.pos[2]], c)
  }
  return {}
}

// AV stack · CONTROL / lateral (curvature tracking).
// steering = feed-forward(kappa_plan / kappaPerSteer) + P feedback on measured curvature,
// with a steering-rate limiter (comfort / actuator model).
// debug draw: white = commanded steering direction.
// params: kappaPerSteer, fbGain, steerRate
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var kps = params.kappaPerSteer || 0.12
  var fb = params.fbGain != null ? params.fbGain : 0.35
  var rate = params.steerRate != null ? params.steerRate : 4
  var kCmd = av.plan.kappa
  var steer = kCmd / kps
  if (Math.abs(e.speed) > 2 && av.mode !== 'reverse') {
    steer += (fb * (kCmd - e.kappa)) / kps
  }
  if (steer > 1) steer = 1
  if (steer < -1) steer = -1
  var prev = state.steer || 0
  var maxStep = rate * dt
  if (steer > prev + maxStep) steer = prev + maxStep
  if (steer < prev - maxStep) steer = prev - maxStep
  state.steer = steer
  // car2 treats exactly 0 as "no steering command" (wheel re-centres on its own)
  input.actions.steering_angle = Math.abs(steer) < 1e-4 ? 0 : steer
  av.cmdSteer = steer
  if (params.debugDraw !== false) {
    // white: commanded steering direction from the nose (4 m chord)
    var th = steer * kps * 4
    var nose = api.vec.offsetAlong(input.position, e.fwd, 2)
    var dir = [e.fwd[0] * Math.cos(th) + e.left[0] * Math.sin(th), 0, e.fwd[2] * Math.cos(th) + e.left[2] * Math.sin(th)]
    api.visualizeLine(nose, api.vec.offsetAlong(nose, dir, 4), '#ffffff')
  }
  return {}
}

// AV stack · CONTROL / longitudinal (model-based speed control with an online-identified actuator model).
// The car2 actuator turns a command u = throttle − brake into a force, so the body follows
//     a = G · u − D · sgn(v)          (G: m/s² per unit command, D: sliding/rolling friction deceleration, m/s²)
// G and D differ by orders of magnitude between bodies (reference car: G ≈ 156, D ≈ 60; a light icy car with power 2400:
// G ≈ 1200, D ≈ 1). A fixed deadband / gain only fits one of them — on the other the smallest command jumps the speed by
// metres per second per frame and the controller bang-bangs (the "jitter"). So G and D are estimated online (recursive
// least squares on the previous frame's command vs. the measured acceleration) and the controller asks for an
// acceleration: u = (a_des + D · s) / G, a_des = clamp((v_target − v) / tau + I, −maxDecel, maxAccel).
// Publishes av.actuator {G, D, u} (u = applied command; a later stage that overrides the actions must update it — the AEB does). The AEB uses it to brake with a deceleration instead of a raw command) and av.cmd.
// At rest the static friction can exceed D: a breakaway offset ramps while demanded motion does not start.
// params: tau, ki, maxAccel, maxDecel, maxThrottle, maxBrake, breakawayRate, gainInit, frictionInit, forget
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var vDes = av.plan.vDesired || 0
  var tau = params.tau != null ? params.tau : 0.35
  var ki = params.ki != null ? params.ki : 0.6
  var maxAcc = params.maxAccel != null ? params.maxAccel : 10
  var maxDec = params.maxDecel != null ? params.maxDecel : 12
  var maxThr = params.maxThrottle != null ? params.maxThrottle : 1
  var maxBrk = params.maxBrake != null ? params.maxBrake : 1
  var lam = params.forget != null ? params.forget : 0.97
  var v = e.speed
  if (state.G === undefined) {
    state.G = params.gainInit != null ? params.gainInit : 156
    state.D = params.frictionInit != null ? params.frictionInit : 60
    // RLS covariance over [G, D]
    state.P = [1e4, 0, 0, 1e3]
    state.uPrev = 0
    state.vPrev = v
    state.I = 0
    state.boost = 0
    state.samples = 0
  }
  // --- identify: last frame's command produced this frame's acceleration ---
  // a later stage (AEB) that overrode the command reports what was really applied in last frame's av.actuator.u
  if (state.lastAct && typeof state.lastAct.u === 'number') state.uPrev = state.lastAct.u
  var aMeas = dt > 1e-6 ? (v - state.vPrev) / dt : 0
  var vMid = 0.5 * (v + state.vPrev)
  var pushing = input.environment && input.environment.isTouchingSide
  // (sliding friction acts as soon as the body slides: learn from 0.12 m/s on, so a car creeping in force balance is not
  // stuck between 'too slow to learn' and 'too fast for the breakaway push')
  if (!pushing && Math.abs(state.uPrev) > 1e-4 && Math.abs(vMid) > 0.12 && state.vPrev * v > 0) {
    var x0 = state.uPrev
    var x1 = -(vMid > 0 ? 1 : -1)
    var P = state.P
    var px0 = P[0] * x0 + P[1] * x1
    var px1 = P[2] * x0 + P[3] * x1
    var den = lam + x0 * px0 + x1 * px1
    var k0 = px0 / den
    var k1 = px1 / den
    var err = aMeas - (state.G * x0 + state.D * x1)
    // robust: a collision / kerb spike must not wreck the model
    var lim = 50 + 0.5 * Math.abs(state.G * x0)
    if (err > lim) err = lim
    if (err < -lim) err = -lim
    state.G = Math.max(10, Math.min(20000, state.G + k0 * err))
    state.D = Math.max(0, Math.min(300, state.D + k1 * err))
    var n0 = (P[0] - k0 * px0) / lam
    var n1 = (P[1] - k0 * px1) / lam
    var n2 = (P[2] - k1 * px0) / lam
    var n3 = (P[3] - k1 * px1) / lam
    // keep the covariance bounded (forgetting without excitation blows it up)
    state.P = [Math.min(n0, 1e5), n1, n2, Math.min(n3, 1e4)]
    state.samples++
  }
  // Rescue path: the command clearly dominates friction and the response is far larger than the model predicts
  // (G underestimated — e.g. learned while pushing against a slope, or while the speed sign flipped every frame, where
  // the RLS is gated off). Pull G towards the observed gain directly so the controller stops saturating.
  // Only for a saturated command (that is the failure mode); collisions also produce big accelerations and must not pump G.
  if (!pushing && Math.abs(state.uPrev) > 0.3 && aMeas * state.uPrev > 0 && Math.abs(aMeas) > 3 * state.D + 10) {
    var gObs = Math.abs(aMeas / state.uPrev)
    if (gObs > 1.5 * state.G) state.G = Math.min(20000, state.G + 0.3 * (gObs - state.G))
  }
  var G = state.G
  var D = state.D

  // --- control ---
  var u = 0
  var holding = Math.abs(vDes) < 0.05 && Math.abs(v) < 0.3
  if (holding) {
    state.I = 0
    state.boost = 0
  } else {
    var errV = vDes - v
    // integral (acceleration units) only while not saturated, so steady errors (slope, model error) vanish
    var aDes = errV / tau + state.I
    if (aDes > maxAcc) aDes = maxAcc
    if (aDes < -maxDec) aDes = -maxDec
    if (aDes > -maxDec && aDes < maxAcc) state.I = Math.max(-3, Math.min(3, state.I + ki * errV * dt))
    // never brake through zero within one frame: the deceleration that stops the car this frame is the most we ask for
    if (Math.abs(vDes) < 0.05) {
      var stopA = Math.abs(v) / Math.max(dt, 1e-3)
      if (v > 0 && aDes < -stopA) aDes = -stopA
      if (v < 0 && aDes > stopA) aDes = stopA
    }
    // friction feed-forward in the direction of travel (at rest: of the wanted motion)
    var s = Math.abs(v) > 0.3 ? (v > 0 ? 1 : -1) : aDes > 0 ? 1 : aDes < 0 ? -1 : 0
    var fric = D * s
    // at rest, friction helps braking: no reverse push needed to stay stopped
    if (Math.abs(v) <= 0.3 && Math.abs(vDes) < 0.05) fric = 0
    u = (aDes + fric) / G
    // breakaway: demanded motion does not start (static friction > D) -> ramp an extra push
    var want = Math.abs(vDes) > 0.3
    // far below the demanded speed and not gaining (static friction / force balance the model does not explain yet)
    var stuck = want && vDes * v < Math.min(1, 0.4 * Math.abs(vDes)) && vDes * aDes > 0 && aMeas * (vDes > 0 ? 1 : -1) < 0.5
    if (stuck) state.boost = Math.min(1, state.boost + (params.breakawayRate != null ? params.breakawayRate : 0.5) * dt)
    // keep the push until the car really drives (else it jerks, stops, ramps again); then relax it slowly
    else if (!want || vDes * v >= Math.min(1, 0.4 * Math.abs(vDes))) state.boost = Math.max(0, state.boost - 0.5 * dt)
    if (state.boost > 0 && want) u += (vDes > 0 ? 1 : -1) * state.boost
    // stopping: never push along the direction of travel (friction alone may decelerate harder than maxDecel — fine)
    if (Math.abs(vDes) < 0.05 && u * v > 0) u = 0
  }
  if (u > maxThr) u = maxThr
  if (u < -maxBrk) u = -maxBrk
  state.uPrev = u
  state.vPrev = v
  input.actions.throttle = u > 0 ? u : 0
  input.actions.brake = u < 0 ? -u : 0
  // mailbox: stages after this one write the command they actually applied into av.actuator.u
  av.actuator = { G: G, D: D, samples: state.samples, u: u }
  state.lastAct = av.actuator
  av.cmd = { throttle: input.actions.throttle, brake: input.actions.brake }
  api.watch('av.throttle', 'u ' + u.toFixed(3) + ' G ' + G.toFixed(0) + ' D ' + D.toFixed(1) + ' vd ' + vDes.toFixed(1))
  return {}
}

// AV stack · SAFETY / autonomous emergency braking (independent monitor, own sensing).
// Runs after control and may only reduce throttle / add brake. Uses a smaller margin while the manoeuvre planner is driving (it already keeps swept clearance).
// Brakes with a deceleration (aebDecel), turned into a command with the actuator model the longitudinal stage identified
// (av.actuator {G, D}): a raw brake value means 360 m/s² on a light, powerful car and flips its speed within a frame.
// Footprint from av.vehicle (look-ahead starts at the nose, spread covers the body width).
// debug draw: dark gold = AEB look-ahead, red = AEB triggered.
// params: aebDecel, aebMargin, aebHalfWidth
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  if (e.speed < 0.8) {
    av.aeb = false
    return {}
  }
  var a = params.aebDecel || 7
  var margin = params.aebMargin != null ? params.aebMargin : 1.0
  if (av.mode === 'maneuver') margin = 0.2
  var len = (av.vehicle && av.vehicle.length) || params.vehicleLength || 4
  var wid = (av.vehicle && av.vehicle.width) || params.vehicleWidth || 2
  var hw = params.aebHalfWidth != null ? params.aebHalfWidth : Math.max(0.9, wid / 2 - 0.1)
  var need = (e.speed * e.speed) / (2 * a) + margin
  var origin = api.vec.offsetAlong(input.position, e.fwd, len / 2 + 0.3)
  var hit = api.raycastSpread(origin, e.fwd, need + 1, hw, 5, { visualize: false })
  av.aeb = false
  var drawOn = params.debugDraw !== false
  if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, need), '#b8860b')
  if (hit.hit && hit.distance < need) {
    if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, hit.distance), '#ff0000')
    av.aeb = true
    // deceleration needed to stop before the hit (at least aebDecel), never more than stops the car within this frame
    var room = Math.max(0.1, hit.distance - 0.2 * margin)
    var dec = Math.max(a, (e.speed * e.speed) / (2 * room))
    dec = Math.min(dec, e.speed / Math.max(dt, 1e-3))
    var act = av.actuator
    var u
    if (act && act.G > 0) u = (-dec + act.D) / act.G
    else u = -Math.min(1, 0.3 + (need - hit.distance) / need)
    var cur = (input.actions.throttle || 0) - (input.actions.brake || 0)
    if (u < cur) {
      input.actions.throttle = u > 0 ? u : 0
      input.actions.brake = u < 0 ? Math.min(1, -u) : 0
      // tell the longitudinal controller what was really applied (its actuator identification)
      if (act) act.u = input.actions.throttle - input.actions.brake
    }
    api.watch('av.aeb', Math.round(hit.distance * 10) / 10 + ' m dec ' + dec.toFixed(1))
  }
  return {}
}

// AV stack · GOAL SOURCE: random goals ("wanderer") — drop-in replacement for the waypoint mission (av-mission).
// Any goal source speaks the same contract, so the autopilot does not care which one is in front of it:
//   input.target       = { pose: { position: [x, 0, z] }, speed }   current goal (what planners read)
//   input.goalSource   = { index, waypoints: [[x, z], ...], isFinal } optional hint; av-ego adopts it as av.mission
// A wandering car never has a "final" goal, so isFinal is false: the speed planner does not brake for each goal.
// Runs at priority 2.5 (after av-ego at 2) like av-mission; it also works in front of av-ego via `goalSource`.
// params:
//   area          [xmin, xmax, zmin, zmax] world metres (default: stack param `drivableArea`, else +-40 around the start)
//   margin        keep goals this far from the area edge (default 8)
//   acceptRadius  goal counts as reached inside this radius (default 9)
//   minDistance / maxDistance  distance of the next goal from the car (defaults 25 / 60)
//   giveUpAfter   seconds (sim time) after which an unreachable goal is replaced (default 45)
//   speed         target speed hint (default 10); seed: reproducible sequence (default 1)
function transform(input, dt, params, state, api) {
  var pos = input.position
  if (state.t === undefined) {
    state.t = 0
    state.n = 0
    state.rng = ((params.seed != null ? params.seed : 1) * 2654435761) >>> 0 || 1
    state.goal = null
  }
  state.t += dt
  function rand() {
    // mulberry32
    state.rng = (state.rng + 0x6d2b79f5) >>> 0
    var t = state.rng
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
  var area = params.area || params.drivableArea
  if (!area) area = [pos[0] - 40, pos[0] + 40, pos[2] - 40, pos[2] + 40]
  if (state.area0 === undefined) state.area0 = area
  var margin = params.margin != null ? params.margin : 8
  var radius = params.acceptRadius != null ? params.acceptRadius : 9
  var dMin = params.minDistance != null ? params.minDistance : 25
  var dMax = params.maxDistance != null ? params.maxDistance : 60
  var giveUp = params.giveUpAfter != null ? params.giveUpAfter : 45

  var g = state.goal
  var reached = g && Math.hypot(pos[0] - g[0], pos[2] - g[1]) < radius
  var stale = g && state.t - state.pickedAt > giveUp
  if (!g || reached || stale) {
    var x0 = area[0] + margin
    var x1 = area[1] - margin
    var z0 = area[2] + margin
    var z1 = area[3] - margin
    var best = null
    for (var k = 0; k < 24; k++) {
      var cx = x0 + rand() * Math.max(0, x1 - x0)
      var cz = z0 + rand() * Math.max(0, z1 - z0)
      var d = Math.hypot(cx - pos[0], cz - pos[2])
      if (d >= dMin && d <= dMax) {
        best = [cx, cz]
        break
      }
      // fallback: the candidate closest to the wanted distance band
      var miss = d < dMin ? dMin - d : d - dMax
      if (!best || miss < best.miss) {
        best = [cx, cz]
        best.miss = miss
      }
    }
    state.goal = g = [best[0], best[1]]
    state.pickedAt = state.t
    state.n += 1
  }
  input.target = {
    pose: { position: [g[0], 0, g[1]], rotation: [0, 0, 0] },
    speed: params.speed != null ? params.speed : 10,
  }
  var mission = { index: state.n, waypoints: [[g[0], g[1]]], isFinal: false }
  input.goalSource = mission
  if (input.av) input.av.mission = mission
  return {}
}

// AV stack · SENSE / state estimation ("localization" layer).
// Publishes the ego state on the shared blackboard `input.av.ego` for all later stages.
// Also publishes av.vehicle {width, length, height} = max(params, own box collider) used by all planners.
// debug draw (params.debugDraw, default true): cyan = velocity vector.
// Owns the simulated clock (state.t) so no downstream stage needs a wall clock.
function transform(input, dt, params, state, api) {
  // fresh blackboard every frame (the input object is reused by the runtime)
  var av = (input.av = {})
  // a goal source running in front of this stage hands its mission over via input.goalSource (see av-wander.js)
  if (input.goalSource) {
    av.mission = input.goalSource
    input.goalSource = undefined
  }
  // Goal contract: a source that declares `input.target.isFinal === false` (preset wanderer, ...) makes the stack cruise
  // through its goals instead of braking at each one. (Sources without that flag are single, final goals.)
  if (!av.mission && input.target && input.target.pose && input.target.isFinal === false) {
    var tp = input.target.pose.position
    av.mission = { index: 0, waypoints: [[tp[0], tp[2]]], isFinal: false }
  }
  if (state.t === undefined) {
    state.t = 0
    state.speedF = 0
    state.prevSpeed = 0
    state.accelF = 0
  }
  state.t += dt
  // Vehicle footprint: never plan with a hull smaller than the entity's own box collider (a 4 x 8 m body driven with the
  // 2 x 4 defaults touches every neighbour). params.vehicleWidth / vehicleLength can only enlarge it. Cached (getEntity copies).
  if (state.vehT === undefined || state.t - state.vehT > 2) {
    state.vehT = state.t
    var ent = api.getEntity(input.entityId)
    var sh = ent && ent.shape
    var sc = (ent && ent.scale) || [1, 1, 1]
    state.vehW = sh && sh.type === 'box' ? Math.abs(sh.width * (sc[0] || 1)) : 0
    state.vehL = sh && sh.type === 'box' ? Math.abs(sh.depth * (sc[2] || 1)) : 0
    state.vehH = sh && sh.type === 'box' ? Math.abs(sh.height * (sc[1] || 1)) : 0
  }
  av.vehicle = {
    width: Math.max(params.vehicleWidth || 2, state.vehW || 0),
    length: Math.max(params.vehicleLength || 4, state.vehL || 0),
    height: state.vehH || 0,
  }
  var up = api.getUpVector(input.rotation)
  var fwd = api.vec.normalize(api.vec.projectOntoPlane(api.getForwardVector(input.rotation), up))
  var left = api.vec.normalize(api.vec.cross(up, fwd))
  var speed = api.vec.getForwardSpeed(input.velocity, fwd)
  var yawRate = api.vec.dot(input.angularVelocity, up)
  var a = dt > 1e-6 ? (speed - state.prevSpeed) / dt : 0
  state.prevSpeed = speed
  state.accelF += (a - state.accelF) * Math.min(1, dt * 8)
  state.speedF += (speed - state.speedF) * Math.min(1, dt * 20)
  av.ego = {
    t: state.t,
    dt: dt,
    pos: input.position,
    fwd: fwd,
    left: left,
    up: up,
    speed: speed,
    speedF: state.speedF,
    accel: state.accelF,
    yawRate: yawRate,
    kappa: Math.abs(speed) > 1.5 ? yawRate / speed : 0,
  }
  api.watch('av.speed', Math.round(speed * 10) / 10)
  if (params.debugDraw !== false) {
    // cyan: velocity vector
    api.visualizeLine(input.position, api.vec.add(input.position, api.vec.scale(input.velocity, 0.6)), '#00e5ff')
  }
  return {}
}

// AV stack · SENSE / perception.
// 360° range-scan ring (lidar-like, mounted at the vehicle centre, rays start on the hull)
// + obstacle memory ("local costmap") so the planners also know what is behind / beside.
// Publishes: av.scan {angles, ranges, range}, av.points [[x,z],...] (world), av.rearClear.
// debug draw (params.debugDraw, debugRayStride, debugMaxPoints): red = lidar hit rays, magenta ticks = costmap points.
// Extra ray plane at the car's top edge (params.rayLevels false = off); params.lowRayClearance (m above the underside) adds a low plane.
// Memory clearing: remembered cells that fresh rays pass through (within memClearRange 45 m, 0 = off) are dropped, so moving obstacles leave no ghost trail.
// params: drivableArea [xmin, xmax, zmin, zmax] (virtual walls at the edge), edgeStep, rayCount, fovDeg, sensorRange, memoryTtl, memoryCell, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var n = params.rayCount || 72
  var fov = ((params.fovDeg || 360) * Math.PI) / 180
  // Sense far enough to stop: cruise speed needs v^2 / (2 * decel) of free view (default 24 m covers the stock 10 m/s).
  var cruiseV = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var stopD = (cruiseV * cruiseV) / (2 * (params.comfortDecel || 5))
  var range = params.sensorRange || Math.min(150, Math.max(24, 1.1 * stopD + 8))
  var ttl = params.memoryTtl != null ? params.memoryTtl : 15
  var cell = params.memoryCell || 0.5
  var hl = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + 0.15
  var hw = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + 0.15
  if (!state.mem) state.mem = {}
  var mem = state.mem
  var pos = input.position
  var full = fov >= 2 * Math.PI - 1e-3
  var angles = []
  var ranges = []
  var rearClear = params.rearRange || 8
  var draw = params.debugDraw !== false
  var rayInfo = []
  var rayStride = params.debugRayStride || 2
  // extra ray planes (offsets from the centre ray): the car's top edge (+ optionally just above its underside)
  var levels = []
  var carH = av.vehicle && av.vehicle.height ? av.vehicle.height : 0
  if (params.rayLevels !== false && carH > 0.3) {
    levels = [carH / 2 - 0.08]
    // optional underside plane for low bars (off by default: ground bumps then read as obstacles)
    if (params.lowRayClearance != null) levels.push(-carH / 2 + params.lowRayClearance)
  }
  for (var i = 0; i < n; i++) {
    var th = full ? -Math.PI + (2 * Math.PI * i) / n : n === 1 ? 0 : -fov / 2 + (fov * i) / (n - 1)
    var c = Math.cos(th)
    var s = Math.sin(th)
    var dir = [
      e.fwd[0] * c + e.left[0] * s,
      e.fwd[1] * c + e.left[1] * s,
      e.fwd[2] * c + e.left[2] * s,
    ]
    // start just outside the hull rectangle along this ray
    var tHull = Math.min(Math.abs(c) > 1e-6 ? hl / Math.abs(c) : 1e9, Math.abs(s) > 1e-6 ? hw / Math.abs(s) : 1e9)
    var origin = api.vec.offsetAlong(pos, dir, tHull)
    // One horizontal plane misses what curves away from it (a sphere / dome is farther at the car's top edge than at the
    // equator, a low bar hides under the plane): cast at the car's top edge too and keep the nearest hit.
    var r = api.raycast(origin, dir, range, { visualize: false })
    for (var li = 0; li < levels.length; li++) {
      var lo = [origin[0], origin[1] + levels[li], origin[2]]
      var rl = api.raycast(lo, dir, range, { visualize: false })
      if (rl.hit && (!r.hit || rl.distance < r.distance)) {
        r = rl
        origin = lo
      }
    }
    angles.push(th)
    if (r.hit) {
      if (draw && i % rayStride === 0) api.visualizeLine(origin, api.vec.offsetAlong(origin, dir, r.distance), '#ff4d4d')
      ranges.push(r.distance)
      rayInfo.push([dir, tHull, r.distance])
      var hx = origin[0] + dir[0] * r.distance
      var hz = origin[2] + dir[2] * r.distance
      mem[Math.round(hx / cell) + ',' + Math.round(hz / cell)] = { x: hx, z: hz, t: e.t }
      if (c < -0.9 && r.distance < rearClear) rearClear = r.distance
    } else {
      ranges.push(range)
      rayInfo.push([dir, tHull, range])
    }
  }
  // Free-space clearing: a remembered obstacle that a fresh ray now passes straight through is gone (a car that drove
  // on). Without it moving traffic leaves ghost trails that box the car in for the whole memory time.
  // Cells written this frame are never cleared (a ray grazing a thin obstacle must not erase it).
  var clearRange = params.memClearRange != null ? params.memClearRange : 45
  if (clearRange > 0) {
    for (var ri = 0; ri < rayInfo.length; ri++) {
      var rd = rayInfo[ri][0]
      var rs = rayInfo[ri][1]
      var rend = Math.min(rayInfo[ri][2] - 1.0, clearRange)
      for (var rt = rs + cell; rt < rend; rt += cell) {
        var kk = Math.round((pos[0] + rd[0] * rt) / cell) + ',' + Math.round((pos[2] + rd[2] * rt) / cell)
        var mm = mem[kk]
        if (mm && mm.t < e.t - 1e-6) delete mem[kk]
      }
    }
  }
  var pts = []
  // virtual walls along the edge of the drivable area (map prior): [xmin, xmax, zmin, zmax]
  var area = params.drivableArea
  if (area && area.length === 4) {
    var step = params.edgeStep || 1.2
    var reach = range
    var xs = Math.max(area[0], pos[0] - reach)
    var xe = Math.min(area[1], pos[0] + reach)
    var zs = Math.max(area[2], pos[2] - reach)
    var ze = Math.min(area[3], pos[2] + reach)
    var j
    if (pos[2] - area[2] < reach) for (j = xs; j <= xe; j += step) pts.push([j, area[2]])
    if (area[3] - pos[2] < reach) for (j = xs; j <= xe; j += step) pts.push([j, area[3]])
    if (pos[0] - area[0] < reach) for (j = zs; j <= ze; j += step) pts.push([area[0], j])
    if (area[1] - pos[0] < reach) for (j = zs; j <= ze; j += step) pts.push([area[1], j])
  }
  var keys = Object.keys(mem)
  for (var k = 0; k < keys.length; k++) {
    var m = mem[keys[k]]
    if (e.t - m.t > ttl) delete mem[keys[k]]
    else pts.push([m.x, m.z])
  }
  if (draw) {
    // magenta ticks: remembered obstacle points (costmap), nearest 60
    var near = pts
      .map(function (q) {
        var ddx = q[0] - pos[0]
        var ddz = q[1] - pos[2]
        return [ddx * ddx + ddz * ddz, q]
      })
      .sort(function (a, b) {
        return a[0] - b[0]
      })
      .slice(0, params.debugMaxPoints || 60)
    for (var pi = 0; pi < near.length; pi++) {
      var q2 = near[pi][1]
      api.visualizeLine([q2[0], pos[1] - 0.4, q2[1]], [q2[0], pos[1] + 0.5, q2[1]], '#ff00ff')
    }
  }
  av.scan = { angles: angles, ranges: ranges, range: range }
  av.points = pts
  av.rearClear = rearClear
  return {}
}

// AV stack · SENSE / mission overlay (debug only, no effect on driving).
// Draws the whole mission route: mint polyline + poles at every waypoint; the active target pole is yellow.
// Reads av.mission.waypoints (av-mission stage) or params.waypoints [[x, z], ...].
// params: waypoints, debugDraw
function transform(input, dt, params, state, api) {
  if (params.debugDraw === false) return {}
  var av = input.av
  var wps = (av && av.mission && av.mission.waypoints) || params.waypoints
  if (!wps || !wps.length) return {}
  var y = input.position[1]
  var cur = input.target && input.target.pose && input.target.pose.position
  for (var i = 0; i < wps.length; i++) {
    var w = wps[i]
    var active = cur && Math.abs(cur[0] - w[0]) < 0.05 && Math.abs(cur[2] - w[1]) < 0.05
    api.visualizeLine([w[0], y - 0.5, w[1]], [w[0], y + 5, w[1]], active ? '#ffcc00' : '#00ffcc')
    if (i > 0) api.visualizeLine([wps[i - 1][0], y - 0.4, wps[i - 1][1]], [w[0], y - 0.4, w[1]], '#7dffb0')
  }
  return {}
}

// AV stack · PLAN / route + manoeuvre planner (Hybrid-A* over forward/reverse arc primitives).
// Two jobs, one search:
//  1. ROUTE: every `routeInterval` s plans a collision-free route to the goal over the costmap and publishes
//     `av.carrot` (a point ~lookahead metres along the forward part of the route). The local planner chases
//     the carrot instead of the raw goal, so a goal behind an obstacle no longer produces endless orbits.
//  2. MANOEUVRE: if the route starts by reversing (or the car is stuck) it takes over (`av.override`): drives the
//     multi-point turn segment by segment, re-plans on drift/blockage/stall, and hands back as soon as the route
//     has a long forward run.
// Runs BEFORE the local motion planner. Simulated time only.
// debug draw: magenta = route / manoeuvre path (+ status mast while manoeuvring), orange = current segment end.
// params: maneuverSpeed, routeInterval, routeExpansions, lookahead, primitiveLength, maxExpansions,
//         gearSwitchPenalty, reversePenalty, maxReverseRun, planMargin, tightMargin, guardMargin, stallTime, stuckTime,
//         contactTtl (s, how long an unseen contact stays a virtual obstacle, default 25), contactRestTime (s at rest before a lateral stall counts as contact, default 1), contactMemory (false = off), restWaitMax (s, wait for rest before a gear change), maxOffPath (m, drop a plan the car is farther from), crawlTime,
//         goalReach, handbackFree, goalTolerance, maxCurvature, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) return {}
  var gxw = tgt[0]
  var gzw = tgt[2]
  var kmax = params.maxCurvature || 0.115
  var planMargin = params.planMargin != null ? params.planMargin : 0.4
  var tightMargin = params.tightMargin != null ? params.tightMargin : 0.1
  var guardMargin = params.guardMargin != null ? params.guardMargin : 0.15
  var ell = params.primitiveLength || 1.8
  var maxExpFull = params.maxExpansions || 4000
  var routeExp = params.routeExpansions || 1500
  var routeInterval = params.routeInterval != null ? params.routeInterval : 0.8
  var lookahead = params.lookahead != null ? params.lookahead : 14
  var gearPen = params.gearSwitchPenalty != null ? params.gearSwitchPenalty : 4
  var revPen = params.reversePenalty != null ? params.reversePenalty : 4
  var handback = params.handbackFree != null ? params.handbackFree : 10
  var vMan = params.maneuverSpeed != null ? params.maneuverSpeed : 3
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var restWaitMax = params.restWaitMax != null ? params.restWaitMax : 1.2
  var maxOffPath = params.maxOffPath != null ? params.maxOffPath : 6
  var holdTol = params.goalTolerance != null ? params.goalTolerance : 3.5
  // route ends inside the waypoint acceptance zone (not only at its centre)
  var reach = params.goalReach != null ? params.goalReach : 3.5
  var maxRevRun = params.maxReverseRun != null ? params.maxReverseRun : 8
  var termHeadW = params.exitHeadingWeight != null ? params.exitHeadingWeight : 0
  var ks = [-kmax, -kmax / 2, 0, kmax / 2, kmax]
  var pos = input.position
  // next waypoint after the current target: the route should arrive heading towards it
  var nextWp = null
  var wps = av.mission ? av.mission.waypoints : params.waypoints
  if (wps && wps.length) {
    for (var wi = 0; wi < wps.length - 1; wi++) {
      if (Math.abs(wps[wi][0] - gxw) < 0.05 && Math.abs(wps[wi][1] - gzw) < 0.05) {
        nextWp = wps[wi + 1]
        break
      }
    }
  }
  var goalDist = Math.sqrt((gxw - pos[0]) * (gxw - pos[0]) + (gzw - pos[2]) * (gzw - pos[2]))
  // Contacts the lidar cannot see (a low bar under the ray plane, a car pressed against the hull): remembered as
  // virtual obstacle points so every planner after this stage routes around them instead of driving into them again.
  var contactTtl = params.contactTtl != null ? params.contactTtl : 25
  if (!state.contacts) state.contacts = []
  // drop expired marks and any mark that now lies inside (or hugging) the car's own footprint: it is obsolete by
  // definition and, left in place, makes every start pose collide so the car can never plan a way out
  var pHalfL = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + 0.1
  var pHalfW = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + 0.1
  state.contacts = state.contacts.filter(function (c) {
    if (e.t - c.t >= contactTtl) return false
    var rx = c.x - pos[0]
    var rz = c.z - pos[2]
    var lf = rx * e.fwd[0] + rz * e.fwd[2]
    var ll = rx * e.left[0] + rz * e.left[2]
    return !(Math.abs(lf) < pHalfL && Math.abs(ll) < pHalfW)
  })
  state.restT = Math.abs(e.speed) < 0.25 && goalDist > ((params.goalTolerance != null ? params.goalTolerance : 3.5)) ? (state.restT || 0) + dt : 0
  api.watch('av.contacts', state.contacts.length + ' rest ' + (state.restT || 0).toFixed(1) + ' side ' + (input.environment && input.environment.isTouchingSide ? 1 : 0))
  function markContact(g, stalledAlready) {
    // only a LATERAL contact (isTouchingSide: wall, other body, low bar) counts — isTouchingObject is also true on the floor — and only after the car has really been pushing
    // without moving for a while, and never build a cage (no new mark where a recent one already sits ahead).
    if (params.contactMemory === false) return
    if (!stalledAlready && (state.restT || 0) < (params.contactRestTime != null ? params.contactRestTime : 1.0)) return
    var cdd = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + 0.3
    for (var ck = 0; ck < state.contacts.length; ck++) {
      var dxk = state.contacts[ck].x - (pos[0] + e.fwd[0] * g * cdd)
      var dzk = state.contacts[ck].z - (pos[2] + e.fwd[2] * g * cdd)
      if (dxk * dxk + dzk * dzk < 2.25) return
    }
    var cd = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + 0.3
    var cw = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2
    for (var cl = -cw; cl <= cw + 1e-6; cl += cw) {
      state.contacts.push({
        x: pos[0] + e.fwd[0] * g * cd + e.left[0] * cl,
        z: pos[2] + e.fwd[2] * g * cd + e.left[2] * cl,
        t: e.t,
      })
    }
    if (state.contacts.length > 40) state.contacts.splice(0, state.contacts.length - 40)
  }
  if (state.contacts.length > 0) {
    var withContacts = (av.points || []).slice()
    for (var ci2 = 0; ci2 < state.contacts.length; ci2++) withContacts.push([state.contacts[ci2].x, state.contacts[ci2].z])
    av.points = withContacts
  }

  // spatial hash over costmap points + swept-footprint test (hl/hw are the active margins)
  function makeHit(pts, hlA, hwA) {
    var grid = {}
    for (var i = 0; i < pts.length; i++) {
      var key = Math.floor(pts[i][0] / 2) + ',' + Math.floor(pts[i][1] / 2)
      ;(grid[key] || (grid[key] = [])).push(pts[i])
    }
    var R = Math.sqrt(hlA * hlA + hwA * hwA)
    return function (x, z, fx, fz) {
      var x0 = Math.floor((x - R) / 2)
      var x1 = Math.floor((x + R) / 2)
      var z0 = Math.floor((z - R) / 2)
      var z1 = Math.floor((z + R) / 2)
      for (var cx = x0; cx <= x1; cx++) {
        for (var cz = z0; cz <= z1; cz++) {
          var list = grid[cx + ',' + cz]
          if (!list) continue
          for (var q = 0; q < list.length; q++) {
            var dx = list[q][0] - x
            var dz = list[q][1] - z
            var lx = dx * fx + dz * fz
            var ly = dx * fz - dz * fx
            if (lx > -hlA && lx < hlA && ly > -hwA && ly < hwA) return true
          }
        }
      }
      return false
    }
  }

  function search(sx, sz, sfx, sfz, gx, gz, pts, maxExp, marginOverride) {
    var hlS = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + planMargin
    var hwS = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + planMargin
    var hit = makeHit(pts, hlS, hwS)
    // start already inside the comfort margin (drift, soft contact): re-plan with the tight margin so
    // the planner can still drive out of the margin band instead of finding every primitive blocked
    // start already inside the comfort margin (drift, soft contact): re-plan with the tight margin so
    // the planner can still drive out of the margin band instead of finding every primitive blocked
    var marginUsed = planMargin
    if (marginOverride != null) {
      marginUsed = marginOverride
      hlS = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + marginUsed
      hwS = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + marginUsed
      hit = makeHit(pts, hlS, hwS)
    } else if (hit(sx, sz, sfx, sfz)) {
      marginUsed = tightMargin
      hlS = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + tightMargin
      hwS = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + tightMargin
      hit = makeHit(pts, hlS, hwS)
    }
    state.startMargin = marginUsed
    function dist(x, z) {
      var dx = gx - x
      var dz = gz - z
      return Math.sqrt(dx * dx + dz * dz)
    }
    // binary min-heap on f
    var heap = []
    function push(nd) {
      heap.push(nd)
      var c = heap.length - 1
      while (c > 0) {
        var p = (c - 1) >> 1
        if (heap[p].f <= heap[c].f) break
        var t = heap[p]
        heap[p] = heap[c]
        heap[c] = t
        c = p
      }
    }
    function pop() {
      var top = heap[0]
      var last = heap.pop()
      if (heap.length > 0) {
        heap[0] = last
        var c = 0
        for (;;) {
          var l = 2 * c + 1
          var r = l + 1
          var m = c
          if (l < heap.length && heap[l].f < heap[m].f) m = l
          if (r < heap.length && heap[r].f < heap[m].f) m = r
          if (m === c) break
          var t = heap[m]
          heap[m] = heap[c]
          heap[c] = t
          c = m
        }
      }
      return top
    }
    function skey(x, z, fx, fz, g) {
      var ih = Math.round((Math.atan2(fz, fx) / (2 * Math.PI)) * 36)
      if (ih < 0) ih += 36
      return Math.round(x / 0.6) + ',' + Math.round(z / 0.6) + ',' + (ih % 36) + ',' + g
    }
    var HW = 1.4
    var start = { x: sx, z: sz, fx: sfx, fz: sfz, g: 0, gear: 0, k: 0, parent: null, f: dist(sx, sz) * HW, d: 0 }
    push(start)
    var best = {}
    best[skey(sx, sz, sfx, sfz, 0)] = 0
    var bestNode = start
    var bestH = dist(sx, sz)
    var goalNode = null
    var expansions = 0
    while (heap.length > 0 && expansions < maxExp) {
      var cur = pop()
      var ck = skey(cur.x, cur.z, cur.fx, cur.fz, cur.gear)
      if (best[ck] !== undefined && cur.g > best[ck] + 1e-6) continue
      expansions++
      var h = dist(cur.x, cur.z)
      if (h < bestH) {
        bestH = h
        bestNode = cur
      }
      if (h < reach) {
        if (cur.terminal || !nextWp) {
          goalNode = cur
          break
        }
        // arrival cost: leave the goal zone heading towards the next waypoint
        var ndx = nextWp[0] - cur.x
        var ndz = nextWp[1] - cur.z
        var nl = Math.sqrt(ndx * ndx + ndz * ndz) || 1
        var cosA = Math.max(-1, Math.min(1, (cur.fx * ndx + cur.fz * ndz) / nl))
        var termG = cur.g + termHeadW * Math.acos(cosA)
        push({ x: cur.x, z: cur.z, fx: cur.fx, fz: cur.fz, g: termG, gear: cur.gear, k: cur.k, parent: cur, terminal: true, f: termG })
        continue
      }
      for (var gi = 0; gi < 2; gi++) {
        var gear = gi === 0 ? 1 : -1
        for (var ki = 0; ki < ks.length; ki++) {
          var k = ks[ki]
          var lx = cur.fz
          var lz = -cur.fx
          var revRun = gear < 0 ? (cur.gear < 0 ? cur.revRun || 0 : 0) + ell : 0
          if (revRun > maxRevRun) continue
          var ok = true
          var nx = cur.x
          var nz = cur.z
          var nfx = cur.fx
          var nfz = cur.fz
          for (var sIdx = 1; sIdx <= 4; sIdx++) {
            var d = (gear * ell * sIdx) / 4
            var th = k * d
            var ddx
            var ddy
            if (Math.abs(k) < 1e-6) {
              ddx = d
              ddy = 0
            } else {
              ddx = Math.sin(th) / k
              ddy = (1 - Math.cos(th)) / k
            }
            nx = cur.x + cur.fx * ddx + lx * ddy
            nz = cur.z + cur.fz * ddx + lz * ddy
            var ct = Math.cos(th)
            var st = Math.sin(th)
            nfx = cur.fx * ct + lx * st
            nfz = cur.fz * ct + lz * st
            if (hit(nx, nz, nfx, nfz)) {
              ok = false
              break
            }
          }
          if (!ok) continue
          var step = ell * (gear < 0 ? revPen : 1) + (Math.abs(k) / kmax) * 0.4 * ell
          if (cur.gear !== 0 && cur.gear !== gear) step += gearPen
          if (cur.gear !== 0 && cur.k !== k) step += 0.3
          var g2 = cur.g + step
          var nk = skey(nx, nz, nfx, nfz, gear)
          if (best[nk] !== undefined && best[nk] <= g2) continue
          best[nk] = g2
          push({ x: nx, z: nz, fx: nfx, fz: nfz, g: g2, gear: gear, k: k, revRun: revRun, parent: cur, f: g2 + dist(nx, nz) * HW })
        }
      }
    }
    var end = goalNode || bestNode
    if (end.terminal) end = end.parent
    var segs = []
    for (var nd = end; nd && nd.parent; nd = nd.parent) {
      var last = segs[0]
      if (last && last.g === nd.gear && last.k === nd.k) {
        last.len += ell
      } else {
        segs.unshift({ g: nd.gear, k: nd.k, len: ell, end: null })
      }
    }
    // expected pose at the end of every segment (walk the chain again, front to back)
    var chain = []
    for (var cn = end; cn; cn = cn.parent) chain.unshift(cn)
    var si = -1
    var prevG = null
    var prevK = null
    for (var ci = 1; ci < chain.length; ci++) {
      var nn = chain[ci]
      if (si < 0 || nn.gear !== prevG || nn.k !== prevK) {
        si++
        prevG = nn.gear
        prevK = nn.k
      }
      segs[si].end = { x: nn.x, z: nn.z, fx: nn.fx, fz: nn.fz }
    }
    var pathPts = []
    for (var pj = 0; pj < chain.length; pj++) pathPts.push([chain[pj].x, chain[pj].z])
    var nodes = []
    for (var nj = 0; nj < chain.length; nj++) nodes.push({ x: chain[nj].x, z: chain[nj].z, g: chain[nj].gear })
    return { segs: segs, reached: !!goalNode, expansions: expansions, hRemaining: bestH, path: pathPts, nodes: nodes }
  }

  function begin(res) {
    state.segs = res.segs
    state.idx = 0
    state.segStart = null
    state.prevGear = 0
    state.path = res.path
  }
  function deviates(seg) {
    if (!seg || !seg.end) return false
    var ex = pos[0] - seg.end.x
    var ez = pos[2] - seg.end.z
    var dot = e.fwd[0] * seg.end.fx + e.fwd[2] * seg.end.fz
    return Math.sqrt(ex * ex + ez * ez) > 0.9 || dot < 0.97
  }
  function plan(maxE) {
    var res = search(pos[0], pos[2], e.fwd[0], e.fwd[2], gxw, gzw, av.points || [], maxE, null)
    // Pressed against something (a corner touching a long wall): every primitive is blocked at the comfort margins, so
    // retry with ever smaller margins until the car can at least drive out of the contact.
    var escape = [0.05, 0.02, 0]
    for (var ei = 0; ei < escape.length && res.segs.length === 0 && !res.reached; ei++) {
      res = search(pos[0], pos[2], e.fwd[0], e.fwd[2], gxw, gzw, av.points || [], maxE, escape[ei])
    }
    return res
  }
  // route summary: first gear, length of the leading forward run, carrot point
  function summarize(res) {
    var nodes = res.nodes
    var firstGear = nodes.length > 1 ? nodes[1].g : 1
    var run = 0
    var carrot = null
    if (firstGear === 1) {
      var want = Math.min(lookahead, 6 + 1.0 * Math.max(0, e.speedF))
      var acc = 0
      for (var i = 1; i < nodes.length && nodes[i].g === 1; i++) {
        var dx = nodes[i].x - nodes[i - 1].x
        var dz = nodes[i].z - nodes[i - 1].z
        acc += Math.sqrt(dx * dx + dz * dz)
        carrot = [nodes[i].x, nodes[i].z]
        if (acc >= want) break
      }
      run = acc
      for (var j = i; j < nodes.length && nodes[j].g === 1; j++) {
        var ddx = nodes[j].x - nodes[j - 1].x
        var ddz = nodes[j].z - nodes[j - 1].z
        run += Math.sqrt(ddx * ddx + ddz * ddz)
      }
    }
    // speed limit from the bends ahead on the route: corner speed sqrt(aLat / kappa), reachable by braking
    var aLat = params.maxLatAccel || 9
    var aBrk = params.comfortDecel || 5
    var vLimit = Infinity
    var dAhead = 0
    for (var si = 0; si < res.segs.length && dAhead < 40 && res.segs[si].g > 0; si++) {
      var kk = Math.abs(res.segs[si].k)
      if (kk > 0.04) {
        var vi = Math.sqrt(aLat / kk)
        var allowed = Math.sqrt(vi * vi + 2 * aBrk * dAhead)
        if (allowed < vLimit) vLimit = allowed
      }
      dAhead += res.segs[si].len
    }
    return { firstGear: firstGear, run: run, carrot: carrot, reached: res.reached, nodes: nodes, path: res.path, vLimit: vLimit }
  }

  // stuck watchdog (own, independent of the local planner)
  if (state.stuckT === undefined) state.stuckT = 0
  if (!state.active && Math.abs(e.speed) < 0.25 && goalDist > holdTol) state.stuckT += dt
  else state.stuckT = 0
  // Scraping along an obstacle (wheels spinning against contact friction) is slow but not "stopped": also count it as
  // stuck when the car has hardly moved over a longer window while driving slowly.
  if (!state.crawlAnchor) state.crawlAnchor = [pos[0], pos[2]]
  var crawlMoved = Math.sqrt((pos[0] - state.crawlAnchor[0]) * (pos[0] - state.crawlAnchor[0]) + (pos[2] - state.crawlAnchor[1]) * (pos[2] - state.crawlAnchor[1]))
  if (state.active || goalDist <= holdTol || Math.abs(e.speed) > 1.2 || crawlMoved > 2.5) {
    state.crawlAnchor = [pos[0], pos[2]]
    state.crawlT = 0
  } else {
    state.crawlT = (state.crawlT || 0) + dt
    if (state.crawlT > (params.crawlTime != null ? params.crawlTime : 6)) {
      state.stuckT = Math.max(state.stuckT, stuckTime + 0.1)
      state.crawlT = 0
      state.crawlAnchor = [pos[0], pos[2]]
    }
  }

  if (!state.active) {
    if (state.route === undefined || e.t - state.routeT >= routeInterval) {
      state.route = summarize(plan(routeExp))
      state.routeT = e.t
      state.revFresh = true
      state.routes = (state.routes || 0) + 1
    }
    var rt = state.route
    // hysteresis: a reverse-first route must be confirmed by two consecutive plans before the car manoeuvres
    state.revVotes = rt.firstGear === -1 ? (state.revFresh ? (state.revVotes || 0) + 1 : state.revVotes || 1) : 0
    state.revFresh = false
    var wantManeuver = (rt.firstGear === -1 && (state.revVotes >= 2 || Math.abs(e.speed) < 0.3) && Math.abs(e.speed) < 1.5) || state.stuckT > stuckTime
    if (wantManeuver && goalDist > holdTol) {
      // stuck although the costmap shows a free way, and in contact with something: it is invisible to the lidar
      if (state.stuckT > stuckTime && input.environment && input.environment.isTouchingSide) {
        markContact(rt.firstGear === -1 ? -1 : 1)
        av.points = (av.points || []).concat(state.contacts.slice(-3).map(function (c) { return [c.x, c.z] }))
      }
      var res = plan(maxExpFull)
      if (res.segs.length > 0) {
        state.active = true
        state.replans = (state.replans || 0) + 1
        state.stuckT = 0
        begin(res)
      }
    }
    if (!state.active) {
      if (rt.carrot) av.carrot = rt.carrot
      av.route = { firstGear: rt.firstGear, run: rt.run, reached: rt.reached, vLimit: rt.vLimit }
      if (params.debugDraw !== false) {
        var y0 = pos[1]
        for (var di = 2; di < rt.path.length; di += 2) {
          api.visualizeLine([rt.path[di - 2][0], y0, rt.path[di - 2][1]], [rt.path[di][0], y0, rt.path[di][1]], '#ff44ff')
        }
      }
      api.watch('av.route', 'gear ' + rt.firstGear + ' run ' + rt.run.toFixed(1) + (rt.reached ? ' goal' : ' partial'))
      return {}
    }
  }

  // --- execute manoeuvre ---
  var cur = state.segs[state.idx]
  if (state.segStart === null) {
    // a gear change must come to rest first so the odometer does not count coasting
    // (not forever: a car that chatters around zero speed never reads as stopped)
    state.restWaitT = (state.restWaitT || 0) + dt
    if (cur.g === state.prevGear || Math.abs(e.speed) < 0.4 || state.restWaitT > restWaitMax) {
      state.segStart = [pos[0], pos[2]]
      state.restWaitT = 0
    }
  }
  // a plan the car is far away from (pushed, teleported, stale): drop it and plan from the real pose
  if (state.path && state.path.length > 1) {
    var offPath = Infinity
    for (var oi = 1; oi < state.path.length; oi++) {
      var ax0 = state.path[oi - 1][0]
      var az0 = state.path[oi - 1][1]
      var abx = state.path[oi][0] - ax0
      var abz = state.path[oi][1] - az0
      var ab2 = abx * abx + abz * abz
      var tt = ab2 > 1e-9 ? Math.max(0, Math.min(1, ((pos[0] - ax0) * abx + (pos[2] - az0) * abz) / ab2)) : 0
      var dd = Math.hypot(pos[0] - (ax0 + tt * abx), pos[2] - (az0 + tt * abz))
      if (dd < offPath) offPath = dd
    }
    if (offPath > maxOffPath) {
      state.active = false
      state.route = undefined
      state.stuckT = 0
      return {}
    }
  }
  var travelled = 0
  if (state.segStart) {
    var dx = pos[0] - state.segStart[0]
    var dz = pos[2] - state.segStart[1]
    travelled = Math.sqrt(dx * dx + dz * dz)
  }
  // --- execution guard: re-plan when the real pose makes the rest of the segment collide, or when stalled ---
  if (state.segStart !== null) {
    // the guard must not be stricter than the margin the manoeuvre was planned with (escaping from contact)
    var guardM = Math.min(guardMargin, state.startMargin != null ? state.startMargin : guardMargin)
    var guardL = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + guardM
    var guardW = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + guardM
    var gHit = makeHit(av.points || [], guardL, guardW)
    var lx0 = e.left[0]
    var lz0 = e.left[2]
    var look = Math.min(2.0, Math.max(0, cur.len - travelled))
    var blockedAhead = false
    for (var gd = 0.5; gd <= look + 1e-6 && !blockedAhead; gd += 0.5) {
      var gdd = cur.g * gd
      var gth = cur.k * gdd
      var gx2 = Math.abs(cur.k) < 1e-6 ? gdd : Math.sin(gth) / cur.k
      var gy2 = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(gth)) / cur.k
      var px = pos[0] + e.fwd[0] * gx2 + lx0 * gy2
      var pz = pos[2] + e.fwd[2] * gx2 + lz0 * gy2
      var pfx = e.fwd[0] * Math.cos(gth) + lx0 * Math.sin(gth)
      var pfz = e.fwd[2] * Math.cos(gth) + lz0 * Math.sin(gth)
      if (gHit(px, pz, pfx, pfz)) blockedAhead = true
    }
    state.stallT = Math.abs(e.speed) < 0.15 ? (state.stallT || 0) + dt : 0
    var stallTime = params.stallTime != null ? params.stallTime : 1.2
    if ((blockedAhead || state.stallT > stallTime) && e.t - (state.lastReplanT || -9) > 0.6) {
      // pushing against something the costmap does not show: mark the spot ahead (in the driving direction) as occupied
      if (!blockedAhead && input.environment && input.environment.isTouchingSide) markContact(cur.g, true)
      var fix = plan(maxExpFull)
      state.lastReplanT = e.t
      state.stallT = 0
      state.replans++
      if (fix.segs.length > 0) {
        begin(fix)
        state.prevGear = cur.g
        cur = state.segs[0]
        travelled = 0
      }
    }
  }
  // hand back once the rest of the plan starts with a long forward run
  var fwdRun = 0
  // (also from the first segment: a plan that simply starts with a long forward run is a route, not a manoeuvre — creeping
  // along it at manoeuvre speed with open-loop segments is what made the car shuttle back and forth next to obstacles)
  for (var si = state.idx; si < state.segs.length && state.segs[si].g > 0; si++) fwdRun += state.segs[si].len
  fwdRun -= travelled
  var aheadFree = false
  if (fwdRun >= handback && cur.g > 0) {
    // the car must really have room ahead on its own heading, not just a plan that will get there
    var aHit = makeHit(av.points || [], ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + planMargin, ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + planMargin)
    aheadFree = true
    for (var ad = 0; ad <= handback && aheadFree; ad += 1) {
      // along the current segment's arc (what the local planner would also pick), not just straight on
      var ath = cur.k * ad
      var ax = Math.abs(cur.k) < 1e-6 ? ad : Math.sin(ath) / cur.k
      var ay = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(ath)) / cur.k
      var apx = pos[0] + e.fwd[0] * ax + e.left[0] * ay
      var apz = pos[2] + e.fwd[2] * ax + e.left[2] * ay
      if (aHit(apx, apz, e.fwd[0] * Math.cos(ath) + e.left[0] * Math.sin(ath), e.fwd[2] * Math.cos(ath) + e.left[2] * Math.sin(ath))) aheadFree = false
    }
  }
  if (aheadFree) {
    state.active = false
    state.route = undefined
    return {}
  }
  var finished = state.segStart !== null && travelled >= cur.len - 0.25
  if (finished) {
    state.prevGear = cur.g
    if (state.idx + 1 >= state.segs.length || deviates(cur)) {
      var again = plan(maxExpFull)
      state.replans++
      if (again.segs.length === 0 || state.idx + 1 >= state.segs.length) {
        state.active = false
        state.route = undefined
        if (again.segs.length === 0) return {}
      }
      if (again.segs.length > 0 && state.active) {
        begin(again)
        state.prevGear = cur.g
      }
    } else {
      state.idx++
      state.segStart = null
    }
    if (!state.active) return {}
    cur = state.segs[state.idx]
    travelled = 0
  }
  if (params.debugDraw !== false && state.path) {
    var py = pos[1]
    for (var pi = 2; pi < state.path.length; pi += 2) {
      api.visualizeLine([state.path[pi - 2][0], py, state.path[pi - 2][1]], [state.path[pi][0], py, state.path[pi][1]], '#ff44ff')
    }
    if (cur.end) api.visualizeLine(pos, [cur.end.x, py, cur.end.z], '#ff8800')
    api.visualizeLine([pos[0], py + 1.2, pos[2]], [pos[0], py + 4, pos[2]], '#ff44ff')
  }
  var remain = state.segStart ? Math.max(0, cur.len - travelled) : cur.len
  var vMax = Math.min(vMan, 0.9 + Math.sqrt(2 * 3 * remain))
  // waiting for rest before a gear change: demand zero. Once the segment has started but the car still rolls the other
  // way (momentum from the previous segment; an icy car does not stop by itself and a zero-demand brake is below the
  // actuator deadband), drive in the demanded direction: that brakes it hard and turns it around.
  var waitingForRest = state.segStart === null
  var rollingWrong = !waitingForRest && cur.g * e.speed < -0.35
  av.override = { kappa: cur.k, vDesired: waitingForRest ? 0 : rollingWrong ? cur.g * Math.min(vMax, 2.5) : cur.g * vMax }
  av.mode = 'maneuver'
  api.watch('av.maneuver', 'seg ' + state.idx + '/' + state.segs.length + ' g' + cur.g + ' k' + cur.k.toFixed(3) + ' replans ' + state.replans)
  return {}
}

// AV stack · PLAN / local motion planner (sampling-based, receding horizon).
// Candidate paths = constant-curvature turn (limited turn angle) followed by a straight, so a path can
// swing around an obstacle and then run alongside it. Each path is swept with the vehicle footprint
// (margin grows with speed) against the costmap. Cost = progress to goal, heading, required stopping
// length, clearance, smoothness. Publishes av.plan {kappa, free, freeSoft, clearance, blocked, horizon}.
// debug draw: yellow = line to goal / route carrot, dark blue = candidate fan, green = chosen path, orange = where it would hit.
// params: vehicleWidth, vehicleLength, safetyMargin, marginSpeedGain, softMargin, maxCurvature, arcCount,
//         horizonMin, horizonGain, horizonMax, comfortDecel, wProgress, wHeading, wRequired, wFree, wSoft,
//         wSmooth, wTurn, minFree, rearIgnore, marginRamp (m over which the margin grows from the current clearance), debugDraw
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) {
    av.plan = { kappa: 0, free: 0, freeSoft: 0, clearance: 0, blocked: false, horizon: 0, noGoal: true }
    return {}
  }
  var pos = input.position
  var tdx = tgt[0] - pos[0]
  var tdz = tgt[2] - pos[2]
  av.goal = { x: tgt[0], z: tgt[2], dist: Math.sqrt(tdx * tdx + tdz * tdz) }
  // manoeuvre planner owns the controls (multi-point turn): pass its command through
  if (av.override) {
    av.plan = { kappa: av.override.kappa, vDesired: av.override.vDesired, free: 99, freeSoft: 99, clearance: 9, blocked: false, horizon: 0, override: true }
    return {}
  }
  // chase the route's carrot (global plan) when there is one, else the raw goal
  var aim = av.carrot ? [av.carrot[0], 0, av.carrot[1]] : tgt
  var gdx = aim[0] - pos[0]
  var gdz = aim[2] - pos[2]
  var gx = gdx * e.fwd[0] + gdz * e.fwd[2]
  var gy = gdx * e.left[0] + gdz * e.left[2]
  var goalDist = Math.sqrt(gx * gx + gy * gy)

  var v = Math.max(0, e.speedF)
  var margin = (params.safetyMargin != null ? params.safetyMargin : 0.5) + (params.marginSpeedGain != null ? params.marginSpeedGain : 0.05) * v
  var soft = params.softMargin != null ? params.softMargin : 1.1
  var halfW = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + margin
  var halfL = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + margin
  var kmax = params.maxCurvature || 0.115
  var count = params.arcCount || 31
  var hMin = params.horizonMin != null ? params.horizonMin : 10
  var aBrake = params.comfortDecel || 5
  // The planning horizon has to cover the stopping distance of the speed we want to drive, otherwise the free-path
  // limit (sqrt(2 * decel * horizon)) silently caps cruiseSpeed (26 m / 5 m/s^2 = 15.8 m/s).
  var cruiseV = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var hMax = params.horizonMax != null ? params.horizonMax : Math.min(150, Math.max(26, 1.1 * ((cruiseV * cruiseV) / (2 * aBrake)) + 10))
  var H = Math.min(hMax, hMin + Math.max((params.horizonGain != null ? params.horizonGain : 1.2) * v, (1.1 * v * v) / (2 * aBrake)))
  var Lreq = Math.min(H, (v * v) / (2 * aBrake) + 5)
  var wProg = params.wProgress != null ? params.wProgress : 1.0
  var wHead = params.wHeading != null ? params.wHeading : 2.0
  var wReq = params.wRequired != null ? params.wRequired : 60
  var wFree = params.wFree != null ? params.wFree : 10
  var wSoft = params.wSoft != null ? params.wSoft : 8
  var wSmooth = params.wSmooth != null ? params.wSmooth : 2.5
  var wTurn = params.wTurn != null ? params.wTurn : 1.5
  var minFree = params.minFree != null ? params.minFree : 4.5
  var ds = 0.75
  var turnAngles = [0.5, 1.15]

  // costmap into ego frame
  var pts = av.points || []
  var ox = []
  var oy = []
  for (var i = 0; i < pts.length; i++) {
    var dx = pts[i][0] - pos[0]
    var dz = pts[i][1] - pos[2]
    var px = dx * e.fwd[0] + dz * e.fwd[2]
    var py = dx * e.left[0] + dz * e.left[2]
    if (px > -halfL - soft - 3 && px < H + halfL + soft + 3 && py > -H - 4 && py < H + 4) {
      ox.push(px)
      oy.push(py)
    }
  }

  // pose along a path: turn at `kappa` for `turnLen`, then straight
  function poseAt(kappa, turnLen, s, out) {
    var sa = s < turnLen ? s : turnLen
    var th = kappa * sa
    var x
    var y
    if (Math.abs(kappa) < 1e-6) {
      x = sa
      y = 0
    } else {
      x = Math.sin(th) / kappa
      y = (1 - Math.cos(th)) / kappa
    }
    if (s > turnLen) {
      x += Math.cos(th) * (s - turnLen)
      y += Math.sin(th) * (s - turnLen)
    }
    out.x = x
    out.y = y
    out.th = th
  }
  var P = { x: 0, y: 0, th: 0 }

  // forward paths only sweep the front of the footprint: an obstacle already behind/at the tail (touching
  // start pose) must not veto driving away from it
  var rearIgnore = params.rearIgnore != null ? params.rearIgnore : 1.4
  // Start already inside the margin (parked next to a car / wall): the full margin would veto every path at s = 0 and
  // freeze the car. The margin therefore starts at the clearance the car has now and grows to the full value over
  // `marginRamp` metres — a path may not get closer than the car already is, but it may drive away.
  var hullL = halfL - margin
  var hullW = halfW - margin
  var startGap = margin + soft
  for (var sg = 0; sg < ox.length; sg++) {
    if (ox[sg] < -hullL + rearIgnore - margin) continue
    var gap = Math.max(Math.abs(ox[sg]) - hullL, Math.abs(oy[sg]) - hullW)
    if (gap < startGap) startGap = gap
  }
  var ramp = params.marginRamp != null ? params.marginRamp : 3
  function freeLength(kappa, turnLen, hw, hl) {
    var extra = hw - hullW
    var m0 = Math.max(0, Math.min(extra, startGap - 0.05))
    for (var s = 0; s <= H; s += ds) {
      var m = s >= ramp || m0 >= extra ? extra : m0 + ((extra - m0) * s) / ramp
      var hwS = hullW + m
      var hlS = hullL + m
      var hlRear = Math.max(0.3, hlS - rearIgnore)
      poseAt(kappa, turnLen, s, P)
      var ct = Math.cos(P.th)
      var st = Math.sin(P.th)
      for (var q = 0; q < ox.length; q++) {
        var rx = ox[q] - P.x
        var ry = oy[q] - P.y
        var lx = ct * rx + st * ry
        var ly = -st * rx + ct * ry
        if (lx > -hlRear && lx < hlS && ly > -hwS && ly < hwS) return Math.max(0, s - ds)
      }
    }
    return H
  }

  var prev = state.prevKappa || 0
  var prevTurn = state.prevTurn || 0
  var best = null
  var bestCost = Infinity
  var bestHard = 0
  var bestSoft = 0
  var bestTurnLen = 0
  var cand = []
  // Direct aim: turn at curvature `kappa` until the car points at the goal, then drive straight (shortest way when the
  // way is free). Returns the turn angle (rad), or 0 when the goal is on the other side / cannot be aimed at this way.
  function aimTurnAngle(kappa) {
    var ak = Math.abs(kappa)
    if (ak < 1e-6) return 0
    var gyS = kappa > 0 ? gy : -gy
    if (gyS <= 0.05 && gx > 0) return 0
    var prevF = null
    for (var th = 0.02; th <= Math.PI; th += 0.02) {
      var x = Math.sin(th) / ak
      var y = (1 - Math.cos(th)) / ak
      var f = Math.atan2(gyS - y, gx - x) - th
      while (f > Math.PI) f -= 2 * Math.PI
      while (f < -Math.PI) f += 2 * Math.PI
      if (prevF !== null && prevF > 0 && f <= 0) return th
      prevF = f
    }
    return 0
  }
  for (var a = 0; a < count; a++) {
    var kappa = count === 1 ? 0 : -kmax + (2 * kmax * a) / (count - 1)
    var aimAng = aimTurnAngle(kappa)
    var nAngles = turnAngles.length + (aimAng > 0 ? 1 : 0)
    for (var ti = 0; ti < nAngles; ti++) {
      if (Math.abs(kappa) < 1e-6 && ti > 0) continue
      var isAim = ti >= turnAngles.length
      var turnLen = Math.abs(kappa) < 1e-6 ? H : Math.min(H, (isAim ? aimAng : turnAngles[ti]) / Math.abs(kappa))
      var fHard = freeLength(kappa, turnLen, halfW, halfL)
      var fSoft = freeLength(kappa, turnLen, halfW + soft - margin, halfL + soft - margin)
      var L = fHard
      var Lpose = L
      if (isAim) {
        // judged where it reaches the goal (not far beyond it); free-length terms still use the full free path
        poseAt(kappa, turnLen, turnLen, P)
        Lpose = Math.min(L, turnLen + Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y)))
      }
      poseAt(kappa, turnLen, Lpose, P)
      var gdEnd = Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y))
      var progress = goalDist - gdEnd
      var herr = Math.atan2(gy - P.y, gx - P.x) - P.th
      while (herr > Math.PI) herr -= 2 * Math.PI
      while (herr < -Math.PI) herr += 2 * Math.PI
      var cost =
        -wProg * progress +
        wHead * Math.abs(herr) +
        wReq * Math.max(0, 1 - L / Lreq) +
        wFree * (1 - L / H) +
        wSoft * (1 - Math.min(fSoft, H) / H) +
        wSmooth * (Math.abs(kappa - prev) / kmax) +
        wTurn * Math.abs(kappa * turnLen)
      if (cost < bestCost) {
        bestCost = cost
        best = kappa
        bestHard = fHard
        bestSoft = fSoft
        bestTurnLen = turnLen
      }
      if (params.debugDraw !== false && a % 8 === 0 && ti === 0) cand.push([kappa, turnLen, fHard])
    }
  }
  state.prevKappa = best

  // lateral clearance of the chosen path over the distance that matters (beyond the hard margin)
  var clearance = 0
  var margins = [0.5, 1.0, 1.5, 2.5]
  var needLen = Math.min(bestHard, Lreq)
  for (var mi = 0; mi < margins.length; mi++) {
    var fm = freeLength(best, bestTurnLen, halfW + margins[mi], halfL + margins[mi])
    if (fm >= needLen - 1e-6) clearance = margins[mi]
    else break
  }

  av.plan = {
    kappa: best,
    free: bestHard,
    freeSoft: bestSoft,
    clearance: clearance,
    margin: margin,
    blocked: bestHard < minFree,
    startGap: startGap,
    horizon: H,
    required: Lreq,
    cost: bestCost,
  }
  api.watch('av.plan.kappa', Math.round(best * 1000) / 1000)
  api.watch('av.plan.free', Math.round(bestHard * 10) / 10 + ' clr ' + clearance)

  if (params.debugDraw !== false) {
    var y0 = pos[1]
    var W = { x: 0, y: 0, th: 0 }
    function world(x, y) {
      return [pos[0] + e.fwd[0] * x + e.left[0] * y, y0, pos[2] + e.fwd[2] * x + e.left[2] * y]
    }
    function drawPath(kk, tl, len, color, step) {
      var prevW = null
      for (var s = 0; s <= len + 1e-6; s += step) {
        poseAt(kk, tl, s, W)
        var wp = world(W.x, W.y)
        if (prevW) api.visualizeLine(prevW, wp, color)
        prevW = wp
      }
    }
    api.visualizeLine(pos, [aim[0], y0, aim[2]], '#ffcc00')
    for (var ci = 0; ci < cand.length; ci++) drawPath(cand[ci][0], cand[ci][1], cand[ci][2], '#3a5a9a', Math.max(4, cand[ci][2] / 3))
    drawPath(best, bestTurnLen, bestHard, '#22dd66', 2.5)
    if (bestHard < H) drawPath(best, bestTurnLen, Math.min(H, bestHard + 3), '#ff8800', 3)
  }
  return {}
}

// AV stack · PLAN / speed planner.
// v_des = min(cruise, obstacle in the path (auto-brake), obstacle right next to the car, route bends ahead, lateral acceleration, goal approach).
//  - In the path: auto-brake logic — v <= sqrt(2 * brakeDecel * (free distance - stopMargin)). Far obstacles only matter once they are within braking distance.
//  - Next to the car: only obstacles within `obstacleSlowRadius` (default 5 m) of the hull slow the car, linearly from `obstacleSlowFactor * cruiseSpeed` (touching) up to cruise (at the radius).
//    Obstacles that are farther away, or behind the car, never slow it. Set the radius to 0 to switch this off.
// Goal approach only slows for the FINAL waypoint (av.mission, else params.waypoints; otherwise every goal is final).
// The free-path (stopping distance) limit always wins over the floors.
// Publishes av.plan.vDesired / av.plan.vLimit ('cruise' | 'free' | 'near' | 'route' | 'curve' | 'goal').
// params: cruiseSpeed, minSpeed (lowest speed while driving, default 4), comfortDecel (brake decel for obstacles in the path, default 5),
//         stopMargin, obstacleSlowRadius (5), obstacleSlowFactor (speed right next to an obstacle as a fraction of cruise, default 0.5), maxLatAccel (default 9),
//         goalDecel (gentler braking used for the final approach, default 3), goalCrawlSpeed (floor while arriving, default 2), goalTolerance, vehicleWidth, vehicleLength, waypoints
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan) return {}
  var plan = av.plan
  if (plan.override) return {}
  var cruise = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var aBrake = params.comfortDecel || 5
  var aLat = params.maxLatAccel || 9
  var stopMargin = params.stopMargin != null ? params.stopMargin : 1.2
  var crawl = params.minSpeed != null ? params.minSpeed : params.crawlSpeed != null ? params.crawlSpeed : 4
  var limit = 'cruise'
  var v = cruise
  // obstacle in the path: auto-brake (free distance of the chosen path)
  var vFree = Math.sqrt(2 * aBrake * Math.max(0, plan.free - stopMargin))
  if (vFree < v) {
    v = vFree
    limit = 'free'
  }
  // obstacles right next to the car (hull distance), never farther than the slow radius, never behind
  var slowR = params.obstacleSlowRadius != null ? params.obstacleSlowRadius : 5
  if (slowR > 0 && av.points && av.points.length && av.ego) {
    var e = av.ego
    var hl = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2
    var hw = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2
    var pos = input.position
    var dn = Infinity
    for (var i = 0; i < av.points.length; i++) {
      var dx = av.points[i][0] - pos[0]
      var dz = av.points[i][1] - pos[2]
      var lx = dx * e.fwd[0] + dz * e.fwd[2]
      if (lx < -hl) continue // behind the rear: irrelevant for a forward-driving car
      var ly = dx * e.left[0] + dz * e.left[2]
      var ex = Math.max(Math.abs(lx) - hl, 0)
      var ey = Math.max(Math.abs(ly) - hw, 0)
      var d = Math.sqrt(ex * ex + ey * ey)
      if (d < dn) dn = d
    }
    if (dn < slowR) {
      var vNear = Math.max(crawl, (params.obstacleSlowFactor != null ? params.obstacleSlowFactor : 0.5) * cruise)
      var t = Math.min(1, Math.max(0, (dn - 0.3) / Math.max(0.01, slowR - 0.3)))
      var vProx = vNear + (cruise - vNear) * t
      if (vProx < v) {
        v = vProx
        limit = 'near'
      }
    }
  }
  // bends ahead on the global route (corner speed, reachable by braking)
  if (av.route && av.route.vLimit < v) {
    v = Math.max(av.route.vLimit, crawl)
    limit = 'route'
  }
  var k = Math.abs(plan.kappa)
  if (k > 1e-4) {
    var vCurve = Math.sqrt(aLat / k)
    if (vCurve < v) {
      v = Math.max(vCurve, crawl)
      limit = 'curve'
    }
  }
  if (av.goal) {
    var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
    var wps = params.waypoints
    var isFinal = true
    if (av.mission) {
      isFinal = av.mission.isFinal
    } else if (wps && wps.length) {
      var last = wps[wps.length - 1]
      isFinal = Math.abs(av.goal.x - last[0]) < 0.05 && Math.abs(av.goal.z - last[1]) < 0.05
    }
    if (isFinal) {
      var vGoal = Math.sqrt(2 * (params.goalDecel != null ? params.goalDecel : 3) * Math.max(0, av.goal.dist - tol))
      if (vGoal < v) {
        // arriving: creep in slowly enough to stop inside the hold radius (own, lower floor than the driving minimum)
        v = Math.max(vGoal, params.goalCrawlSpeed != null ? params.goalCrawlSpeed : 2)
        limit = 'goal'
      }
    }
  }
  if (!plan.blocked && v < crawl && limit !== 'goal') v = crawl
  // The stopping-distance limit is a safety bound, not a preference: no floor (minSpeed, route/curve crawl, goal crawl)
  // may lift the speed above what can still stop within the free path (minSpeed 9.4 with 5 m free and 2 m/s² used to
  // drive at 9.4 instead of 3.9 m/s — straight into the AEB, then stop-and-go).
  if (v > vFree) {
    v = vFree
    limit = 'free'
  }
  plan.vDesired = v
  plan.vLimit = limit
  api.watch('av.vLimit', limit + ' ' + v.toFixed(1))
  return {}
}

// AV stack · PLAN / behaviour supervisor.
// Watches planner health and flags `av.needManeuver` when the local planner is blocked
// or the vehicle is stuck; holds at the final goal. Sets av.mode ('drive' | 'hold').
// debug draw: vertical mast above the car = status (green drive, orange needs manoeuvre, white hold).
// Simulated time only. params: stuckTime, blockedTime, holdAtGoal, goalTolerance
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var plan = av.plan
  if (state.stuckT === undefined) {
    state.stuckT = 0
    state.blockedT = 0
  }
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var blockedTime = params.blockedTime != null ? params.blockedTime : 0.4
  var wantsMove = (plan.vDesired || 0) > 0.8
  if (wantsMove && Math.abs(e.speed) < 0.25) state.stuckT += dt
  else state.stuckT = 0
  if (plan.blocked && Math.abs(e.speed) < 1.2) state.blockedT += dt
  else state.blockedT = 0
  av.needManeuver = state.blockedT > blockedTime || state.stuckT > stuckTime
  av.mode = av.override ? 'maneuver' : 'drive'
  var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
  var finalGoal = !av.mission || av.mission.isFinal
  if (params.holdAtGoal !== false && finalGoal && av.goal && av.goal.dist < tol) {
    av.mode = 'hold'
    plan.override = false
    plan.vDesired = 0
    plan.kappa = 0
  }
  if (params.debugDraw !== false) {
    // status mast above the car: green drive, orange manoeuvre requested, white hold
    var c = av.mode === 'hold' ? '#ffffff' : av.needManeuver ? '#ff8800' : '#00ff66'
    api.visualizeLine([e.pos[0], e.pos[1] + 1.2, e.pos[2]], [e.pos[0], e.pos[1] + 4, e.pos[2]], c)
  }
  return {}
}

// AV stack · CONTROL / lateral (curvature tracking).
// steering = feed-forward(kappa_plan / kappaPerSteer) + P feedback on measured curvature,
// with a steering-rate limiter (comfort / actuator model).
// debug draw: white = commanded steering direction.
// params: kappaPerSteer, fbGain, steerRate
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var kps = params.kappaPerSteer || 0.12
  var fb = params.fbGain != null ? params.fbGain : 0.35
  var rate = params.steerRate != null ? params.steerRate : 4
  var kCmd = av.plan.kappa
  var steer = kCmd / kps
  if (Math.abs(e.speed) > 2 && av.mode !== 'reverse') {
    steer += (fb * (kCmd - e.kappa)) / kps
  }
  if (steer > 1) steer = 1
  if (steer < -1) steer = -1
  var prev = state.steer || 0
  var maxStep = rate * dt
  if (steer > prev + maxStep) steer = prev + maxStep
  if (steer < prev - maxStep) steer = prev - maxStep
  state.steer = steer
  // car2 treats exactly 0 as "no steering command" (wheel re-centres on its own)
  input.actions.steering_angle = Math.abs(steer) < 1e-4 ? 0 : steer
  av.cmdSteer = steer
  if (params.debugDraw !== false) {
    // white: commanded steering direction from the nose (4 m chord)
    var th = steer * kps * 4
    var nose = api.vec.offsetAlong(input.position, e.fwd, 2)
    var dir = [e.fwd[0] * Math.cos(th) + e.left[0] * Math.sin(th), 0, e.fwd[2] * Math.cos(th) + e.left[2] * Math.sin(th)]
    api.visualizeLine(nose, api.vec.offsetAlong(nose, dir, 4), '#ffffff')
  }
  return {}
}

// AV stack · CONTROL / longitudinal (model-based speed control with an online-identified actuator model).
// The car2 actuator turns a command u = throttle − brake into a force, so the body follows
//     a = G · u − D · sgn(v)          (G: m/s² per unit command, D: sliding/rolling friction deceleration, m/s²)
// G and D differ by orders of magnitude between bodies (reference car: G ≈ 156, D ≈ 60; a light icy car with power 2400:
// G ≈ 1200, D ≈ 1). A fixed deadband / gain only fits one of them — on the other the smallest command jumps the speed by
// metres per second per frame and the controller bang-bangs (the "jitter"). So G and D are estimated online (recursive
// least squares on the previous frame's command vs. the measured acceleration) and the controller asks for an
// acceleration: u = (a_des + D · s) / G, a_des = clamp((v_target − v) / tau + I, −maxDecel, maxAccel).
// Publishes av.actuator {G, D, u} (u = applied command; a later stage that overrides the actions must update it — the AEB does). The AEB uses it to brake with a deceleration instead of a raw command) and av.cmd.
// At rest the static friction can exceed D: a breakaway offset ramps while demanded motion does not start.
// params: tau, ki, maxAccel, maxDecel, maxThrottle, maxBrake, breakawayRate, gainInit, frictionInit, forget
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var vDes = av.plan.vDesired || 0
  var tau = params.tau != null ? params.tau : 0.35
  var ki = params.ki != null ? params.ki : 0.6
  var maxAcc = params.maxAccel != null ? params.maxAccel : 10
  var maxDec = params.maxDecel != null ? params.maxDecel : 12
  var maxThr = params.maxThrottle != null ? params.maxThrottle : 1
  var maxBrk = params.maxBrake != null ? params.maxBrake : 1
  var lam = params.forget != null ? params.forget : 0.97
  var v = e.speed
  if (state.G === undefined) {
    state.G = params.gainInit != null ? params.gainInit : 156
    state.D = params.frictionInit != null ? params.frictionInit : 60
    // RLS covariance over [G, D]
    state.P = [1e4, 0, 0, 1e3]
    state.uPrev = 0
    state.vPrev = v
    state.I = 0
    state.boost = 0
    state.samples = 0
  }
  // --- identify: last frame's command produced this frame's acceleration ---
  // a later stage (AEB) that overrode the command reports what was really applied in last frame's av.actuator.u
  if (state.lastAct && typeof state.lastAct.u === 'number') state.uPrev = state.lastAct.u
  var aMeas = dt > 1e-6 ? (v - state.vPrev) / dt : 0
  var vMid = 0.5 * (v + state.vPrev)
  var pushing = input.environment && input.environment.isTouchingSide
  // (sliding friction acts as soon as the body slides: learn from 0.12 m/s on, so a car creeping in force balance is not
  // stuck between 'too slow to learn' and 'too fast for the breakaway push')
  if (!pushing && Math.abs(state.uPrev) > 1e-4 && Math.abs(vMid) > 0.12 && state.vPrev * v > 0) {
    var x0 = state.uPrev
    var x1 = -(vMid > 0 ? 1 : -1)
    var P = state.P
    var px0 = P[0] * x0 + P[1] * x1
    var px1 = P[2] * x0 + P[3] * x1
    var den = lam + x0 * px0 + x1 * px1
    var k0 = px0 / den
    var k1 = px1 / den
    var err = aMeas - (state.G * x0 + state.D * x1)
    // robust: a collision / kerb spike must not wreck the model
    var lim = 50 + 0.5 * Math.abs(state.G * x0)
    if (err > lim) err = lim
    if (err < -lim) err = -lim
    state.G = Math.max(10, Math.min(20000, state.G + k0 * err))
    state.D = Math.max(0, Math.min(300, state.D + k1 * err))
    var n0 = (P[0] - k0 * px0) / lam
    var n1 = (P[1] - k0 * px1) / lam
    var n2 = (P[2] - k1 * px0) / lam
    var n3 = (P[3] - k1 * px1) / lam
    // keep the covariance bounded (forgetting without excitation blows it up)
    state.P = [Math.min(n0, 1e5), n1, n2, Math.min(n3, 1e4)]
    state.samples++
  }
  // Rescue path: the command clearly dominates friction and the response is far larger than the model predicts
  // (G underestimated — e.g. learned while pushing against a slope, or while the speed sign flipped every frame, where
  // the RLS is gated off). Pull G towards the observed gain directly so the controller stops saturating.
  // Only for a saturated command (that is the failure mode); collisions also produce big accelerations and must not pump G.
  if (!pushing && Math.abs(state.uPrev) > 0.3 && aMeas * state.uPrev > 0 && Math.abs(aMeas) > 3 * state.D + 10) {
    var gObs = Math.abs(aMeas / state.uPrev)
    if (gObs > 1.5 * state.G) state.G = Math.min(20000, state.G + 0.3 * (gObs - state.G))
  }
  var G = state.G
  var D = state.D

  // --- control ---
  var u = 0
  var holding = Math.abs(vDes) < 0.05 && Math.abs(v) < 0.3
  if (holding) {
    state.I = 0
    state.boost = 0
  } else {
    var errV = vDes - v
    // integral (acceleration units) only while not saturated, so steady errors (slope, model error) vanish
    var aDes = errV / tau + state.I
    if (aDes > maxAcc) aDes = maxAcc
    if (aDes < -maxDec) aDes = -maxDec
    if (aDes > -maxDec && aDes < maxAcc) state.I = Math.max(-3, Math.min(3, state.I + ki * errV * dt))
    // never brake through zero within one frame: the deceleration that stops the car this frame is the most we ask for
    if (Math.abs(vDes) < 0.05) {
      var stopA = Math.abs(v) / Math.max(dt, 1e-3)
      if (v > 0 && aDes < -stopA) aDes = -stopA
      if (v < 0 && aDes > stopA) aDes = stopA
    }
    // friction feed-forward in the direction of travel (at rest: of the wanted motion)
    var s = Math.abs(v) > 0.3 ? (v > 0 ? 1 : -1) : aDes > 0 ? 1 : aDes < 0 ? -1 : 0
    var fric = D * s
    // at rest, friction helps braking: no reverse push needed to stay stopped
    if (Math.abs(v) <= 0.3 && Math.abs(vDes) < 0.05) fric = 0
    u = (aDes + fric) / G
    // breakaway: demanded motion does not start (static friction > D) -> ramp an extra push
    var want = Math.abs(vDes) > 0.3
    // far below the demanded speed and not gaining (static friction / force balance the model does not explain yet)
    var stuck = want && vDes * v < Math.min(1, 0.4 * Math.abs(vDes)) && vDes * aDes > 0 && aMeas * (vDes > 0 ? 1 : -1) < 0.5
    if (stuck) state.boost = Math.min(1, state.boost + (params.breakawayRate != null ? params.breakawayRate : 0.5) * dt)
    // keep the push until the car really drives (else it jerks, stops, ramps again); then relax it slowly
    else if (!want || vDes * v >= Math.min(1, 0.4 * Math.abs(vDes))) state.boost = Math.max(0, state.boost - 0.5 * dt)
    if (state.boost > 0 && want) u += (vDes > 0 ? 1 : -1) * state.boost
    // stopping: never push along the direction of travel (friction alone may decelerate harder than maxDecel — fine)
    if (Math.abs(vDes) < 0.05 && u * v > 0) u = 0
  }
  if (u > maxThr) u = maxThr
  if (u < -maxBrk) u = -maxBrk
  state.uPrev = u
  state.vPrev = v
  input.actions.throttle = u > 0 ? u : 0
  input.actions.brake = u < 0 ? -u : 0
  // mailbox: stages after this one write the command they actually applied into av.actuator.u
  av.actuator = { G: G, D: D, samples: state.samples, u: u }
  state.lastAct = av.actuator
  av.cmd = { throttle: input.actions.throttle, brake: input.actions.brake }
  api.watch('av.throttle', 'u ' + u.toFixed(3) + ' G ' + G.toFixed(0) + ' D ' + D.toFixed(1) + ' vd ' + vDes.toFixed(1))
  return {}
}

// AV stack · SAFETY / autonomous emergency braking (independent monitor, own sensing).
// Runs after control and may only reduce throttle / add brake. Uses a smaller margin while the manoeuvre planner is driving (it already keeps swept clearance).
// Brakes with a deceleration (aebDecel), turned into a command with the actuator model the longitudinal stage identified
// (av.actuator {G, D}): a raw brake value means 360 m/s² on a light, powerful car and flips its speed within a frame.
// Footprint from av.vehicle (look-ahead starts at the nose, spread covers the body width).
// debug draw: dark gold = AEB look-ahead, red = AEB triggered.
// params: aebDecel, aebMargin, aebHalfWidth
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  if (e.speed < 0.8) {
    av.aeb = false
    return {}
  }
  var a = params.aebDecel || 7
  var margin = params.aebMargin != null ? params.aebMargin : 1.0
  if (av.mode === 'maneuver') margin = 0.2
  var len = (av.vehicle && av.vehicle.length) || params.vehicleLength || 4
  var wid = (av.vehicle && av.vehicle.width) || params.vehicleWidth || 2
  var hw = params.aebHalfWidth != null ? params.aebHalfWidth : Math.max(0.9, wid / 2 - 0.1)
  var need = (e.speed * e.speed) / (2 * a) + margin
  var origin = api.vec.offsetAlong(input.position, e.fwd, len / 2 + 0.3)
  var hit = api.raycastSpread(origin, e.fwd, need + 1, hw, 5, { visualize: false })
  av.aeb = false
  var drawOn = params.debugDraw !== false
  if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, need), '#b8860b')
  if (hit.hit && hit.distance < need) {
    if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, hit.distance), '#ff0000')
    av.aeb = true
    // deceleration needed to stop before the hit (at least aebDecel), never more than stops the car within this frame
    var room = Math.max(0.1, hit.distance - 0.2 * margin)
    var dec = Math.max(a, (e.speed * e.speed) / (2 * room))
    dec = Math.min(dec, e.speed / Math.max(dt, 1e-3))
    var act = av.actuator
    var u
    if (act && act.G > 0) u = (-dec + act.D) / act.G
    else u = -Math.min(1, 0.3 + (need - hit.distance) / need)
    var cur = (input.actions.throttle || 0) - (input.actions.brake || 0)
    if (u < cur) {
      input.actions.throttle = u > 0 ? u : 0
      input.actions.brake = u < 0 ? Math.min(1, -u) : 0
      // tell the longitudinal controller what was really applied (its actuator identification)
      if (act) act.u = input.actions.throttle - input.actions.brake
    }
    api.watch('av.aeb', Math.round(hit.distance * 10) / 10 + ' m dec ' + dec.toFixed(1))
  }
  return {}
}

// AV stack · MISSION: position-only waypoint sequencer.
// Publishes `input.target` (current waypoint) and `av.mission` {index, waypoints, isFinal} for the whole stack.
// Position-only on purpose: a pass-through waypoint must never demand a heading (the stock targetPoseInput does).
// Edit `waypoints` as [[x, z], ...] (world metres, floor plane). The last waypoint is the stop point (mode 'stop')
// or the loop restarts (mode 'loop').
// params: waypoints, acceptRadius (default 9), mode ('stop' | 'loop'), speed (target speed hint)
function transform(input, dt, params, state, api) {
  var av = input.av
  var wps = params.waypoints
  if (!av || !wps || !wps.length) return {}
  if (state.i === undefined) state.i = 0
  var radius = params.acceptRadius != null ? params.acceptRadius : 9
  var loop = params.mode === 'loop'
  var pos = input.position
  var last = wps.length - 1
  var cur = wps[state.i]
  var d = Math.sqrt((pos[0] - cur[0]) * (pos[0] - cur[0]) + (pos[2] - cur[1]) * (pos[2] - cur[1]))
  if (d < radius) {
    if (state.i < last) state.i += 1
    else if (loop) state.i = 0
    cur = wps[state.i]
  }
  input.target = {
    pose: { position: [cur[0], 0, cur[1]], rotation: [0, 0, 0] },
    speed: params.speed != null ? params.speed : 10,
  }
  av.mission = { index: state.i, waypoints: wps, isFinal: !loop && state.i === last }
  return {}
}

// AV stack · SENSE / state estimation ("localization" layer).
// Publishes the ego state on the shared blackboard `input.av.ego` for all later stages.
// Also publishes av.vehicle {width, length, height} = max(params, own box collider) used by all planners.
// debug draw (params.debugDraw, default true): cyan = velocity vector.
// Owns the simulated clock (state.t) so no downstream stage needs a wall clock.
function transform(input, dt, params, state, api) {
  // fresh blackboard every frame (the input object is reused by the runtime)
  var av = (input.av = {})
  // a goal source running in front of this stage hands its mission over via input.goalSource (see av-wander.js)
  if (input.goalSource) {
    av.mission = input.goalSource
    input.goalSource = undefined
  }
  // Goal contract: a source that declares `input.target.isFinal === false` (preset wanderer, ...) makes the stack cruise
  // through its goals instead of braking at each one. (Sources without that flag are single, final goals.)
  if (!av.mission && input.target && input.target.pose && input.target.isFinal === false) {
    var tp = input.target.pose.position
    av.mission = { index: 0, waypoints: [[tp[0], tp[2]]], isFinal: false }
  }
  if (state.t === undefined) {
    state.t = 0
    state.speedF = 0
    state.prevSpeed = 0
    state.accelF = 0
  }
  state.t += dt
  // Vehicle footprint: never plan with a hull smaller than the entity's own box collider (a 4 x 8 m body driven with the
  // 2 x 4 defaults touches every neighbour). params.vehicleWidth / vehicleLength can only enlarge it. Cached (getEntity copies).
  if (state.vehT === undefined || state.t - state.vehT > 2) {
    state.vehT = state.t
    var ent = api.getEntity(input.entityId)
    var sh = ent && ent.shape
    var sc = (ent && ent.scale) || [1, 1, 1]
    state.vehW = sh && sh.type === 'box' ? Math.abs(sh.width * (sc[0] || 1)) : 0
    state.vehL = sh && sh.type === 'box' ? Math.abs(sh.depth * (sc[2] || 1)) : 0
    state.vehH = sh && sh.type === 'box' ? Math.abs(sh.height * (sc[1] || 1)) : 0
  }
  av.vehicle = {
    width: Math.max(params.vehicleWidth || 2, state.vehW || 0),
    length: Math.max(params.vehicleLength || 4, state.vehL || 0),
    height: state.vehH || 0,
  }
  var up = api.getUpVector(input.rotation)
  var fwd = api.vec.normalize(api.vec.projectOntoPlane(api.getForwardVector(input.rotation), up))
  var left = api.vec.normalize(api.vec.cross(up, fwd))
  var speed = api.vec.getForwardSpeed(input.velocity, fwd)
  var yawRate = api.vec.dot(input.angularVelocity, up)
  var a = dt > 1e-6 ? (speed - state.prevSpeed) / dt : 0
  state.prevSpeed = speed
  state.accelF += (a - state.accelF) * Math.min(1, dt * 8)
  state.speedF += (speed - state.speedF) * Math.min(1, dt * 20)
  av.ego = {
    t: state.t,
    dt: dt,
    pos: input.position,
    fwd: fwd,
    left: left,
    up: up,
    speed: speed,
    speedF: state.speedF,
    accel: state.accelF,
    yawRate: yawRate,
    kappa: Math.abs(speed) > 1.5 ? yawRate / speed : 0,
  }
  api.watch('av.speed', Math.round(speed * 10) / 10)
  if (params.debugDraw !== false) {
    // cyan: velocity vector
    api.visualizeLine(input.position, api.vec.add(input.position, api.vec.scale(input.velocity, 0.6)), '#00e5ff')
  }
  return {}
}

// AV stack · SENSE / perception.
// 360° range-scan ring (lidar-like, mounted at the vehicle centre, rays start on the hull)
// + obstacle memory ("local costmap") so the planners also know what is behind / beside.
// Publishes: av.scan {angles, ranges, range}, av.points [[x,z],...] (world), av.rearClear.
// debug draw (params.debugDraw, debugRayStride, debugMaxPoints): red = lidar hit rays, magenta ticks = costmap points.
// Extra ray plane at the car's top edge (params.rayLevels false = off); params.lowRayClearance (m above the underside) adds a low plane.
// Memory clearing: remembered cells that fresh rays pass through (within memClearRange 45 m, 0 = off) are dropped, so moving obstacles leave no ghost trail.
// params: drivableArea [xmin, xmax, zmin, zmax] (virtual walls at the edge), edgeStep, rayCount, fovDeg, sensorRange, memoryTtl, memoryCell, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var n = params.rayCount || 72
  var fov = ((params.fovDeg || 360) * Math.PI) / 180
  // Sense far enough to stop: cruise speed needs v^2 / (2 * decel) of free view (default 24 m covers the stock 10 m/s).
  var cruiseV = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var stopD = (cruiseV * cruiseV) / (2 * (params.comfortDecel || 5))
  var range = params.sensorRange || Math.min(150, Math.max(24, 1.1 * stopD + 8))
  var ttl = params.memoryTtl != null ? params.memoryTtl : 15
  var cell = params.memoryCell || 0.5
  var hl = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + 0.15
  var hw = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + 0.15
  if (!state.mem) state.mem = {}
  var mem = state.mem
  var pos = input.position
  var full = fov >= 2 * Math.PI - 1e-3
  var angles = []
  var ranges = []
  var rearClear = params.rearRange || 8
  var draw = params.debugDraw !== false
  var rayInfo = []
  var rayStride = params.debugRayStride || 2
  // extra ray planes (offsets from the centre ray): the car's top edge (+ optionally just above its underside)
  var levels = []
  var carH = av.vehicle && av.vehicle.height ? av.vehicle.height : 0
  if (params.rayLevels !== false && carH > 0.3) {
    levels = [carH / 2 - 0.08]
    // optional underside plane for low bars (off by default: ground bumps then read as obstacles)
    if (params.lowRayClearance != null) levels.push(-carH / 2 + params.lowRayClearance)
  }
  for (var i = 0; i < n; i++) {
    var th = full ? -Math.PI + (2 * Math.PI * i) / n : n === 1 ? 0 : -fov / 2 + (fov * i) / (n - 1)
    var c = Math.cos(th)
    var s = Math.sin(th)
    var dir = [
      e.fwd[0] * c + e.left[0] * s,
      e.fwd[1] * c + e.left[1] * s,
      e.fwd[2] * c + e.left[2] * s,
    ]
    // start just outside the hull rectangle along this ray
    var tHull = Math.min(Math.abs(c) > 1e-6 ? hl / Math.abs(c) : 1e9, Math.abs(s) > 1e-6 ? hw / Math.abs(s) : 1e9)
    var origin = api.vec.offsetAlong(pos, dir, tHull)
    // One horizontal plane misses what curves away from it (a sphere / dome is farther at the car's top edge than at the
    // equator, a low bar hides under the plane): cast at the car's top edge too and keep the nearest hit.
    var r = api.raycast(origin, dir, range, { visualize: false })
    for (var li = 0; li < levels.length; li++) {
      var lo = [origin[0], origin[1] + levels[li], origin[2]]
      var rl = api.raycast(lo, dir, range, { visualize: false })
      if (rl.hit && (!r.hit || rl.distance < r.distance)) {
        r = rl
        origin = lo
      }
    }
    angles.push(th)
    if (r.hit) {
      if (draw && i % rayStride === 0) api.visualizeLine(origin, api.vec.offsetAlong(origin, dir, r.distance), '#ff4d4d')
      ranges.push(r.distance)
      rayInfo.push([dir, tHull, r.distance])
      var hx = origin[0] + dir[0] * r.distance
      var hz = origin[2] + dir[2] * r.distance
      mem[Math.round(hx / cell) + ',' + Math.round(hz / cell)] = { x: hx, z: hz, t: e.t }
      if (c < -0.9 && r.distance < rearClear) rearClear = r.distance
    } else {
      ranges.push(range)
      rayInfo.push([dir, tHull, range])
    }
  }
  // Free-space clearing: a remembered obstacle that a fresh ray now passes straight through is gone (a car that drove
  // on). Without it moving traffic leaves ghost trails that box the car in for the whole memory time.
  // Cells written this frame are never cleared (a ray grazing a thin obstacle must not erase it).
  var clearRange = params.memClearRange != null ? params.memClearRange : 45
  if (clearRange > 0) {
    for (var ri = 0; ri < rayInfo.length; ri++) {
      var rd = rayInfo[ri][0]
      var rs = rayInfo[ri][1]
      var rend = Math.min(rayInfo[ri][2] - 1.0, clearRange)
      for (var rt = rs + cell; rt < rend; rt += cell) {
        var kk = Math.round((pos[0] + rd[0] * rt) / cell) + ',' + Math.round((pos[2] + rd[2] * rt) / cell)
        var mm = mem[kk]
        if (mm && mm.t < e.t - 1e-6) delete mem[kk]
      }
    }
  }
  var pts = []
  // virtual walls along the edge of the drivable area (map prior): [xmin, xmax, zmin, zmax]
  var area = params.drivableArea
  if (area && area.length === 4) {
    var step = params.edgeStep || 1.2
    var reach = range
    var xs = Math.max(area[0], pos[0] - reach)
    var xe = Math.min(area[1], pos[0] + reach)
    var zs = Math.max(area[2], pos[2] - reach)
    var ze = Math.min(area[3], pos[2] + reach)
    var j
    if (pos[2] - area[2] < reach) for (j = xs; j <= xe; j += step) pts.push([j, area[2]])
    if (area[3] - pos[2] < reach) for (j = xs; j <= xe; j += step) pts.push([j, area[3]])
    if (pos[0] - area[0] < reach) for (j = zs; j <= ze; j += step) pts.push([area[0], j])
    if (area[1] - pos[0] < reach) for (j = zs; j <= ze; j += step) pts.push([area[1], j])
  }
  var keys = Object.keys(mem)
  for (var k = 0; k < keys.length; k++) {
    var m = mem[keys[k]]
    if (e.t - m.t > ttl) delete mem[keys[k]]
    else pts.push([m.x, m.z])
  }
  if (draw) {
    // magenta ticks: remembered obstacle points (costmap), nearest 60
    var near = pts
      .map(function (q) {
        var ddx = q[0] - pos[0]
        var ddz = q[1] - pos[2]
        return [ddx * ddx + ddz * ddz, q]
      })
      .sort(function (a, b) {
        return a[0] - b[0]
      })
      .slice(0, params.debugMaxPoints || 60)
    for (var pi = 0; pi < near.length; pi++) {
      var q2 = near[pi][1]
      api.visualizeLine([q2[0], pos[1] - 0.4, q2[1]], [q2[0], pos[1] + 0.5, q2[1]], '#ff00ff')
    }
  }
  av.scan = { angles: angles, ranges: ranges, range: range }
  av.points = pts
  av.rearClear = rearClear
  return {}
}

// AV stack · SENSE / mission overlay (debug only, no effect on driving).
// Draws the whole mission route: mint polyline + poles at every waypoint; the active target pole is yellow.
// Reads av.mission.waypoints (av-mission stage) or params.waypoints [[x, z], ...].
// params: waypoints, debugDraw
function transform(input, dt, params, state, api) {
  if (params.debugDraw === false) return {}
  var av = input.av
  var wps = (av && av.mission && av.mission.waypoints) || params.waypoints
  if (!wps || !wps.length) return {}
  var y = input.position[1]
  var cur = input.target && input.target.pose && input.target.pose.position
  for (var i = 0; i < wps.length; i++) {
    var w = wps[i]
    var active = cur && Math.abs(cur[0] - w[0]) < 0.05 && Math.abs(cur[2] - w[1]) < 0.05
    api.visualizeLine([w[0], y - 0.5, w[1]], [w[0], y + 5, w[1]], active ? '#ffcc00' : '#00ffcc')
    if (i > 0) api.visualizeLine([wps[i - 1][0], y - 0.4, wps[i - 1][1]], [w[0], y - 0.4, w[1]], '#7dffb0')
  }
  return {}
}

// AV stack · PLAN / route + manoeuvre planner (Hybrid-A* over forward/reverse arc primitives).
// Two jobs, one search:
//  1. ROUTE: every `routeInterval` s plans a collision-free route to the goal over the costmap and publishes
//     `av.carrot` (a point ~lookahead metres along the forward part of the route). The local planner chases
//     the carrot instead of the raw goal, so a goal behind an obstacle no longer produces endless orbits.
//  2. MANOEUVRE: if the route starts by reversing (or the car is stuck) it takes over (`av.override`): drives the
//     multi-point turn segment by segment, re-plans on drift/blockage/stall, and hands back as soon as the route
//     has a long forward run.
// Runs BEFORE the local motion planner. Simulated time only.
// debug draw: magenta = route / manoeuvre path (+ status mast while manoeuvring), orange = current segment end.
// params: maneuverSpeed, routeInterval, routeExpansions, lookahead, primitiveLength, maxExpansions,
//         gearSwitchPenalty, reversePenalty, maxReverseRun, planMargin, tightMargin, guardMargin, stallTime, stuckTime,
//         contactTtl (s, how long an unseen contact stays a virtual obstacle, default 25), contactRestTime (s at rest before a lateral stall counts as contact, default 1), contactMemory (false = off), restWaitMax (s, wait for rest before a gear change), maxOffPath (m, drop a plan the car is farther from), crawlTime,
//         goalReach, handbackFree, goalTolerance, maxCurvature, vehicleWidth, vehicleLength
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) return {}
  var gxw = tgt[0]
  var gzw = tgt[2]
  var kmax = params.maxCurvature || 0.115
  var planMargin = params.planMargin != null ? params.planMargin : 0.4
  var tightMargin = params.tightMargin != null ? params.tightMargin : 0.1
  var guardMargin = params.guardMargin != null ? params.guardMargin : 0.15
  var ell = params.primitiveLength || 1.8
  var maxExpFull = params.maxExpansions || 4000
  var routeExp = params.routeExpansions || 1500
  var routeInterval = params.routeInterval != null ? params.routeInterval : 0.8
  var lookahead = params.lookahead != null ? params.lookahead : 14
  var gearPen = params.gearSwitchPenalty != null ? params.gearSwitchPenalty : 4
  var revPen = params.reversePenalty != null ? params.reversePenalty : 4
  var handback = params.handbackFree != null ? params.handbackFree : 10
  var vMan = params.maneuverSpeed != null ? params.maneuverSpeed : 3
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var restWaitMax = params.restWaitMax != null ? params.restWaitMax : 1.2
  var maxOffPath = params.maxOffPath != null ? params.maxOffPath : 6
  var holdTol = params.goalTolerance != null ? params.goalTolerance : 3.5
  // route ends inside the waypoint acceptance zone (not only at its centre)
  var reach = params.goalReach != null ? params.goalReach : 3.5
  var maxRevRun = params.maxReverseRun != null ? params.maxReverseRun : 8
  var termHeadW = params.exitHeadingWeight != null ? params.exitHeadingWeight : 0
  var ks = [-kmax, -kmax / 2, 0, kmax / 2, kmax]
  var pos = input.position
  // next waypoint after the current target: the route should arrive heading towards it
  var nextWp = null
  var wps = av.mission ? av.mission.waypoints : params.waypoints
  if (wps && wps.length) {
    for (var wi = 0; wi < wps.length - 1; wi++) {
      if (Math.abs(wps[wi][0] - gxw) < 0.05 && Math.abs(wps[wi][1] - gzw) < 0.05) {
        nextWp = wps[wi + 1]
        break
      }
    }
  }
  var goalDist = Math.sqrt((gxw - pos[0]) * (gxw - pos[0]) + (gzw - pos[2]) * (gzw - pos[2]))
  // Contacts the lidar cannot see (a low bar under the ray plane, a car pressed against the hull): remembered as
  // virtual obstacle points so every planner after this stage routes around them instead of driving into them again.
  var contactTtl = params.contactTtl != null ? params.contactTtl : 25
  if (!state.contacts) state.contacts = []
  // drop expired marks and any mark that now lies inside (or hugging) the car's own footprint: it is obsolete by
  // definition and, left in place, makes every start pose collide so the car can never plan a way out
  var pHalfL = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + 0.1
  var pHalfW = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + 0.1
  state.contacts = state.contacts.filter(function (c) {
    if (e.t - c.t >= contactTtl) return false
    var rx = c.x - pos[0]
    var rz = c.z - pos[2]
    var lf = rx * e.fwd[0] + rz * e.fwd[2]
    var ll = rx * e.left[0] + rz * e.left[2]
    return !(Math.abs(lf) < pHalfL && Math.abs(ll) < pHalfW)
  })
  state.restT = Math.abs(e.speed) < 0.25 && goalDist > ((params.goalTolerance != null ? params.goalTolerance : 3.5)) ? (state.restT || 0) + dt : 0
  api.watch('av.contacts', state.contacts.length + ' rest ' + (state.restT || 0).toFixed(1) + ' side ' + (input.environment && input.environment.isTouchingSide ? 1 : 0))
  function markContact(g, stalledAlready) {
    // only a LATERAL contact (isTouchingSide: wall, other body, low bar) counts — isTouchingObject is also true on the floor — and only after the car has really been pushing
    // without moving for a while, and never build a cage (no new mark where a recent one already sits ahead).
    if (params.contactMemory === false) return
    if (!stalledAlready && (state.restT || 0) < (params.contactRestTime != null ? params.contactRestTime : 1.0)) return
    var cdd = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + 0.3
    for (var ck = 0; ck < state.contacts.length; ck++) {
      var dxk = state.contacts[ck].x - (pos[0] + e.fwd[0] * g * cdd)
      var dzk = state.contacts[ck].z - (pos[2] + e.fwd[2] * g * cdd)
      if (dxk * dxk + dzk * dzk < 2.25) return
    }
    var cd = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + 0.3
    var cw = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2
    for (var cl = -cw; cl <= cw + 1e-6; cl += cw) {
      state.contacts.push({
        x: pos[0] + e.fwd[0] * g * cd + e.left[0] * cl,
        z: pos[2] + e.fwd[2] * g * cd + e.left[2] * cl,
        t: e.t,
      })
    }
    if (state.contacts.length > 40) state.contacts.splice(0, state.contacts.length - 40)
  }
  if (state.contacts.length > 0) {
    var withContacts = (av.points || []).slice()
    for (var ci2 = 0; ci2 < state.contacts.length; ci2++) withContacts.push([state.contacts[ci2].x, state.contacts[ci2].z])
    av.points = withContacts
  }

  // spatial hash over costmap points + swept-footprint test (hl/hw are the active margins)
  function makeHit(pts, hlA, hwA) {
    var grid = {}
    for (var i = 0; i < pts.length; i++) {
      var key = Math.floor(pts[i][0] / 2) + ',' + Math.floor(pts[i][1] / 2)
      ;(grid[key] || (grid[key] = [])).push(pts[i])
    }
    var R = Math.sqrt(hlA * hlA + hwA * hwA)
    return function (x, z, fx, fz) {
      var x0 = Math.floor((x - R) / 2)
      var x1 = Math.floor((x + R) / 2)
      var z0 = Math.floor((z - R) / 2)
      var z1 = Math.floor((z + R) / 2)
      for (var cx = x0; cx <= x1; cx++) {
        for (var cz = z0; cz <= z1; cz++) {
          var list = grid[cx + ',' + cz]
          if (!list) continue
          for (var q = 0; q < list.length; q++) {
            var dx = list[q][0] - x
            var dz = list[q][1] - z
            var lx = dx * fx + dz * fz
            var ly = dx * fz - dz * fx
            if (lx > -hlA && lx < hlA && ly > -hwA && ly < hwA) return true
          }
        }
      }
      return false
    }
  }

  function search(sx, sz, sfx, sfz, gx, gz, pts, maxExp, marginOverride) {
    var hlS = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + planMargin
    var hwS = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + planMargin
    var hit = makeHit(pts, hlS, hwS)
    // start already inside the comfort margin (drift, soft contact): re-plan with the tight margin so
    // the planner can still drive out of the margin band instead of finding every primitive blocked
    // start already inside the comfort margin (drift, soft contact): re-plan with the tight margin so
    // the planner can still drive out of the margin band instead of finding every primitive blocked
    var marginUsed = planMargin
    if (marginOverride != null) {
      marginUsed = marginOverride
      hlS = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + marginUsed
      hwS = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + marginUsed
      hit = makeHit(pts, hlS, hwS)
    } else if (hit(sx, sz, sfx, sfz)) {
      marginUsed = tightMargin
      hlS = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + tightMargin
      hwS = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + tightMargin
      hit = makeHit(pts, hlS, hwS)
    }
    state.startMargin = marginUsed
    function dist(x, z) {
      var dx = gx - x
      var dz = gz - z
      return Math.sqrt(dx * dx + dz * dz)
    }
    // binary min-heap on f
    var heap = []
    function push(nd) {
      heap.push(nd)
      var c = heap.length - 1
      while (c > 0) {
        var p = (c - 1) >> 1
        if (heap[p].f <= heap[c].f) break
        var t = heap[p]
        heap[p] = heap[c]
        heap[c] = t
        c = p
      }
    }
    function pop() {
      var top = heap[0]
      var last = heap.pop()
      if (heap.length > 0) {
        heap[0] = last
        var c = 0
        for (;;) {
          var l = 2 * c + 1
          var r = l + 1
          var m = c
          if (l < heap.length && heap[l].f < heap[m].f) m = l
          if (r < heap.length && heap[r].f < heap[m].f) m = r
          if (m === c) break
          var t = heap[m]
          heap[m] = heap[c]
          heap[c] = t
          c = m
        }
      }
      return top
    }
    function skey(x, z, fx, fz, g) {
      var ih = Math.round((Math.atan2(fz, fx) / (2 * Math.PI)) * 36)
      if (ih < 0) ih += 36
      return Math.round(x / 0.6) + ',' + Math.round(z / 0.6) + ',' + (ih % 36) + ',' + g
    }
    var HW = 1.4
    var start = { x: sx, z: sz, fx: sfx, fz: sfz, g: 0, gear: 0, k: 0, parent: null, f: dist(sx, sz) * HW, d: 0 }
    push(start)
    var best = {}
    best[skey(sx, sz, sfx, sfz, 0)] = 0
    var bestNode = start
    var bestH = dist(sx, sz)
    var goalNode = null
    var expansions = 0
    while (heap.length > 0 && expansions < maxExp) {
      var cur = pop()
      var ck = skey(cur.x, cur.z, cur.fx, cur.fz, cur.gear)
      if (best[ck] !== undefined && cur.g > best[ck] + 1e-6) continue
      expansions++
      var h = dist(cur.x, cur.z)
      if (h < bestH) {
        bestH = h
        bestNode = cur
      }
      if (h < reach) {
        if (cur.terminal || !nextWp) {
          goalNode = cur
          break
        }
        // arrival cost: leave the goal zone heading towards the next waypoint
        var ndx = nextWp[0] - cur.x
        var ndz = nextWp[1] - cur.z
        var nl = Math.sqrt(ndx * ndx + ndz * ndz) || 1
        var cosA = Math.max(-1, Math.min(1, (cur.fx * ndx + cur.fz * ndz) / nl))
        var termG = cur.g + termHeadW * Math.acos(cosA)
        push({ x: cur.x, z: cur.z, fx: cur.fx, fz: cur.fz, g: termG, gear: cur.gear, k: cur.k, parent: cur, terminal: true, f: termG })
        continue
      }
      for (var gi = 0; gi < 2; gi++) {
        var gear = gi === 0 ? 1 : -1
        for (var ki = 0; ki < ks.length; ki++) {
          var k = ks[ki]
          var lx = cur.fz
          var lz = -cur.fx
          var revRun = gear < 0 ? (cur.gear < 0 ? cur.revRun || 0 : 0) + ell : 0
          if (revRun > maxRevRun) continue
          var ok = true
          var nx = cur.x
          var nz = cur.z
          var nfx = cur.fx
          var nfz = cur.fz
          for (var sIdx = 1; sIdx <= 4; sIdx++) {
            var d = (gear * ell * sIdx) / 4
            var th = k * d
            var ddx
            var ddy
            if (Math.abs(k) < 1e-6) {
              ddx = d
              ddy = 0
            } else {
              ddx = Math.sin(th) / k
              ddy = (1 - Math.cos(th)) / k
            }
            nx = cur.x + cur.fx * ddx + lx * ddy
            nz = cur.z + cur.fz * ddx + lz * ddy
            var ct = Math.cos(th)
            var st = Math.sin(th)
            nfx = cur.fx * ct + lx * st
            nfz = cur.fz * ct + lz * st
            if (hit(nx, nz, nfx, nfz)) {
              ok = false
              break
            }
          }
          if (!ok) continue
          var step = ell * (gear < 0 ? revPen : 1) + (Math.abs(k) / kmax) * 0.4 * ell
          if (cur.gear !== 0 && cur.gear !== gear) step += gearPen
          if (cur.gear !== 0 && cur.k !== k) step += 0.3
          var g2 = cur.g + step
          var nk = skey(nx, nz, nfx, nfz, gear)
          if (best[nk] !== undefined && best[nk] <= g2) continue
          best[nk] = g2
          push({ x: nx, z: nz, fx: nfx, fz: nfz, g: g2, gear: gear, k: k, revRun: revRun, parent: cur, f: g2 + dist(nx, nz) * HW })
        }
      }
    }
    var end = goalNode || bestNode
    if (end.terminal) end = end.parent
    var segs = []
    for (var nd = end; nd && nd.parent; nd = nd.parent) {
      var last = segs[0]
      if (last && last.g === nd.gear && last.k === nd.k) {
        last.len += ell
      } else {
        segs.unshift({ g: nd.gear, k: nd.k, len: ell, end: null })
      }
    }
    // expected pose at the end of every segment (walk the chain again, front to back)
    var chain = []
    for (var cn = end; cn; cn = cn.parent) chain.unshift(cn)
    var si = -1
    var prevG = null
    var prevK = null
    for (var ci = 1; ci < chain.length; ci++) {
      var nn = chain[ci]
      if (si < 0 || nn.gear !== prevG || nn.k !== prevK) {
        si++
        prevG = nn.gear
        prevK = nn.k
      }
      segs[si].end = { x: nn.x, z: nn.z, fx: nn.fx, fz: nn.fz }
    }
    var pathPts = []
    for (var pj = 0; pj < chain.length; pj++) pathPts.push([chain[pj].x, chain[pj].z])
    var nodes = []
    for (var nj = 0; nj < chain.length; nj++) nodes.push({ x: chain[nj].x, z: chain[nj].z, g: chain[nj].gear })
    return { segs: segs, reached: !!goalNode, expansions: expansions, hRemaining: bestH, path: pathPts, nodes: nodes }
  }

  function begin(res) {
    state.segs = res.segs
    state.idx = 0
    state.segStart = null
    state.prevGear = 0
    state.path = res.path
  }
  function deviates(seg) {
    if (!seg || !seg.end) return false
    var ex = pos[0] - seg.end.x
    var ez = pos[2] - seg.end.z
    var dot = e.fwd[0] * seg.end.fx + e.fwd[2] * seg.end.fz
    return Math.sqrt(ex * ex + ez * ez) > 0.9 || dot < 0.97
  }
  function plan(maxE) {
    var res = search(pos[0], pos[2], e.fwd[0], e.fwd[2], gxw, gzw, av.points || [], maxE, null)
    // Pressed against something (a corner touching a long wall): every primitive is blocked at the comfort margins, so
    // retry with ever smaller margins until the car can at least drive out of the contact.
    var escape = [0.05, 0.02, 0]
    for (var ei = 0; ei < escape.length && res.segs.length === 0 && !res.reached; ei++) {
      res = search(pos[0], pos[2], e.fwd[0], e.fwd[2], gxw, gzw, av.points || [], maxE, escape[ei])
    }
    return res
  }
  // route summary: first gear, length of the leading forward run, carrot point
  function summarize(res) {
    var nodes = res.nodes
    var firstGear = nodes.length > 1 ? nodes[1].g : 1
    var run = 0
    var carrot = null
    if (firstGear === 1) {
      var want = Math.min(lookahead, 6 + 1.0 * Math.max(0, e.speedF))
      var acc = 0
      for (var i = 1; i < nodes.length && nodes[i].g === 1; i++) {
        var dx = nodes[i].x - nodes[i - 1].x
        var dz = nodes[i].z - nodes[i - 1].z
        acc += Math.sqrt(dx * dx + dz * dz)
        carrot = [nodes[i].x, nodes[i].z]
        if (acc >= want) break
      }
      run = acc
      for (var j = i; j < nodes.length && nodes[j].g === 1; j++) {
        var ddx = nodes[j].x - nodes[j - 1].x
        var ddz = nodes[j].z - nodes[j - 1].z
        run += Math.sqrt(ddx * ddx + ddz * ddz)
      }
    }
    // speed limit from the bends ahead on the route: corner speed sqrt(aLat / kappa), reachable by braking
    var aLat = params.maxLatAccel || 9
    var aBrk = params.comfortDecel || 5
    var vLimit = Infinity
    var dAhead = 0
    for (var si = 0; si < res.segs.length && dAhead < 40 && res.segs[si].g > 0; si++) {
      var kk = Math.abs(res.segs[si].k)
      if (kk > 0.04) {
        var vi = Math.sqrt(aLat / kk)
        var allowed = Math.sqrt(vi * vi + 2 * aBrk * dAhead)
        if (allowed < vLimit) vLimit = allowed
      }
      dAhead += res.segs[si].len
    }
    return { firstGear: firstGear, run: run, carrot: carrot, reached: res.reached, nodes: nodes, path: res.path, vLimit: vLimit }
  }

  // stuck watchdog (own, independent of the local planner)
  if (state.stuckT === undefined) state.stuckT = 0
  if (!state.active && Math.abs(e.speed) < 0.25 && goalDist > holdTol) state.stuckT += dt
  else state.stuckT = 0
  // Scraping along an obstacle (wheels spinning against contact friction) is slow but not "stopped": also count it as
  // stuck when the car has hardly moved over a longer window while driving slowly.
  if (!state.crawlAnchor) state.crawlAnchor = [pos[0], pos[2]]
  var crawlMoved = Math.sqrt((pos[0] - state.crawlAnchor[0]) * (pos[0] - state.crawlAnchor[0]) + (pos[2] - state.crawlAnchor[1]) * (pos[2] - state.crawlAnchor[1]))
  if (state.active || goalDist <= holdTol || Math.abs(e.speed) > 1.2 || crawlMoved > 2.5) {
    state.crawlAnchor = [pos[0], pos[2]]
    state.crawlT = 0
  } else {
    state.crawlT = (state.crawlT || 0) + dt
    if (state.crawlT > (params.crawlTime != null ? params.crawlTime : 6)) {
      state.stuckT = Math.max(state.stuckT, stuckTime + 0.1)
      state.crawlT = 0
      state.crawlAnchor = [pos[0], pos[2]]
    }
  }

  if (!state.active) {
    if (state.route === undefined || e.t - state.routeT >= routeInterval) {
      state.route = summarize(plan(routeExp))
      state.routeT = e.t
      state.revFresh = true
      state.routes = (state.routes || 0) + 1
    }
    var rt = state.route
    // hysteresis: a reverse-first route must be confirmed by two consecutive plans before the car manoeuvres
    state.revVotes = rt.firstGear === -1 ? (state.revFresh ? (state.revVotes || 0) + 1 : state.revVotes || 1) : 0
    state.revFresh = false
    var wantManeuver = (rt.firstGear === -1 && (state.revVotes >= 2 || Math.abs(e.speed) < 0.3) && Math.abs(e.speed) < 1.5) || state.stuckT > stuckTime
    if (wantManeuver && goalDist > holdTol) {
      // stuck although the costmap shows a free way, and in contact with something: it is invisible to the lidar
      if (state.stuckT > stuckTime && input.environment && input.environment.isTouchingSide) {
        markContact(rt.firstGear === -1 ? -1 : 1)
        av.points = (av.points || []).concat(state.contacts.slice(-3).map(function (c) { return [c.x, c.z] }))
      }
      var res = plan(maxExpFull)
      if (res.segs.length > 0) {
        state.active = true
        state.replans = (state.replans || 0) + 1
        state.stuckT = 0
        begin(res)
      }
    }
    if (!state.active) {
      if (rt.carrot) av.carrot = rt.carrot
      av.route = { firstGear: rt.firstGear, run: rt.run, reached: rt.reached, vLimit: rt.vLimit }
      if (params.debugDraw !== false) {
        var y0 = pos[1]
        for (var di = 2; di < rt.path.length; di += 2) {
          api.visualizeLine([rt.path[di - 2][0], y0, rt.path[di - 2][1]], [rt.path[di][0], y0, rt.path[di][1]], '#ff44ff')
        }
      }
      api.watch('av.route', 'gear ' + rt.firstGear + ' run ' + rt.run.toFixed(1) + (rt.reached ? ' goal' : ' partial'))
      return {}
    }
  }

  // --- execute manoeuvre ---
  var cur = state.segs[state.idx]
  if (state.segStart === null) {
    // a gear change must come to rest first so the odometer does not count coasting
    // (not forever: a car that chatters around zero speed never reads as stopped)
    state.restWaitT = (state.restWaitT || 0) + dt
    if (cur.g === state.prevGear || Math.abs(e.speed) < 0.4 || state.restWaitT > restWaitMax) {
      state.segStart = [pos[0], pos[2]]
      state.restWaitT = 0
    }
  }
  // a plan the car is far away from (pushed, teleported, stale): drop it and plan from the real pose
  if (state.path && state.path.length > 1) {
    var offPath = Infinity
    for (var oi = 1; oi < state.path.length; oi++) {
      var ax0 = state.path[oi - 1][0]
      var az0 = state.path[oi - 1][1]
      var abx = state.path[oi][0] - ax0
      var abz = state.path[oi][1] - az0
      var ab2 = abx * abx + abz * abz
      var tt = ab2 > 1e-9 ? Math.max(0, Math.min(1, ((pos[0] - ax0) * abx + (pos[2] - az0) * abz) / ab2)) : 0
      var dd = Math.hypot(pos[0] - (ax0 + tt * abx), pos[2] - (az0 + tt * abz))
      if (dd < offPath) offPath = dd
    }
    if (offPath > maxOffPath) {
      state.active = false
      state.route = undefined
      state.stuckT = 0
      return {}
    }
  }
  var travelled = 0
  if (state.segStart) {
    var dx = pos[0] - state.segStart[0]
    var dz = pos[2] - state.segStart[1]
    travelled = Math.sqrt(dx * dx + dz * dz)
  }
  // --- execution guard: re-plan when the real pose makes the rest of the segment collide, or when stalled ---
  if (state.segStart !== null) {
    // the guard must not be stricter than the margin the manoeuvre was planned with (escaping from contact)
    var guardM = Math.min(guardMargin, state.startMargin != null ? state.startMargin : guardMargin)
    var guardL = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + guardM
    var guardW = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + guardM
    var gHit = makeHit(av.points || [], guardL, guardW)
    var lx0 = e.left[0]
    var lz0 = e.left[2]
    var look = Math.min(2.0, Math.max(0, cur.len - travelled))
    var blockedAhead = false
    for (var gd = 0.5; gd <= look + 1e-6 && !blockedAhead; gd += 0.5) {
      var gdd = cur.g * gd
      var gth = cur.k * gdd
      var gx2 = Math.abs(cur.k) < 1e-6 ? gdd : Math.sin(gth) / cur.k
      var gy2 = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(gth)) / cur.k
      var px = pos[0] + e.fwd[0] * gx2 + lx0 * gy2
      var pz = pos[2] + e.fwd[2] * gx2 + lz0 * gy2
      var pfx = e.fwd[0] * Math.cos(gth) + lx0 * Math.sin(gth)
      var pfz = e.fwd[2] * Math.cos(gth) + lz0 * Math.sin(gth)
      if (gHit(px, pz, pfx, pfz)) blockedAhead = true
    }
    state.stallT = Math.abs(e.speed) < 0.15 ? (state.stallT || 0) + dt : 0
    var stallTime = params.stallTime != null ? params.stallTime : 1.2
    if ((blockedAhead || state.stallT > stallTime) && e.t - (state.lastReplanT || -9) > 0.6) {
      // pushing against something the costmap does not show: mark the spot ahead (in the driving direction) as occupied
      if (!blockedAhead && input.environment && input.environment.isTouchingSide) markContact(cur.g, true)
      var fix = plan(maxExpFull)
      state.lastReplanT = e.t
      state.stallT = 0
      state.replans++
      if (fix.segs.length > 0) {
        begin(fix)
        state.prevGear = cur.g
        cur = state.segs[0]
        travelled = 0
      }
    }
  }
  // hand back once the rest of the plan starts with a long forward run
  var fwdRun = 0
  // (also from the first segment: a plan that simply starts with a long forward run is a route, not a manoeuvre — creeping
  // along it at manoeuvre speed with open-loop segments is what made the car shuttle back and forth next to obstacles)
  for (var si = state.idx; si < state.segs.length && state.segs[si].g > 0; si++) fwdRun += state.segs[si].len
  fwdRun -= travelled
  var aheadFree = false
  if (fwdRun >= handback && cur.g > 0) {
    // the car must really have room ahead on its own heading, not just a plan that will get there
    var aHit = makeHit(av.points || [], ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + planMargin, ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + planMargin)
    aheadFree = true
    for (var ad = 0; ad <= handback && aheadFree; ad += 1) {
      // along the current segment's arc (what the local planner would also pick), not just straight on
      var ath = cur.k * ad
      var ax = Math.abs(cur.k) < 1e-6 ? ad : Math.sin(ath) / cur.k
      var ay = Math.abs(cur.k) < 1e-6 ? 0 : (1 - Math.cos(ath)) / cur.k
      var apx = pos[0] + e.fwd[0] * ax + e.left[0] * ay
      var apz = pos[2] + e.fwd[2] * ax + e.left[2] * ay
      if (aHit(apx, apz, e.fwd[0] * Math.cos(ath) + e.left[0] * Math.sin(ath), e.fwd[2] * Math.cos(ath) + e.left[2] * Math.sin(ath))) aheadFree = false
    }
  }
  if (aheadFree) {
    state.active = false
    state.route = undefined
    return {}
  }
  var finished = state.segStart !== null && travelled >= cur.len - 0.25
  if (finished) {
    state.prevGear = cur.g
    if (state.idx + 1 >= state.segs.length || deviates(cur)) {
      var again = plan(maxExpFull)
      state.replans++
      if (again.segs.length === 0 || state.idx + 1 >= state.segs.length) {
        state.active = false
        state.route = undefined
        if (again.segs.length === 0) return {}
      }
      if (again.segs.length > 0 && state.active) {
        begin(again)
        state.prevGear = cur.g
      }
    } else {
      state.idx++
      state.segStart = null
    }
    if (!state.active) return {}
    cur = state.segs[state.idx]
    travelled = 0
  }
  if (params.debugDraw !== false && state.path) {
    var py = pos[1]
    for (var pi = 2; pi < state.path.length; pi += 2) {
      api.visualizeLine([state.path[pi - 2][0], py, state.path[pi - 2][1]], [state.path[pi][0], py, state.path[pi][1]], '#ff44ff')
    }
    if (cur.end) api.visualizeLine(pos, [cur.end.x, py, cur.end.z], '#ff8800')
    api.visualizeLine([pos[0], py + 1.2, pos[2]], [pos[0], py + 4, pos[2]], '#ff44ff')
  }
  var remain = state.segStart ? Math.max(0, cur.len - travelled) : cur.len
  var vMax = Math.min(vMan, 0.9 + Math.sqrt(2 * 3 * remain))
  // waiting for rest before a gear change: demand zero. Once the segment has started but the car still rolls the other
  // way (momentum from the previous segment; an icy car does not stop by itself and a zero-demand brake is below the
  // actuator deadband), drive in the demanded direction: that brakes it hard and turns it around.
  var waitingForRest = state.segStart === null
  var rollingWrong = !waitingForRest && cur.g * e.speed < -0.35
  av.override = { kappa: cur.k, vDesired: waitingForRest ? 0 : rollingWrong ? cur.g * Math.min(vMax, 2.5) : cur.g * vMax }
  av.mode = 'maneuver'
  api.watch('av.maneuver', 'seg ' + state.idx + '/' + state.segs.length + ' g' + cur.g + ' k' + cur.k.toFixed(3) + ' replans ' + state.replans)
  return {}
}

// AV stack · PLAN / local motion planner (sampling-based, receding horizon).
// Candidate paths = constant-curvature turn (limited turn angle) followed by a straight, so a path can
// swing around an obstacle and then run alongside it. Each path is swept with the vehicle footprint
// (margin grows with speed) against the costmap. Cost = progress to goal, heading, required stopping
// length, clearance, smoothness. Publishes av.plan {kappa, free, freeSoft, clearance, blocked, horizon}.
// debug draw: yellow = line to goal / route carrot, dark blue = candidate fan, green = chosen path, orange = where it would hit.
// params: vehicleWidth, vehicleLength, safetyMargin, marginSpeedGain, softMargin, maxCurvature, arcCount,
//         horizonMin, horizonGain, horizonMax, comfortDecel, wProgress, wHeading, wRequired, wFree, wSoft,
//         wSmooth, wTurn, minFree, rearIgnore, marginRamp (m over which the margin grows from the current clearance), debugDraw
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  var tgt = input.target && input.target.pose && input.target.pose.position
  if (!tgt) {
    av.plan = { kappa: 0, free: 0, freeSoft: 0, clearance: 0, blocked: false, horizon: 0, noGoal: true }
    return {}
  }
  var pos = input.position
  var tdx = tgt[0] - pos[0]
  var tdz = tgt[2] - pos[2]
  av.goal = { x: tgt[0], z: tgt[2], dist: Math.sqrt(tdx * tdx + tdz * tdz) }
  // manoeuvre planner owns the controls (multi-point turn): pass its command through
  if (av.override) {
    av.plan = { kappa: av.override.kappa, vDesired: av.override.vDesired, free: 99, freeSoft: 99, clearance: 9, blocked: false, horizon: 0, override: true }
    return {}
  }
  // chase the route's carrot (global plan) when there is one, else the raw goal
  var aim = av.carrot ? [av.carrot[0], 0, av.carrot[1]] : tgt
  var gdx = aim[0] - pos[0]
  var gdz = aim[2] - pos[2]
  var gx = gdx * e.fwd[0] + gdz * e.fwd[2]
  var gy = gdx * e.left[0] + gdz * e.left[2]
  var goalDist = Math.sqrt(gx * gx + gy * gy)

  var v = Math.max(0, e.speedF)
  var margin = (params.safetyMargin != null ? params.safetyMargin : 0.5) + (params.marginSpeedGain != null ? params.marginSpeedGain : 0.05) * v
  var soft = params.softMargin != null ? params.softMargin : 1.1
  var halfW = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2 + margin
  var halfL = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2 + margin
  var kmax = params.maxCurvature || 0.115
  var count = params.arcCount || 31
  var hMin = params.horizonMin != null ? params.horizonMin : 10
  var aBrake = params.comfortDecel || 5
  // The planning horizon has to cover the stopping distance of the speed we want to drive, otherwise the free-path
  // limit (sqrt(2 * decel * horizon)) silently caps cruiseSpeed (26 m / 5 m/s^2 = 15.8 m/s).
  var cruiseV = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var hMax = params.horizonMax != null ? params.horizonMax : Math.min(150, Math.max(26, 1.1 * ((cruiseV * cruiseV) / (2 * aBrake)) + 10))
  var H = Math.min(hMax, hMin + Math.max((params.horizonGain != null ? params.horizonGain : 1.2) * v, (1.1 * v * v) / (2 * aBrake)))
  var Lreq = Math.min(H, (v * v) / (2 * aBrake) + 5)
  var wProg = params.wProgress != null ? params.wProgress : 1.0
  var wHead = params.wHeading != null ? params.wHeading : 2.0
  var wReq = params.wRequired != null ? params.wRequired : 60
  var wFree = params.wFree != null ? params.wFree : 10
  var wSoft = params.wSoft != null ? params.wSoft : 8
  var wSmooth = params.wSmooth != null ? params.wSmooth : 2.5
  var wTurn = params.wTurn != null ? params.wTurn : 1.5
  var minFree = params.minFree != null ? params.minFree : 4.5
  var ds = 0.75
  var turnAngles = [0.5, 1.15]

  // costmap into ego frame
  var pts = av.points || []
  var ox = []
  var oy = []
  for (var i = 0; i < pts.length; i++) {
    var dx = pts[i][0] - pos[0]
    var dz = pts[i][1] - pos[2]
    var px = dx * e.fwd[0] + dz * e.fwd[2]
    var py = dx * e.left[0] + dz * e.left[2]
    if (px > -halfL - soft - 3 && px < H + halfL + soft + 3 && py > -H - 4 && py < H + 4) {
      ox.push(px)
      oy.push(py)
    }
  }

  // pose along a path: turn at `kappa` for `turnLen`, then straight
  function poseAt(kappa, turnLen, s, out) {
    var sa = s < turnLen ? s : turnLen
    var th = kappa * sa
    var x
    var y
    if (Math.abs(kappa) < 1e-6) {
      x = sa
      y = 0
    } else {
      x = Math.sin(th) / kappa
      y = (1 - Math.cos(th)) / kappa
    }
    if (s > turnLen) {
      x += Math.cos(th) * (s - turnLen)
      y += Math.sin(th) * (s - turnLen)
    }
    out.x = x
    out.y = y
    out.th = th
  }
  var P = { x: 0, y: 0, th: 0 }

  // forward paths only sweep the front of the footprint: an obstacle already behind/at the tail (touching
  // start pose) must not veto driving away from it
  var rearIgnore = params.rearIgnore != null ? params.rearIgnore : 1.4
  // Start already inside the margin (parked next to a car / wall): the full margin would veto every path at s = 0 and
  // freeze the car. The margin therefore starts at the clearance the car has now and grows to the full value over
  // `marginRamp` metres — a path may not get closer than the car already is, but it may drive away.
  var hullL = halfL - margin
  var hullW = halfW - margin
  var startGap = margin + soft
  for (var sg = 0; sg < ox.length; sg++) {
    if (ox[sg] < -hullL + rearIgnore - margin) continue
    var gap = Math.max(Math.abs(ox[sg]) - hullL, Math.abs(oy[sg]) - hullW)
    if (gap < startGap) startGap = gap
  }
  var ramp = params.marginRamp != null ? params.marginRamp : 3
  function freeLength(kappa, turnLen, hw, hl) {
    var extra = hw - hullW
    var m0 = Math.max(0, Math.min(extra, startGap - 0.05))
    for (var s = 0; s <= H; s += ds) {
      var m = s >= ramp || m0 >= extra ? extra : m0 + ((extra - m0) * s) / ramp
      var hwS = hullW + m
      var hlS = hullL + m
      var hlRear = Math.max(0.3, hlS - rearIgnore)
      poseAt(kappa, turnLen, s, P)
      var ct = Math.cos(P.th)
      var st = Math.sin(P.th)
      for (var q = 0; q < ox.length; q++) {
        var rx = ox[q] - P.x
        var ry = oy[q] - P.y
        var lx = ct * rx + st * ry
        var ly = -st * rx + ct * ry
        if (lx > -hlRear && lx < hlS && ly > -hwS && ly < hwS) return Math.max(0, s - ds)
      }
    }
    return H
  }

  var prev = state.prevKappa || 0
  var prevTurn = state.prevTurn || 0
  var best = null
  var bestCost = Infinity
  var bestHard = 0
  var bestSoft = 0
  var bestTurnLen = 0
  var cand = []
  // Direct aim: turn at curvature `kappa` until the car points at the goal, then drive straight (shortest way when the
  // way is free). Returns the turn angle (rad), or 0 when the goal is on the other side / cannot be aimed at this way.
  function aimTurnAngle(kappa) {
    var ak = Math.abs(kappa)
    if (ak < 1e-6) return 0
    var gyS = kappa > 0 ? gy : -gy
    if (gyS <= 0.05 && gx > 0) return 0
    var prevF = null
    for (var th = 0.02; th <= Math.PI; th += 0.02) {
      var x = Math.sin(th) / ak
      var y = (1 - Math.cos(th)) / ak
      var f = Math.atan2(gyS - y, gx - x) - th
      while (f > Math.PI) f -= 2 * Math.PI
      while (f < -Math.PI) f += 2 * Math.PI
      if (prevF !== null && prevF > 0 && f <= 0) return th
      prevF = f
    }
    return 0
  }
  for (var a = 0; a < count; a++) {
    var kappa = count === 1 ? 0 : -kmax + (2 * kmax * a) / (count - 1)
    var aimAng = aimTurnAngle(kappa)
    var nAngles = turnAngles.length + (aimAng > 0 ? 1 : 0)
    for (var ti = 0; ti < nAngles; ti++) {
      if (Math.abs(kappa) < 1e-6 && ti > 0) continue
      var isAim = ti >= turnAngles.length
      var turnLen = Math.abs(kappa) < 1e-6 ? H : Math.min(H, (isAim ? aimAng : turnAngles[ti]) / Math.abs(kappa))
      var fHard = freeLength(kappa, turnLen, halfW, halfL)
      var fSoft = freeLength(kappa, turnLen, halfW + soft - margin, halfL + soft - margin)
      var L = fHard
      var Lpose = L
      if (isAim) {
        // judged where it reaches the goal (not far beyond it); free-length terms still use the full free path
        poseAt(kappa, turnLen, turnLen, P)
        Lpose = Math.min(L, turnLen + Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y)))
      }
      poseAt(kappa, turnLen, Lpose, P)
      var gdEnd = Math.sqrt((gx - P.x) * (gx - P.x) + (gy - P.y) * (gy - P.y))
      var progress = goalDist - gdEnd
      var herr = Math.atan2(gy - P.y, gx - P.x) - P.th
      while (herr > Math.PI) herr -= 2 * Math.PI
      while (herr < -Math.PI) herr += 2 * Math.PI
      var cost =
        -wProg * progress +
        wHead * Math.abs(herr) +
        wReq * Math.max(0, 1 - L / Lreq) +
        wFree * (1 - L / H) +
        wSoft * (1 - Math.min(fSoft, H) / H) +
        wSmooth * (Math.abs(kappa - prev) / kmax) +
        wTurn * Math.abs(kappa * turnLen)
      if (cost < bestCost) {
        bestCost = cost
        best = kappa
        bestHard = fHard
        bestSoft = fSoft
        bestTurnLen = turnLen
      }
      if (params.debugDraw !== false && a % 8 === 0 && ti === 0) cand.push([kappa, turnLen, fHard])
    }
  }
  state.prevKappa = best

  // lateral clearance of the chosen path over the distance that matters (beyond the hard margin)
  var clearance = 0
  var margins = [0.5, 1.0, 1.5, 2.5]
  var needLen = Math.min(bestHard, Lreq)
  for (var mi = 0; mi < margins.length; mi++) {
    var fm = freeLength(best, bestTurnLen, halfW + margins[mi], halfL + margins[mi])
    if (fm >= needLen - 1e-6) clearance = margins[mi]
    else break
  }

  av.plan = {
    kappa: best,
    free: bestHard,
    freeSoft: bestSoft,
    clearance: clearance,
    margin: margin,
    blocked: bestHard < minFree,
    startGap: startGap,
    horizon: H,
    required: Lreq,
    cost: bestCost,
  }
  api.watch('av.plan.kappa', Math.round(best * 1000) / 1000)
  api.watch('av.plan.free', Math.round(bestHard * 10) / 10 + ' clr ' + clearance)

  if (params.debugDraw !== false) {
    var y0 = pos[1]
    var W = { x: 0, y: 0, th: 0 }
    function world(x, y) {
      return [pos[0] + e.fwd[0] * x + e.left[0] * y, y0, pos[2] + e.fwd[2] * x + e.left[2] * y]
    }
    function drawPath(kk, tl, len, color, step) {
      var prevW = null
      for (var s = 0; s <= len + 1e-6; s += step) {
        poseAt(kk, tl, s, W)
        var wp = world(W.x, W.y)
        if (prevW) api.visualizeLine(prevW, wp, color)
        prevW = wp
      }
    }
    api.visualizeLine(pos, [aim[0], y0, aim[2]], '#ffcc00')
    for (var ci = 0; ci < cand.length; ci++) drawPath(cand[ci][0], cand[ci][1], cand[ci][2], '#3a5a9a', Math.max(4, cand[ci][2] / 3))
    drawPath(best, bestTurnLen, bestHard, '#22dd66', 2.5)
    if (bestHard < H) drawPath(best, bestTurnLen, Math.min(H, bestHard + 3), '#ff8800', 3)
  }
  return {}
}

// AV stack · PLAN / speed planner.
// v_des = min(cruise, obstacle in the path (auto-brake), obstacle right next to the car, route bends ahead, lateral acceleration, goal approach).
//  - In the path: auto-brake logic — v <= sqrt(2 * brakeDecel * (free distance - stopMargin)). Far obstacles only matter once they are within braking distance.
//  - Next to the car: only obstacles within `obstacleSlowRadius` (default 5 m) of the hull slow the car, linearly from `obstacleSlowFactor * cruiseSpeed` (touching) up to cruise (at the radius).
//    Obstacles that are farther away, or behind the car, never slow it. Set the radius to 0 to switch this off.
// Goal approach only slows for the FINAL waypoint (av.mission, else params.waypoints; otherwise every goal is final).
// The free-path (stopping distance) limit always wins over the floors.
// Publishes av.plan.vDesired / av.plan.vLimit ('cruise' | 'free' | 'near' | 'route' | 'curve' | 'goal').
// params: cruiseSpeed, minSpeed (lowest speed while driving, default 4), comfortDecel (brake decel for obstacles in the path, default 5),
//         stopMargin, obstacleSlowRadius (5), obstacleSlowFactor (speed right next to an obstacle as a fraction of cruise, default 0.5), maxLatAccel (default 9),
//         goalDecel (gentler braking used for the final approach, default 3), goalCrawlSpeed (floor while arriving, default 2), goalTolerance, vehicleWidth, vehicleLength, waypoints
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan) return {}
  var plan = av.plan
  if (plan.override) return {}
  var cruise = params.cruiseSpeed != null ? params.cruiseSpeed : 10
  var aBrake = params.comfortDecel || 5
  var aLat = params.maxLatAccel || 9
  var stopMargin = params.stopMargin != null ? params.stopMargin : 1.2
  var crawl = params.minSpeed != null ? params.minSpeed : params.crawlSpeed != null ? params.crawlSpeed : 4
  var limit = 'cruise'
  var v = cruise
  // obstacle in the path: auto-brake (free distance of the chosen path)
  var vFree = Math.sqrt(2 * aBrake * Math.max(0, plan.free - stopMargin))
  if (vFree < v) {
    v = vFree
    limit = 'free'
  }
  // obstacles right next to the car (hull distance), never farther than the slow radius, never behind
  var slowR = params.obstacleSlowRadius != null ? params.obstacleSlowRadius : 5
  if (slowR > 0 && av.points && av.points.length && av.ego) {
    var e = av.ego
    var hl = ((av.vehicle && av.vehicle.length) || params.vehicleLength || 4) / 2
    var hw = ((av.vehicle && av.vehicle.width) || params.vehicleWidth || 2) / 2
    var pos = input.position
    var dn = Infinity
    for (var i = 0; i < av.points.length; i++) {
      var dx = av.points[i][0] - pos[0]
      var dz = av.points[i][1] - pos[2]
      var lx = dx * e.fwd[0] + dz * e.fwd[2]
      if (lx < -hl) continue // behind the rear: irrelevant for a forward-driving car
      var ly = dx * e.left[0] + dz * e.left[2]
      var ex = Math.max(Math.abs(lx) - hl, 0)
      var ey = Math.max(Math.abs(ly) - hw, 0)
      var d = Math.sqrt(ex * ex + ey * ey)
      if (d < dn) dn = d
    }
    if (dn < slowR) {
      var vNear = Math.max(crawl, (params.obstacleSlowFactor != null ? params.obstacleSlowFactor : 0.5) * cruise)
      var t = Math.min(1, Math.max(0, (dn - 0.3) / Math.max(0.01, slowR - 0.3)))
      var vProx = vNear + (cruise - vNear) * t
      if (vProx < v) {
        v = vProx
        limit = 'near'
      }
    }
  }
  // bends ahead on the global route (corner speed, reachable by braking)
  if (av.route && av.route.vLimit < v) {
    v = Math.max(av.route.vLimit, crawl)
    limit = 'route'
  }
  var k = Math.abs(plan.kappa)
  if (k > 1e-4) {
    var vCurve = Math.sqrt(aLat / k)
    if (vCurve < v) {
      v = Math.max(vCurve, crawl)
      limit = 'curve'
    }
  }
  if (av.goal) {
    var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
    var wps = params.waypoints
    var isFinal = true
    if (av.mission) {
      isFinal = av.mission.isFinal
    } else if (wps && wps.length) {
      var last = wps[wps.length - 1]
      isFinal = Math.abs(av.goal.x - last[0]) < 0.05 && Math.abs(av.goal.z - last[1]) < 0.05
    }
    if (isFinal) {
      var vGoal = Math.sqrt(2 * (params.goalDecel != null ? params.goalDecel : 3) * Math.max(0, av.goal.dist - tol))
      if (vGoal < v) {
        // arriving: creep in slowly enough to stop inside the hold radius (own, lower floor than the driving minimum)
        v = Math.max(vGoal, params.goalCrawlSpeed != null ? params.goalCrawlSpeed : 2)
        limit = 'goal'
      }
    }
  }
  if (!plan.blocked && v < crawl && limit !== 'goal') v = crawl
  // The stopping-distance limit is a safety bound, not a preference: no floor (minSpeed, route/curve crawl, goal crawl)
  // may lift the speed above what can still stop within the free path (minSpeed 9.4 with 5 m free and 2 m/s² used to
  // drive at 9.4 instead of 3.9 m/s — straight into the AEB, then stop-and-go).
  if (v > vFree) {
    v = vFree
    limit = 'free'
  }
  plan.vDesired = v
  plan.vLimit = limit
  api.watch('av.vLimit', limit + ' ' + v.toFixed(1))
  return {}
}

// AV stack · PLAN / behaviour supervisor.
// Watches planner health and flags `av.needManeuver` when the local planner is blocked
// or the vehicle is stuck; holds at the final goal. Sets av.mode ('drive' | 'hold').
// debug draw: vertical mast above the car = status (green drive, orange needs manoeuvre, white hold).
// Simulated time only. params: stuckTime, blockedTime, holdAtGoal, goalTolerance
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var plan = av.plan
  if (state.stuckT === undefined) {
    state.stuckT = 0
    state.blockedT = 0
  }
  var stuckTime = params.stuckTime != null ? params.stuckTime : 1.5
  var blockedTime = params.blockedTime != null ? params.blockedTime : 0.4
  var wantsMove = (plan.vDesired || 0) > 0.8
  if (wantsMove && Math.abs(e.speed) < 0.25) state.stuckT += dt
  else state.stuckT = 0
  if (plan.blocked && Math.abs(e.speed) < 1.2) state.blockedT += dt
  else state.blockedT = 0
  av.needManeuver = state.blockedT > blockedTime || state.stuckT > stuckTime
  av.mode = av.override ? 'maneuver' : 'drive'
  var tol = params.goalTolerance != null ? params.goalTolerance : 3.5
  var finalGoal = !av.mission || av.mission.isFinal
  if (params.holdAtGoal !== false && finalGoal && av.goal && av.goal.dist < tol) {
    av.mode = 'hold'
    plan.override = false
    plan.vDesired = 0
    plan.kappa = 0
  }
  if (params.debugDraw !== false) {
    // status mast above the car: green drive, orange manoeuvre requested, white hold
    var c = av.mode === 'hold' ? '#ffffff' : av.needManeuver ? '#ff8800' : '#00ff66'
    api.visualizeLine([e.pos[0], e.pos[1] + 1.2, e.pos[2]], [e.pos[0], e.pos[1] + 4, e.pos[2]], c)
  }
  return {}
}

// AV stack · CONTROL / lateral (curvature tracking).
// steering = feed-forward(kappa_plan / kappaPerSteer) + P feedback on measured curvature,
// with a steering-rate limiter (comfort / actuator model).
// debug draw: white = commanded steering direction.
// params: kappaPerSteer, fbGain, steerRate
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var kps = params.kappaPerSteer || 0.12
  var fb = params.fbGain != null ? params.fbGain : 0.35
  var rate = params.steerRate != null ? params.steerRate : 4
  var kCmd = av.plan.kappa
  var steer = kCmd / kps
  if (Math.abs(e.speed) > 2 && av.mode !== 'reverse') {
    steer += (fb * (kCmd - e.kappa)) / kps
  }
  if (steer > 1) steer = 1
  if (steer < -1) steer = -1
  var prev = state.steer || 0
  var maxStep = rate * dt
  if (steer > prev + maxStep) steer = prev + maxStep
  if (steer < prev - maxStep) steer = prev - maxStep
  state.steer = steer
  // car2 treats exactly 0 as "no steering command" (wheel re-centres on its own)
  input.actions.steering_angle = Math.abs(steer) < 1e-4 ? 0 : steer
  av.cmdSteer = steer
  if (params.debugDraw !== false) {
    // white: commanded steering direction from the nose (4 m chord)
    var th = steer * kps * 4
    var nose = api.vec.offsetAlong(input.position, e.fwd, 2)
    var dir = [e.fwd[0] * Math.cos(th) + e.left[0] * Math.sin(th), 0, e.fwd[2] * Math.cos(th) + e.left[2] * Math.sin(th)]
    api.visualizeLine(nose, api.vec.offsetAlong(nose, dir, 4), '#ffffff')
  }
  return {}
}

// AV stack · CONTROL / longitudinal (model-based speed control with an online-identified actuator model).
// The car2 actuator turns a command u = throttle − brake into a force, so the body follows
//     a = G · u − D · sgn(v)          (G: m/s² per unit command, D: sliding/rolling friction deceleration, m/s²)
// G and D differ by orders of magnitude between bodies (reference car: G ≈ 156, D ≈ 60; a light icy car with power 2400:
// G ≈ 1200, D ≈ 1). A fixed deadband / gain only fits one of them — on the other the smallest command jumps the speed by
// metres per second per frame and the controller bang-bangs (the "jitter"). So G and D are estimated online (recursive
// least squares on the previous frame's command vs. the measured acceleration) and the controller asks for an
// acceleration: u = (a_des + D · s) / G, a_des = clamp((v_target − v) / tau + I, −maxDecel, maxAccel).
// Publishes av.actuator {G, D, u} (u = applied command; a later stage that overrides the actions must update it — the AEB does). The AEB uses it to brake with a deceleration instead of a raw command) and av.cmd.
// At rest the static friction can exceed D: a breakaway offset ramps while demanded motion does not start.
// params: tau, ki, maxAccel, maxDecel, maxThrottle, maxBrake, breakawayRate, gainInit, frictionInit, forget
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.plan || !av.ego) return {}
  var e = av.ego
  var vDes = av.plan.vDesired || 0
  var tau = params.tau != null ? params.tau : 0.35
  var ki = params.ki != null ? params.ki : 0.6
  var maxAcc = params.maxAccel != null ? params.maxAccel : 10
  var maxDec = params.maxDecel != null ? params.maxDecel : 12
  var maxThr = params.maxThrottle != null ? params.maxThrottle : 1
  var maxBrk = params.maxBrake != null ? params.maxBrake : 1
  var lam = params.forget != null ? params.forget : 0.97
  var v = e.speed
  if (state.G === undefined) {
    state.G = params.gainInit != null ? params.gainInit : 156
    state.D = params.frictionInit != null ? params.frictionInit : 60
    // RLS covariance over [G, D]
    state.P = [1e4, 0, 0, 1e3]
    state.uPrev = 0
    state.vPrev = v
    state.I = 0
    state.boost = 0
    state.samples = 0
  }
  // --- identify: last frame's command produced this frame's acceleration ---
  // a later stage (AEB) that overrode the command reports what was really applied in last frame's av.actuator.u
  if (state.lastAct && typeof state.lastAct.u === 'number') state.uPrev = state.lastAct.u
  var aMeas = dt > 1e-6 ? (v - state.vPrev) / dt : 0
  var vMid = 0.5 * (v + state.vPrev)
  var pushing = input.environment && input.environment.isTouchingSide
  // (sliding friction acts as soon as the body slides: learn from 0.12 m/s on, so a car creeping in force balance is not
  // stuck between 'too slow to learn' and 'too fast for the breakaway push')
  if (!pushing && Math.abs(state.uPrev) > 1e-4 && Math.abs(vMid) > 0.12 && state.vPrev * v > 0) {
    var x0 = state.uPrev
    var x1 = -(vMid > 0 ? 1 : -1)
    var P = state.P
    var px0 = P[0] * x0 + P[1] * x1
    var px1 = P[2] * x0 + P[3] * x1
    var den = lam + x0 * px0 + x1 * px1
    var k0 = px0 / den
    var k1 = px1 / den
    var err = aMeas - (state.G * x0 + state.D * x1)
    // robust: a collision / kerb spike must not wreck the model
    var lim = 50 + 0.5 * Math.abs(state.G * x0)
    if (err > lim) err = lim
    if (err < -lim) err = -lim
    state.G = Math.max(10, Math.min(20000, state.G + k0 * err))
    state.D = Math.max(0, Math.min(300, state.D + k1 * err))
    var n0 = (P[0] - k0 * px0) / lam
    var n1 = (P[1] - k0 * px1) / lam
    var n2 = (P[2] - k1 * px0) / lam
    var n3 = (P[3] - k1 * px1) / lam
    // keep the covariance bounded (forgetting without excitation blows it up)
    state.P = [Math.min(n0, 1e5), n1, n2, Math.min(n3, 1e4)]
    state.samples++
  }
  // Rescue path: the command clearly dominates friction and the response is far larger than the model predicts
  // (G underestimated — e.g. learned while pushing against a slope, or while the speed sign flipped every frame, where
  // the RLS is gated off). Pull G towards the observed gain directly so the controller stops saturating.
  // Only for a saturated command (that is the failure mode); collisions also produce big accelerations and must not pump G.
  if (!pushing && Math.abs(state.uPrev) > 0.3 && aMeas * state.uPrev > 0 && Math.abs(aMeas) > 3 * state.D + 10) {
    var gObs = Math.abs(aMeas / state.uPrev)
    if (gObs > 1.5 * state.G) state.G = Math.min(20000, state.G + 0.3 * (gObs - state.G))
  }
  var G = state.G
  var D = state.D

  // --- control ---
  var u = 0
  var holding = Math.abs(vDes) < 0.05 && Math.abs(v) < 0.3
  if (holding) {
    state.I = 0
    state.boost = 0
  } else {
    var errV = vDes - v
    // integral (acceleration units) only while not saturated, so steady errors (slope, model error) vanish
    var aDes = errV / tau + state.I
    if (aDes > maxAcc) aDes = maxAcc
    if (aDes < -maxDec) aDes = -maxDec
    if (aDes > -maxDec && aDes < maxAcc) state.I = Math.max(-3, Math.min(3, state.I + ki * errV * dt))
    // never brake through zero within one frame: the deceleration that stops the car this frame is the most we ask for
    if (Math.abs(vDes) < 0.05) {
      var stopA = Math.abs(v) / Math.max(dt, 1e-3)
      if (v > 0 && aDes < -stopA) aDes = -stopA
      if (v < 0 && aDes > stopA) aDes = stopA
    }
    // friction feed-forward in the direction of travel (at rest: of the wanted motion)
    var s = Math.abs(v) > 0.3 ? (v > 0 ? 1 : -1) : aDes > 0 ? 1 : aDes < 0 ? -1 : 0
    var fric = D * s
    // at rest, friction helps braking: no reverse push needed to stay stopped
    if (Math.abs(v) <= 0.3 && Math.abs(vDes) < 0.05) fric = 0
    u = (aDes + fric) / G
    // breakaway: demanded motion does not start (static friction > D) -> ramp an extra push
    var want = Math.abs(vDes) > 0.3
    // far below the demanded speed and not gaining (static friction / force balance the model does not explain yet)
    var stuck = want && vDes * v < Math.min(1, 0.4 * Math.abs(vDes)) && vDes * aDes > 0 && aMeas * (vDes > 0 ? 1 : -1) < 0.5
    if (stuck) state.boost = Math.min(1, state.boost + (params.breakawayRate != null ? params.breakawayRate : 0.5) * dt)
    // keep the push until the car really drives (else it jerks, stops, ramps again); then relax it slowly
    else if (!want || vDes * v >= Math.min(1, 0.4 * Math.abs(vDes))) state.boost = Math.max(0, state.boost - 0.5 * dt)
    if (state.boost > 0 && want) u += (vDes > 0 ? 1 : -1) * state.boost
    // stopping: never push along the direction of travel (friction alone may decelerate harder than maxDecel — fine)
    if (Math.abs(vDes) < 0.05 && u * v > 0) u = 0
  }
  if (u > maxThr) u = maxThr
  if (u < -maxBrk) u = -maxBrk
  state.uPrev = u
  state.vPrev = v
  input.actions.throttle = u > 0 ? u : 0
  input.actions.brake = u < 0 ? -u : 0
  // mailbox: stages after this one write the command they actually applied into av.actuator.u
  av.actuator = { G: G, D: D, samples: state.samples, u: u }
  state.lastAct = av.actuator
  av.cmd = { throttle: input.actions.throttle, brake: input.actions.brake }
  api.watch('av.throttle', 'u ' + u.toFixed(3) + ' G ' + G.toFixed(0) + ' D ' + D.toFixed(1) + ' vd ' + vDes.toFixed(1))
  return {}
}

// AV stack · SAFETY / autonomous emergency braking (independent monitor, own sensing).
// Runs after control and may only reduce throttle / add brake. Uses a smaller margin while the manoeuvre planner is driving (it already keeps swept clearance).
// Brakes with a deceleration (aebDecel), turned into a command with the actuator model the longitudinal stage identified
// (av.actuator {G, D}): a raw brake value means 360 m/s² on a light, powerful car and flips its speed within a frame.
// Footprint from av.vehicle (look-ahead starts at the nose, spread covers the body width).
// debug draw: dark gold = AEB look-ahead, red = AEB triggered.
// params: aebDecel, aebMargin, aebHalfWidth
function transform(input, dt, params, state, api) {
  var av = input.av
  if (!av || !av.ego) return {}
  var e = av.ego
  if (e.speed < 0.8) {
    av.aeb = false
    return {}
  }
  var a = params.aebDecel || 7
  var margin = params.aebMargin != null ? params.aebMargin : 1.0
  if (av.mode === 'maneuver') margin = 0.2
  var len = (av.vehicle && av.vehicle.length) || params.vehicleLength || 4
  var wid = (av.vehicle && av.vehicle.width) || params.vehicleWidth || 2
  var hw = params.aebHalfWidth != null ? params.aebHalfWidth : Math.max(0.9, wid / 2 - 0.1)
  var need = (e.speed * e.speed) / (2 * a) + margin
  var origin = api.vec.offsetAlong(input.position, e.fwd, len / 2 + 0.3)
  var hit = api.raycastSpread(origin, e.fwd, need + 1, hw, 5, { visualize: false })
  av.aeb = false
  var drawOn = params.debugDraw !== false
  if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, need), '#b8860b')
  if (hit.hit && hit.distance < need) {
    if (drawOn) api.visualizeLine(origin, api.vec.offsetAlong(origin, e.fwd, hit.distance), '#ff0000')
    av.aeb = true
    // deceleration needed to stop before the hit (at least aebDecel), never more than stops the car within this frame
    var room = Math.max(0.1, hit.distance - 0.2 * margin)
    var dec = Math.max(a, (e.speed * e.speed) / (2 * room))
    dec = Math.min(dec, e.speed / Math.max(dt, 1e-3))
    var act = av.actuator
    var u
    if (act && act.G > 0) u = (-dec + act.D) / act.G
    else u = -Math.min(1, 0.3 + (need - hit.distance) / need)
    var cur = (input.actions.throttle || 0) - (input.actions.brake || 0)
    if (u < cur) {
      input.actions.throttle = u > 0 ? u : 0
      input.actions.brake = u < 0 ? Math.min(1, -u) : 0
      // tell the longitudinal controller what was really applied (its actuator identification)
      if (act) act.u = input.actions.throttle - input.actions.brake
    }
    api.watch('av.aeb', Math.round(hit.distance * 10) / 10 + ' m dec ' + dec.toFixed(1))
  }
  return {}
}
